window.JASTROW_CHUNKS[41]={"16400":{"h":"מִקְלָה","r":"M02424","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lam. II, 10</span>.—[<span class=\"citation\">B. Mets. 74ᵃ</span> <span dir=\"rtl\">מחוסר מקלה</span>, v. <a href=\"#\" data-headword=\"קָלִי ²\"><span dir=\"rtl\">קְלֵי</span> II</a>.]</div>","alt":[]},"16401":{"h":"מַקְלוֹט","r":"M02425","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָלַט\">קָלַט</a>) <i>bag</i> for collecting the excrements of working cattle <span class=\"citation\">Y. B. Kam. II, beg. 2ᵈ</span>. <span class=\"citation\">Kel. XVI, 7</span>, v. <a href=\"#\" data-headword=\"מַלְקוֹט\">מַלְקוֹט</a>.</div>","alt":[]},"16402":{"h":"מקלופין","r":"M02426","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Num. VI, 4</span> <span dir=\"rtl\">מגופנין מַ׳</span>, read <a href=\"#\" data-headword=\"מקלופין\">מִקְּלוֹפִין</a>, and strike out <span dir=\"rtl\">מגופנין</span>, as a gloss to <span dir=\"rtl\">מגופנא</span>; v. <a href=\"#\" data-headword=\"קְלוֹפָא\">קְלוֹפָא</a></div>","alt":[]},"16403":{"h":"מִקְלָט","r":"M02427","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>refuge</i>, esp. for the unintentional man-slayer. <span class=\"citation\">Macc. II, 4</span>. <span class=\"citation\">Ib. 6</span> <span dir=\"rtl\">אחד שוגג … מקדימין לערי מ׳</span> both the innocent and the willful slayers go temporarily to the place of refuge; <span class=\"citation\">Sifré Num. 160</span>. <span class=\"citation\">Macc. II, 8</span> <span dir=\"rtl\">רוצח שגלה לעיר מִקְלָטוֹ</span> a man-slayer who arrives at his place of refuge; a. fr.</div>","alt":[]},"16404":{"h":"מַקְלִיעֲתָא","r":"M02428","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (קְלַע II) <i>braid, plait</i>. <span class=\"citation\">Y. Sabb. VI, 7ᵈ</span> bot. <span dir=\"rtl\">הות מזבנה מ׳ דרישה וכ׳</span> she sold the plait of her head (hair), and gave (the proceeds) to him (Akiba), that he might study the Law; <span class=\"citation\">Y. Sot. IX, end, 24ᶜ</span> <span dir=\"rtl\">קְלִיעֵתָא דשערה</span>.</div>","alt":[]},"16405":{"h":"מִקְלָעָה","r":"M02429","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"מַקְלִיעֲתָא\">preced.</a>) <i>braids, nets.</i> <span class=\"citation\">Yoma VI, 7</span>; v., however, <a href=\"#\" data-headword=\"מַקֵּל\">מַקֵּל</a>.</div>","alt":["מִקְלָעוֹת"]},"16406":{"h":"מְקָם","r":"M02430","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קוּם\">קוּם</a>) </div><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"מַעֲמָד\">מַעֲמַד</a>, <i>standing, attendance, office</i>. <span class=\"citation\">Targ. I Kings X, 5</span>. <span class=\"citation\">Targ. Is. XXII, 19</span> ed. Lag. (ed. <a href=\"#\" data-headword=\"מְקוּמָא\">מְקוּמָ׳</a>, <span dir=\"rtl\">מְקוֹמָ׳</span>).</div><div class=\"sense\"><b>—2)</b> <i>that which is placed before the guest, portion, plate</i>. <span class=\"citation\">Esth. R. to I, 4</span>, v. <a href=\"#\" data-headword=\"קִינָרָס\">קִינָרָס</a>.</div>","alt":["מְקָמָא I"]},"16407":{"h":"מְקָמָא II","r":"M02431","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קוּם\">קוּם</a>; v. <a href=\"#\" data-headword=\"יְקוּם\">יְקוּם</a>; cmp. <span class=\"citation\">Gen. XXIII, 17</span>; <span class=\"citation\">20</span>) <i>acquisition, bought object, thing</i>. <span class=\"citation\">Y. Ned. XI, 42ᶜ</span> bot. <span dir=\"rtl\">דו יב לה מ׳ טבא</span> when he allows her a good bargain. <span class=\"citation\">Cant. R. to VIII, 9</span> <span dir=\"rtl\">למזבן מְקוּמָא</span> to buy some goods.—<span class=\"citation\">Targ. Y. Ex. XXII, 7</span>; <span class=\"citation\">10</span> מקמתא Ar. (ed. <a href=\"#\" data-headword=\"עִיסְקָא\">עיסקא</a>; h. text <span dir=\"rtl\">מלאכת</span>).—<span class=\"citation\">Gen. R. s. 73</span> <span dir=\"rtl\">מאן אכל הדא מקמתא … מאן תבר הדא מ׳</span> who ate this thing (dish, v. <a href=\"#\" data-headword=\"מְקָם\"><span dir=\"rtl\">מְקָמָא</span> I</a>, 2)? who broke this thing (or plate)?—Constr. <a href=\"#\" data-headword=\"מְקָמְתָּא\">מִקְמַת</a>, <a href=\"#\" data-headword=\"מִיקְמַת\">מִיקְמַת</a>. Y. Erub. III, 21ᵇ top; Y. Gitt. VII, end, 49ᵃ <span dir=\"rtl\">מ׳ פלן</span> an estate bearing the name of a certain person; Y. Kidd. III, 64ᵃ top <a href=\"#\" data-headword=\"מוֹקְמַת־\">מוקמת</a>; <span class=\"citation\">Y. Maas. Sh. V, 56ᵇ</span> bot. <a href=\"#\" data-headword=\"מְקָמְתָּא\">מקמת</a>.</div>","alt":["מְקָמָה","מְקָמְתָּא"]},"16408":{"h":"מַקְמֵק","r":"M02432","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְקַק\">מְקַק</a></div>","alt":[]},"16409":{"h":"מְקָמְתָּא","r":"M02433","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְקָמָא II\"><span dir=\"rtl\">מְקָמָא</span> II</a></div>","alt":["מִקְמַת","מִיקְמַת"]},"16410":{"h":"מִקְנֶה","r":"M02434","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>property</i>, esp. <i>cattle</i>. <span class=\"citation\">Num. R. s. 22</span> <span dir=\"rtl\">היה להם מ׳ גדול</span> they had a large stock of cattle; a. e.</div>","alt":[]},"16411":{"h":"מַקְנִיתָא","r":"M02435","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"קָנֵי\">קָנֵי</a>) <i>a bundle of reeds</i>. Y. Maas. Sh. IV, end, 55ᶜ <span dir=\"rtl\">מ׳ מרגלתא</span> the bundle of reeds (seen in an alleged dream) means the bolster at the bottom of the bed.</div>","alt":["מַקְנִיתָה"]},"16412":{"h":"מִקְפֶּה","r":"M02436","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, (<a href=\"#\" data-headword=\"קָפָה\">קָפָה</a>) <i>a stiff mass</i> of grist, oil and onions. <span class=\"citation\">Ned. VI, 10</span>. <span class=\"citation\">Ḥull. 14ᵇ</span>. <span class=\"citation\">Succ. II, 9</span> <span dir=\"rtl\">משתסרח המ׳</span> when a stiff dish gets spoiled. <span class=\"citation\">Ib. 29ᵃ</span> <span dir=\"rtl\">מ׳ של גריסין</span> a pulp of grist; Y. ib. II, end, 53ᵇ <span dir=\"rtl\">מִקְפַּת גריסין</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מכפה של כל דבר</span> (corr. acc.) a pulp of anything; a. fr.</div>","alt":["מִקְפָּה"]},"16413":{"h":"מַקְּפָנָא","r":"M02437","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נְקַף II) </div><div class=\"sense\"><b>1)</b> <i>surrounding, circumvallation</i>. <span class=\"citation\">Targ. Lam. II, 8</span> (h. text <a href=\"#\" data-headword=\"חֵיל I\">חֵל</a>).</div><div class=\"sense\"><b>—2)</b> <i>going around</i>; <span dir=\"rtl\">משיריין מ׳</span> <i>nomadic camps, freebooters</i>. <span class=\"citation\">Targ. O. Num. XXXIII, 55</span> <span dir=\"rtl\">מש׳ מקפנכין</span> freebooters surrounding you.</div>","alt":[]},"16414":{"h":"מֻקְצֶה","r":"M02438","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Lev. 658</span>, v. <a href=\"#\" data-headword=\"מוּקְצֶה\">מוּקְצֶה</a> 3.</div>","alt":[]},"16415":{"h":"מִקְצוֹעַ","r":"M02439","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>corner, angle</i>. <span class=\"citation\">Tam. III, 3</span>; <span class=\"citation\">Yoma 15ᵇ</span> <span dir=\"rtl\">מ׳ צפונית מערבית</span> the corner of the north-western side of the Temple.</div><div class=\"sense\"><b>—2)</b>  = <a href=\"#\" data-headword=\"מוּקְצֶה\">מוּקְצֶה</a>, <i>store</i>. <span class=\"citation\">Men. 54ᵇ</span>; <span class=\"citation\">55ᵃ</span>, v. <a href=\"#\" data-headword=\"מוּקְצֶה\">מוּקְצֶה</a>.—<span class=\"citation\">B. Bath. X, 8</span> (<span class=\"citation\">175ᵇ</span>) <span dir=\"rtl\">שאין מ׳ בכל התורה כולה גדול מהן</span> Ms. M. (v. Rabb. D. S. a. l. note) for there is no store (of wisdom) in the entire Law richer than these (civil laws); <span class=\"citation\">Ber. 63ᵇ</span>.—Pl. <span dir=\"rtl\">מִקְצוֹעִין</span>. <span class=\"citation\">Tosef. Ḥag. I, 9</span> <span dir=\"rtl\">מִקְצוֹעֵי תורה גופי וכ׳</span> stores of the law, bodies of Halakhoth; Tosef. Erub. XI (VIII), 24 <span dir=\"rtl\">מוקצעי</span> ed. Zuck. (Var. <span dir=\"rtl\">מקצועי</span>).</div>","alt":[]},"16416":{"h":"מַקְצוּעַ","r":"M02440","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> מ׳ של דבילה <i>a tool for cutting fig-cakes, knife</i> or <i>saw</i>. <span class=\"citation\">Tosef. Sabb. XIV</span> (<span class=\"citation\">XV), 1</span> (ed. Zuck. <a href=\"#\" data-headword=\"מִקְצוֹעַ\">מִקְצוֹעַ</a>); <span class=\"citation\">Sabb. 123ᵇ</span>; Y. ib. XVII, beg. 16ᵃ.—Pl. <span dir=\"rtl\">מַקְצוּעוֹת</span>, v. <a href=\"#\" data-headword=\"מַקְצוּעָה\">next w.</a></div>","alt":[]},"16417":{"h":"מַקְצוּעָה","r":"M02441","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַקְצוּעַ\">preced.</a> wds.) <i>stored fruits</i>, esp. <i>fig</i>-<i>cake.</i> <i>—</i> Pl. <span dir=\"rtl\">מַקְצוּעוֹת</span>. <span class=\"citation\">Ned. VIII, 4</span> (<span class=\"citation\">61ᵇ</span>) <span dir=\"rtl\">עד שיקפלו המ׳</span> (<span dir=\"rtl\">שיקפילו</span>, <span dir=\"rtl\">שיכפילו</span>) up to the time when people lay the figs in layers; [oth. opin.: people fold up the <i>knives</i> (v. <a href=\"#\" data-headword=\"מַקְצוּעַ\">preced.</a>) to store them away; oth. opin.: people fold up the <i>matting</i> on which the figs are dried before they are stored]. Ib. 62ᵃ. <span class=\"citation\">Tosef. Dem. I, 3</span> <span dir=\"rtl\">משיקפלו המַקְצָעוֹת</span>; Y. ib. I, beg. 21ᶜ <span dir=\"rtl\">המקצועות</span>.</div>","alt":[]},"16418":{"h":"מִקְצָת","r":"M02442","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>a part</i>; (adv.) <i>partially, in some cases</i>. <span class=\"citation\">Shebu. VI, 3</span> <span dir=\"rtl\">הואיל והודה לו מ׳ ממין וכ׳</span> since he has admitted a part of what is comprised in the claim (empty ‘casks’ against the claim of ‘pitchers of oil’). Ib. <span dir=\"rtl\">הודה במִקְצַת כלים</span> if he admits that he owes a portion of the vessels claimed.—<span class=\"citation\">B. Mets. 3ᵃ</span>, a. fr. <span dir=\"rtl\">מודה</span> (<a href=\"#\" data-headword=\"ב\">ב</a>)<span dir=\"rtl\">מ׳ הטענה ישבע</span> he who admits a portion of the claim must make oath. Y. Shebu. VII, beg. 38ᵇ <span dir=\"rtl\">לפי שנהנה מ׳ ומהנה מ׳ וכ׳</span> because he is benefitted to a certain extent and benefits (the owner) to a certain extent, he must swear in some cases and pay damage in other cases. Sifra Sh’mini, Par. 9, ch. XI <span dir=\"rtl\">טמאת מ׳ וטהרת מ׳</span> you make it possible to declare (the seeds) unclean in some cases and clean in others. <span class=\"citation\">Ab. V, 8</span> <span dir=\"rtl\">מִקְצָתָן מעשרין ומקצתן וכ׳</span> if a part of the people give tithes and a part give not, v. <a href=\"#\" data-headword=\"בַּצּוֹרֶת\">בַּצּוֹרֶת</a>. <span class=\"citation\">Koh. R. to VII, 27</span>, a. e. <span dir=\"rtl\">מ׳ הנפש ככל הנפש</span> loss of a part of one’s life (pain, loss of property &amp;c.) is considered like a sacrifice of one’s entire life; a. fr.—Ch. v. <a href=\"#\" data-headword=\"קְצָת\">קְצָת</a>.</div>","alt":[]},"16419":{"h":"מָקַק","r":"M02443","html":"<div class=\"sense\"><i>to soften</i>.</div><div class=\"sense\"><b>Nif. נִמַּק  נִמּוֹק</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"נִימוֹסָא\">נִימּ׳</a> <i>to be softened; to decay; to be sqashed beyond recognition</i>. <span class=\"citation\">Nidd. X, 4</span> <span dir=\"rtl\">עד שיִמּוֹק הבשר</span> until decay has set in. <span class=\"citation\">Bicc. I, 8</span> <span dir=\"rtl\">נִמַּקּוּ</span> if the first fruits became decayed. Sifra B’ḥuck., Par. 2, ch. VIII (ref. to <span class=\"citation\">Lev. XXVI, 39</span>) <span dir=\"rtl\">אינו אומר יִמַּקּוּ אלא יִמַּסּוּ</span> it does not merely mean ‘they shall decay’ (when a portion remains sound), but ‘they shall dissolve’ (v. <span class=\"citation\">Macc. 24ᵃ</span> bot.). <span class=\"citation\">Nidd. III, 4</span> <span dir=\"rtl\">נִימּוֹק הולד וכ׳</span> the embryo may have been mashed (mixed up with the blood) before it was passed. Y. ib. III, end, 51ᵃ <span dir=\"rtl\">נִימּוֹקָּה שלייתו וכ׳</span> the placenta was mashed. Bab. <span class=\"citation\">ib. 27ᵃ</span> <span dir=\"rtl\">אינו דומה נמוק פעם וכ׳</span> there is no comparison between one presumption that the embryo was mashed and two such suppositions (that the placenta of one embryo and the embryo of another placenta were mashed). <span class=\"citation\">R. Hash. III, 8</span> <span dir=\"rtl\">היו נִימּוֹקִּים</span> they decayed (from the serpent’s bites), opp. <span dir=\"rtl\">מתרפאין</span>; a. e.—Tanḥ. Noah 10 <span dir=\"rtl\">נמק יסודו</span>; Yalk. Dan. 1060 <span dir=\"rtl\">נימק סידו</span>, v. infra.</div></div><div class=\"sense\"><b>Hif. הֵמֵק</b> <div class=\"sense\"><b>1)</b> <i>to squash</i>. Y. Ab. Zar. II, 40ᶜ bot. <span dir=\"rtl\">שלא תָמֵיק וכ׳</span> lest she may squash the embryo in her womb.</div><div class=\"sense\"><b>—2)</b> <i>to enervate, cause consumption.</i> <span class=\"citation\">Keth. VII, 10</span> <span dir=\"rtl\">מְמַקְּתוֹ</span> she (the intercourse with her) will enervate him (the leper).</div></div><div class=\"sense\"><b>Hof. הוּמַק</b> <div class=\"sense\"><i>to be crumbled, to dissolve</i>. <span class=\"citation\">Snh. 92ᵇ</span> <span dir=\"rtl\">ה׳ סורו</span> (Rashi) his (Nebucadnezzar’s) pride was crumbled (he confessed his wrong), v. <a href=\"#\" data-headword=\"מָרַק\">מָרַק</a>; (ed. <span dir=\"rtl\">ה׳ סודו</span> its (the kiln’s) foundation was crumbled (from the heat); [oth. vers. <span dir=\"rtl\">ה׳ סידו</span> the lime in it melted; Tanḥ. Noah 10 <span dir=\"rtl\">נמק יסודו</span>; Yalk. Dan. 1060 <span dir=\"rtl\">נימק סידו</span>].</div></div><div class=\"sense\"><b>Hithpalp. הִתְמַקְמֵק</b> <div class=\"sense\"><i>to be crushed, to pine</i>. <span class=\"citation\">Taan. 25ᵇ</span> <span dir=\"rtl\">עד שיִתְמַקְמֵק ויצטער</span> until he is made submissive (by starvation) and feels pain.</div></div>","alt":[]},"16420":{"h":"מְקַק","r":"M02444","html":"<div class=\"sense\"><b>Ithpalp. אִתְמַקְמֵק</b> <div class=\"sense\"><b>1)</b> <i>to pine away, be weakened</i>. <span class=\"citation\">Targ. Y. Deut. XXXI, 18</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to decay, melt</i>. <span class=\"citation\">Targ. Job XIV, 10</span> (h. text <span dir=\"rtl\">חלש</span>). <span class=\"citation\">Targ. Ps. LXXIII, 8</span> (h. text <span dir=\"rtl\">ימיקו</span>).</div><div class=\"sense\"><b>—3)</b> <i>to sneeze</i>, v. infra.</div></div><div class=\"sense\"><b>Ithpe. אִיתְמְקַק</b> <div class=\"sense\"> (cmp. <span dir=\"rtl\">מוג</span>, <i>Ithpol</i>.) </div><div class=\"sense\"><b>1)</b> <i>to be languid, to stretch one’s self</i>. <span class=\"citation\">Targ. I Kings XVII, 21</span>.</div><div class=\"sense\"><b>—2)</b>  [<i>to collapse</i>; v. <a href=\"#\" data-headword=\"מַרְפֵּא\">מַרְפֵּא</a> a. <a href=\"#\" data-headword=\"עָטַשׁ\">עָטַשׁ</a>,] <i>to sneeze</i>. <span class=\"citation\">Targ. II Kings IV, 35</span> ed. Lag. (ed. Ven. I אִתְמוֹקַק <i>Ithpol</i>. of <a href=\"#\" data-headword=\"מוּק\">מוּק</a>; Regia <a href=\"#\" data-headword=\"מְקַק\">אִתְמַקְמַק</a>; ed. <span dir=\"rtl\">אתמורק</span>; h. text <span dir=\"rtl\">ויזורר</span>; Pesh. <a href=\"#\" data-headword=\"פְּקַק\">אתפקק</a>).</div></div>","alt":[]},"16421":{"h":"מֶקֶק","r":"M02445","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִמְקָק\">מִמְקָק</a></div>","alt":[]},"16422":{"h":"מְקָק","r":"M02446","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מֶקֶק\">preced.</a>) <span dir=\"rtl\">מ׳ דסיפרי</span> <i>book-worm</i>. <span class=\"citation\">Sabb. 90ᵃ</span></div>","alt":[]},"16423":{"h":"מַקְקָא","r":"M02447","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מְקַק\">מְקַק</a>, <i>Ithpe.</i>) <i>sneezing.</i> <i>—</i> Pl. <span dir=\"rtl\">מַקְקִין</span>, <span dir=\"rtl\">מְקִי׳</span>. <span class=\"citation\">Targ. Job XLI, 10</span> מַקְקוֹי Regia (Ms. Var. <span dir=\"rtl\">מְקִיקוֹי</span>; ed. <span dir=\"rtl\">זְרִירוֹי</span>; h. text <span dir=\"rtl\">עטישות־</span>).</div>","alt":["מְקִיקָא"]},"16424":{"h":"מֵקַר","r":"M02448","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵיקַר\">מֵיקַר</a></div>","alt":[]},"16425":{"h":"מַקַר","r":"M02449","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>cooling</i>; <span dir=\"rtl\">כיף מ׳</span> <i>shady rock</i>. <span class=\"citation\">Targ. Is. XXV, 5</span> (h. text <a href=\"#\" data-headword=\"עָב I\">עב</a>).</div>","alt":[]},"16426":{"h":"מַקְרָא","r":"M02450","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Μακρός) <i>Macra</i>. <span class=\"citation\">Gen. R. s. 46</span> [read:] <span dir=\"rtl\">מסתברא הדא דמ׳</span> this interpretation of M. is plausible; (<span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">דנְגָדָא</span>).</div>","alt":[]},"16427":{"h":"מְקֹרָא","r":"M02451","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קרי ²\">קָרָא</a>) <i>being called, summons</i>. <span class=\"citation\">Y. Ber. II, 4ᵈ</span> top; <span class=\"citation\">Y. Meg. I, 71ᶜ</span> (play on <span dir=\"rtl\">מקורך</span>, <span class=\"citation\">Prov. V, 18</span>) <span dir=\"rtl\">יהי מְקֹרָאֲךָ לקבר וכ׳</span> blessed be thy being summoned to the grave; <span class=\"citation\">Yalk. Prov. 937</span>; <span class=\"citation\">Koh. R. to IV, 17</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בבית מקוראך תהיה ברוך</span> be blessed in the house to which thou wilt be called.</div>","alt":["מְקוֹרָא"]},"16428":{"h":"מִקְרָא","r":"M02452","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>call, convocation</i>. Sifra Emor, Par. 11, ch. XIV <span dir=\"rtl\">אלא אם עשאו מ׳ קדש</span> unless one made it (the Day of Atonement) a holy call (observed it). Ib. ch. XIII, Par. 11 <span dir=\"rtl\">בני ישראל מ׳ קדש וכ׳</span> the sons of Israel are a holy convocation (called to celebrate the festivals) &amp;c. Mekh. Bo. s. 9; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>reading</i>, esp. <i>the reading from the Scriptures</i>. <span class=\"citation\">Ber. II, 1</span> <span dir=\"rtl\">זמן במ׳</span> the time for reading the sh’mʿa. <span class=\"citation\">Meg. 3ᵃ</span>, a. fr. <span dir=\"rtl\">מ׳ מגילה</span> the recitation of the Book of Esther. <span class=\"citation\">Tosef. Ber. II, 20</span> <span dir=\"rtl\">יש שם מ׳ ותפלה</span> reading the Scriptures and prayer are permitted there; <span class=\"citation\">Sabb. 10ᵃ</span>; a. e.—Meg. l. c. (ref. to <span class=\"citation\">Neh. VIII, 8</span> <span dir=\"rtl\">ויקראו מ׳</span>) <span dir=\"rtl\">זו</span> this means the reading of the text; <span class=\"citation\">Ned. 37ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>pronunciation, vocalization</i>; <span dir=\"rtl\">מ׳ סופרים</span> the traditional vocalization of the Scripture texts. the traditional vocalization of the Scripture texts. Ib.</div><div class=\"sense\"><b>—4)</b> <i>teaching the Bible, primary instruction</i>. Ib. IV, 3 <span dir=\"rtl\">לא ילמדנו מ׳</span> he must not teach him Bible, contrad. to <a href=\"#\" data-headword=\"מִדְרָשׁ\">מדרש</a> &amp;c. Ib. 36ᵇ bot. <span dir=\"rtl\">במקום … על המ׳</span> where is it customary to take remuneration for teaching the Bible. <span class=\"citation\">Y. Meg. III, beg. 73ᵈ</span>; <span class=\"citation\">Y. Keth. XIII, beg. 35ᶜ</span> בית ספר למ׳ וכ׳ Beth Sepher was the school for Bible, Beth Talmud for Mishnah. <span class=\"citation\">Lev. R. s. 2</span>, beg. <span dir=\"rtl\">נכנסין למ׳</span> enter the primary school; a. fr.</div><div class=\"sense\"><b>—5)</b> <i>the Scriptures</i>. <span class=\"citation\">Y. Taan. IV, 68ᵃ</span> bot. <span dir=\"rtl\">חיזרנו על כל המ׳</span>, v. <a href=\"#\" data-headword=\"חָזַר\">חָזַר</a>; a. fr.</div><div class=\"sense\"><b>—6)</b> <i>Biblical verse, text</i>. <span class=\"citation\">Sot. V, 2</span> <span dir=\"rtl\">שאין לו מ׳ מן התורה וכ׳</span> there is for it no passage in the Torah intimating that it is unclean. Ib. <span dir=\"rtl\">מביא לו מ׳ מן וכ׳</span> produces for it a Biblical text in evidence &amp;c. <span class=\"citation\">Yeb. 11ᵇ</span>, a. e. <span dir=\"rtl\">אין מ׳ יוצא מידי פשוטו</span> a Bible verse can never lose its literal sense (although its meaning may be extended by the methods of interpretation). <span class=\"citation\">Snh. 34ᵃ</span>, a. e. <span dir=\"rtl\">מ׳ אחד יוצא וכ׳</span>, v. <a href=\"#\" data-headword=\"טַעַם\">טַעַם</a>. <span class=\"citation\">Ib. 101ᵃ</span> <span dir=\"rtl\">מ׳ זה מעצמו נדרש</span> this verse must be interpreted from its own wording. Ib. bot. <span dir=\"rtl\">מנין לך … מ׳ אני דורש</span> how do you know this?… I interpret Bible verses; a. fr.—Pl. <span dir=\"rtl\">מִקְרָאוֹת</span>, <span dir=\"rtl\">מִקְרָיוֹת</span>. <span class=\"citation\">Men. 19ᵇ</span>; <span class=\"citation\">Zeb. 63ᵇ</span>; <span class=\"citation\">Sot. 14ᵇ</span> <span dir=\"rtl\">כ&quot;מ שאתה מוצא שני מ׳ אחד וכ׳</span> wherever there are two possible interpretations of two parallel expressions one of which contradicts the other, and one of which confirms the other &amp;c. <span class=\"citation\">Yoma 52ᵃ</span> bot., v. <a href=\"#\" data-headword=\"הֶכְרַע\">הֶכְרַע</a>. <span class=\"citation\">Y. Snh. VIII, 26ᶜ</span> top <span dir=\"rtl\">זה אחד משלשה מ׳</span> this is one of the three passages where the Law speaks metaphorically; Y. Keth. IV, 28ᶜ top; a. fr.</div>","alt":[]},"16429":{"h":"מִקְרְבָא","r":"M02453","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִקְרוֹבוּתָא\">מִקְרוֹבוּתָא</a></div>","alt":[]},"16430":{"h":"מקרוא","r":"M02454","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַקְרוֹאֶלַפְרוֹס\">next w.</a></div>","alt":[]},"16431":{"h":"מַקְרוֹאֶלַפְרוֹס","r":"M02455","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μακρο-ἔλαφρος, a made-up word) <i>Macro-elaphros</i> (<i>Tall-Lightfoot</i>). <span class=\"citation\">Gen. R. s. 65</span> <span dir=\"rtl\">והיתה שם … מקרוא לפרוס</span> (corr. acc.) and a woman was there who had a son that was a dwarf, but whom she called M. and said, <span dir=\"rtl\">בני מ׳</span> my son is tall and lightfooted (fit for the body guard); <span class=\"citation\">Cant. R. to II, 15</span> <span dir=\"rtl\">מיקרו ליפארוס</span> (corr. acc.); <span class=\"citation\">Yalk. Jer. 332</span> <a href=\"#\" data-headword=\"מקרולפוס\">מקרולפוס</a>, <a href=\"#\" data-headword=\"מקרולפוס\">מקרולפס</a> (corr. acc.).</div>","alt":[]},"16432":{"h":"מִקְרוֹבוּתָא","r":"M02456","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרָב\">קְרַב</a>) <i>coming near, touching</i>. <span class=\"citation\">Yalk. Gen. 26</span> <span dir=\"rtl\">כמה דלא דמכת במִקְרוֹבוּתֵיה וכ׳</span> as thou didst not die on touching it &amp;c.; <span class=\"citation\">Gen. R. s. 19</span> <span dir=\"rtl\">כמה דלא מיתת במִקְרְבֵיה</span>.</div>","alt":[]},"16433":{"h":"מקרולפוס","r":"M02457","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַקְרוֹאֶלַפְרוֹס\">מַקְרוֹאֶלַפְרוֹס</a></div>","alt":["מקרולפס"]},"16434":{"h":"מַקְרוֹס","r":"M02458","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (μακρός) <i>tall</i>. <span class=\"citation\">Yalk. Gen. 114</span> <span dir=\"rtl\">אם בעיניך מ׳ בעינינו וכ׳</span> though in thy sight he is tall, in ours he is a dwarf; (<span class=\"citation\">Gen. R. s. 65</span>, a. e. <span dir=\"rtl\">מקרוא לפרוס</span> &amp;c., v. <a href=\"#\" data-headword=\"מַקְרוֹאֶלַפְרוֹס\">מַקְרוֹאֶלַפְרוֹס</a>).</div>","alt":[]},"16435":{"h":"מַקְרֵי","r":"M02459","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קְרֵי I <i>Af</i>.), <span dir=\"rtl\">מ׳ דרדקי</span>, <span dir=\"rtl\">מ׳ ינוקי</span> <i>primary teacher</i>. <span class=\"citation\">B. Bath. 21ᵇ</span> <span dir=\"rtl\">במ׳ ד׳ דלא וכ׳</span> that a teacher cannot prevent a colleague from opening a school in the same avenue. <span class=\"citation\">Ib. 21ᵃ</span> <span dir=\"rtl\">סך מ׳ ד׳ וכ׳</span> the highest number of pupils for a primary teacher is twenty-five; a. fr.—Pl. <a href=\"#\" data-headword=\"מַקְרֵי\">מַקְרֵי</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הני תרי מ׳ ד׳ וכ׳</span> where there are two teachers one of whom &amp;c., v. <a href=\"#\" data-headword=\"גְּרַס II\"><span dir=\"rtl\">גְּרַס</span> II</a>.</div>","alt":[]},"16436":{"h":"מַקְרילוֹת","r":"M02460","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (a jocular denom. of <a href=\"#\" data-headword=\"מִקְרָא\">מִקְרָא</a>, to rhyme with <a href=\"#\" data-headword=\"מַקְבִּילוֹת\">מַקְבִּילוֹת</a>) <i>based on textual interpretation</i>. Y. B. Kam. VIII, end, 6ᶜ, v. <a href=\"#\" data-headword=\"מַקְבִּילוֹת\">מַקְבִּילוֹת</a>.</div>","alt":[]},"16437":{"h":"*מַקְרִין I","r":"M02461","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Macrin</i>, (supposed to mean) <i>Macrianus</i>, one of the thirty tyrants, who after the capture by the Persians of Valerian, was declared Roman emperor together with his sons Macrianus and Quietus. <span class=\"citation\">Gen. R. s. 76</span> (ref. to ‘three of the older horns’, <span class=\"citation\">Dan. VII, 8</span>) <span dir=\"rtl\">זו שנתנו להם מלכותם מ׳ וקרוס וקרדידוסי</span> (some ed. <a href=\"#\" data-headword=\"מקדין\">מקדין</a>) those (Romans) who gave them (the princes of Palmyra,) their royal titles (v. <span dir=\"rtl\">נֵצַר IV</span>); M. &amp;c.; Yalk. Dan. 1064 <span dir=\"rtl\">מוקירוס וקירוס וקירקוס</span> (omitting <span dir=\"rtl\">זו … מלכותם</span>) (some ed. <span dir=\"rtl\">וקרירוס</span>; Fürst Gloss. Graeco-Hebr. p. 145 quotes: <span dir=\"rtl\">וקירידיס</span>). [The other two names, obviously corrupted, refer perhaps to the two sons of Macrianus. V. Fürst l. c. for other conjectures.]</div>","alt":[]},"16438":{"h":"מַקְרִין II","r":"M02462","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>having horns</i>. <span class=\"citation\">Ḥull. 60ᵃ</span>; <span class=\"citation\">Sabb. 28ᵇ</span>; <span class=\"citation\">Ab. Zar. 8ᵃ</span> <span dir=\"rtl\">שור שהקריב … מ׳ מפריס</span> the ox which Adam offered had one horn in his forehead, for it is written (<span class=\"citation\">Ps. LXIX, 32</span>) &amp;c.; <span dir=\"rtl\">מ׳ תרין משמע</span> but does not <i>maḳrin</i> mean ‘having two horns’ (as <span dir=\"rtl\">מפריס</span> ‘having hoofs’)? <span dir=\"rtl\">מקרן כתיב</span> it is written without <i>Yod</i> (intimating a defect).</div>","alt":[]},"16439":{"h":"מַקְרְעָן","r":"M02463","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרַע\">קְרַע</a>) <i>rents</i>. <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> bot., v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִיסְטְוָוא</a> II a. <span dir=\"rtl\">מַרְקְעָא</span>.</div>","alt":[]},"16440":{"h":"מִקְרֶצֶת","r":"M02464","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרַץ\">קָרַץ</a>) <i>a piece of dough</i>, separated from the main dough in the trough. <span class=\"citation\">Tosef. Toh. XI, 2</span>. <span class=\"citation\">Toh. I, 8</span>.—Pl. <span dir=\"rtl\">מִקְרָצוֹת</span>. <span class=\"citation\">Ib. 7</span>. <span class=\"citation\">Tosef. Ḥall. I, 12</span> <span dir=\"rtl\">משתעשה מ׳</span> from the time the dough is divided up into lumps; Y. ib. I, beg. 59ᵃ <span dir=\"rtl\">משתעשה מ׳ מ׳</span>; a. e.</div>","alt":[]},"16441":{"h":"מְקַרְקַע","r":"M02465","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, mostly pl. <a href=\"#\" data-headword=\"מְקַרְקַע\">מְקַרְקְעֵי</a> (v. <a href=\"#\" data-headword=\"קַרְקַע\">קַרְקַע</a>) <i>attached to the ground, real estate</i>, opp. <a href=\"#\" data-headword=\"מְטַלְטְלָא\">מטלטלא</a>. <span class=\"citation\">Yeb. 99ᵃ</span>, a. e. <span dir=\"rtl\">עבדא כמ׳ דמי</span> a slave is legally considered as real estate; <span class=\"citation\">B. Bath. 150ᵃ</span> <span dir=\"rtl\">כמקרקעא</span> (Ms. M. pl.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שאני מ׳ דניד וכ׳</span> there is a difference between movable real estate (a slave) and an immovable estate; <span class=\"citation\">ib. 68ᵃ</span>. <span class=\"citation\">Ib. 150ᵇ</span> כתובה דממ׳ תקינו רבנן Ms. M. (ed. <span dir=\"rtl\">דאמ׳</span>) the widowhood which the Rabbis have instituted to be guaranteed by real estate. <span class=\"citation\">Ib.ᵃ</span> bot. <span dir=\"rtl\">כתובת אשה מ׳ הוא</span> the wife’s settlement is considered real estate; a. fr.</div>","alt":["מְקַרְקְעָא"]},"16442":{"h":"מְקֵרְתָּא","r":"M02466","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַקַר\">מַקַר</a>) <i>cooling place</i>. <span class=\"citation\">Targ. I Kings VII, 2</span>, a. e. <span dir=\"rtl\">בית מְקֵרַת מלכיא</span> the royal summer-house (h. text <span dir=\"rtl\">בית יער הלבנון</span>).—<span dir=\"rtl\">מ׳ דצִילַּיָּיא</span> pr. n. <i>M’ḳerta d’Tsillaya</i> (<i>Cooling Shades</i>), name of a field. <span class=\"citation\">Y. M. Kat. I, beg. 80ᵃ</span> (ed. Krot. <span dir=\"rtl\">מְקֵרַת</span>).</div>","alt":["מְקֵירְתָּא"]},"16443":{"h":"מַקְשָׁאָה","r":"M02467","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְשָׁא\">קְשָׁא</a>) <i>one who raises objections, disputant</i>. <span class=\"citation\">Gen. R. s. 48</span>; s. 85; <span class=\"citation\">Yalk. Gen. 82</span>; <span class=\"citation\">B. Mets. 87ᵃ</span>, v. <a href=\"#\" data-headword=\"אֶפְרַיִם\">אֶפְרַיִם</a> (cmp. <a href=\"#\" data-headword=\"מַפְתְּחָא\">מַפְתְּחָא</a>).—Pl. <a href=\"#\" data-headword=\"מַקְשָׁיִי\">מַקְשָׁיֵי</a>. <span class=\"citation\">Y. Kil. III, beg. 28ᶜ</span> <span dir=\"rtl\">הוון יתבין מ׳</span> were sitting and raising questions.</div>","alt":[]},"16444":{"h":"מִקְשָׁאוֹת","r":"M02468","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִקְשָׁה\">next w.</a></div>","alt":["מִקְשָׁאִין"]},"16445":{"h":"מִקְשָׁה","r":"M02469","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.; = <a href=\"#\" data-headword=\"מַקְשָׁאָה\">מקשאה</a>, , v. <a href=\"#\" data-headword=\"קִשּׁוּאִים\">קִשּׁוּאִים</a>) <i>cucumber field</i>, in gen. <i>truck-farm</i>. <span class=\"citation\">Tosef. Ter. I, 4</span>; Y. ib. I, 40ᵇ bot. <span class=\"citation\">Tosef. B. Mets. IX, 32</span>; a. e. (v. also <a href=\"#\" data-headword=\"מוּקְשֶׁה\">מוּקְשֶׁה</a>).—Pl. <a href=\"#\" data-headword=\"מִקְשָׁאוֹת\">מִקְשָׁאוֹת</a>, <a href=\"#\" data-headword=\"מִקְשָׁאוֹת\">מִקְשָׁיוֹת</a>, <a href=\"#\" data-headword=\"מִקְשָׁאוֹת\">מִקְשָׁאִין</a>. <span class=\"citation\">Shebi. II, 1</span> <span dir=\"rtl\">ליטע במ׳</span> (Ms. M. <span dir=\"rtl\">מקשות</span>, corr. acc.; Maim. <span dir=\"rtl\">מקשיות</span>), v. <a href=\"#\" data-headword=\"מִדְלַעַת\">מִדְלַעַת</a>.—In gen. <span dir=\"rtl\">מ׳ ומדלעות</span> <i>late vegetables</i> or <i>fruits</i>. <span class=\"citation\">Pes. 6ᵇ</span>. <span class=\"citation\">Erub. 104ᵃ</span> <span dir=\"rtl\">מִקְשָׁאָיו ומִדְלָעָיו</span> ed. Sonc. (Ms. O. <span dir=\"rtl\">ודלעיו</span>; Ms. M. <span dir=\"rtl\">מקשאיו ומדלעיו</span>, ed. only <span dir=\"rtl\">ודלעיו</span>) (who guards) his late fruits; a. e.—[<span class=\"citation\">Sabb. 90ᵇ</span> <span dir=\"rtl\">מקשה של חזיר</span>, read: <span dir=\"rtl\">מִקָּשֶׁה</span>. v. <a href=\"#\" data-headword=\"קָשֶׁה\">קָשֶׁה</a>.]</div>","alt":[]},"16446":{"h":"מַקְשֶׁה","r":"M02470","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>disputant, undecided</i>. <span class=\"citation\">Hor. 14ᵃ</span> <span dir=\"rtl\">חריף ומ׳</span> quick but undecided, opp. to <span dir=\"rtl\">מתון ומסיק</span> slow but coming to a conclusion.</div>","alt":[]},"16447":{"h":"מִקְשְׁיָא","r":"M02471","html":"<div class=\"sense\"> = h. <a href=\"#\" data-headword=\"מִקְשָׁה\">מִקְשָׁה</a>, v. <a href=\"#\" data-headword=\"מִקְטְיָא\">מִקְטְיָא</a></div>","alt":[]},"16448":{"h":"מַקְשָׁיִי","r":"M02472","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַקְשָׁאָה\">מַקְשָׁאָה</a></div>","alt":[]},"16449":{"h":"מַקְשְׁיָא","r":"M02473","html":"<div class=\"sense\">, f., part. pass. <i>Af</i>. of <a href=\"#\" data-headword=\"קְשֵׁי\">קְשׁי</a>.</div>","alt":["מַקְשְׁיָיא"]},"16450":{"h":"מקשיצת־","r":"M02474","html":"<div class=\"sense\">. <span class=\"citation\">Targ. Y. II, Deut. XXIX, 16</span>, read: <span dir=\"rtl\">מַשְׁקֵיצַת־</span>.</div>","alt":[]},"16451":{"h":"מֹר","r":"M02475","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>myrrh</i>, <a href=\"#\" data-headword=\"מוֹר\">מוֹר</a>.</div>","alt":[]},"16452":{"h":"מַר I","r":"M02476","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אֲמַר\">אֲמַר</a>, <i>to speak, say</i>. <span class=\"citation\">Y. Sabb. I, 3ᵇ</span> top <span dir=\"rtl\">חזר ומר</span> again he said. <span class=\"citation\">Y. B. Bath. X, 17ᶜ</span> bot. <span dir=\"rtl\">מְדְּמַר הונא</span> (not <a href=\"#\" data-headword=\"מרמר\">מרמר</a>) from what H. said (we learn). <span class=\"citation\">Y. Snh. III, 21ᵇ</span> bot. <span dir=\"rtl\">מאן דמר</span> he who said. Ib. X, 27ᵈ bot., v. <a href=\"#\" data-headword=\"דַּתְּ\">דַּתְּ</a>.—<span class=\"citation\">Y. Ter. VIII, 46ᵃ</span> <span dir=\"rtl\">חמון מה אתון מָרִין</span> observe what you say. <span class=\"citation\">Y. Ber. II, 5ᶜ</span> top <span dir=\"rtl\">אית דמָרִין</span> (not <span dir=\"rtl\">דמריי</span>) some say; a. fr.</div>","alt":[]},"16453":{"h":"מַר II","r":"M02477","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>bitter</i>. <span class=\"citation\">Pes. 39ᵃ</span> <span dir=\"rtl\">כל ירק מר וכ׳</span> every bitter herb contains a gum (won by impissation). <span class=\"citation\">Lev. R. s. 31</span> <span dir=\"rtl\">מר מזה מתחת ידו וכ׳</span> rather something bitterer than this out of the hand of the Lord, than sweets out of thine; <span class=\"citation\">Yalk. Gen. 59</span>; <span class=\"citation\">Gen. R. s. 33</span> (corr. acc.); a. fr.—<span class=\"citation\">Y. Snh. X, 27ᵈ</span> <span dir=\"rtl\">מר לי</span> woe is me. <span class=\"citation\">Keth. 69ᵇ</span> (play on <span dir=\"rtl\">וס̇ר מ̇ר̇ז̇ח סרוחים</span>, <span class=\"citation\">Am. VI, 7</span>) <span dir=\"rtl\">מ̇ר̇ וז̇ח̇ נעשה שר לסרוחים</span> he who is bitter (of soul) and distracted (through bereavement) is made the chief of those banqueting (i.e. the mourner must sit at the head at the comforting meal); <span class=\"citation\">M. Kat. 28ᵇ</span> (not <a href=\"#\" data-headword=\"מַרְזֵחַ\">מרזח</a>, Ms. M. <span dir=\"rtl\">מרוזח</span>); Yalk. Am. 545.</div><div class=\"sense\"><b>—2)</b> <i>corrosive substance</i>; trnsf. <i>care, worry</i>. <span class=\"citation\">Sabb. 30ᵇ</span>; <span class=\"citation\">Pes. 117ᵃ</span> (play on <a href=\"#\" data-headword=\"מוֹר\">מוֹר</a>, <span class=\"citation\">Cant. V, 13</span>) a student before his teacher, <span dir=\"rtl\">ואין שפתותיו נוטפות מר</span> whose lips to not drip from care; (Cant. R. l. c. <span dir=\"rtl\">ששפתיו נוטפות מור</span>).—3) <i>mar</i>, name of a bitter herb, <i>ferula</i>. Pes. l. c. <span dir=\"rtl\">מר ירואר</span>, expl. <span dir=\"rtl\">מר זה הוא י׳</span> <i>mar</i> is <i>y’roar</i>, v. <a href=\"#\" data-headword=\"*יְרוֹאָר\">יְרוֹאָר</a>; [for. Var. lect. v. Rabb. D. S. a. l. note].—<i>Fem</i>. <a href=\"#\" data-headword=\"מרי II\">מָרָה</a>, q. v.</div>","alt":[]},"16454":{"h":"מַר III","r":"M02478","html":"<div class=\"sense\"> (or <a href=\"#\" data-headword=\"מָר\">מָר</a>) m. (<a href=\"#\" data-headword=\"מוּר\">מוּר</a>) <i>exchange</i>; <span dir=\"rtl\">במֹר ד־</span> <i>instead of; as</i>. <span class=\"citation\">Ḥull. 94ᵃ</span> <span dir=\"rtl\">ויהבה ניהליה במר דשחוטה</span> and he gave her (the ritually forbidden hen) to him (the gentile) pretending that it was ritually cut. <span class=\"citation\">B. Kam. 113ᵇ</span>, v. <a href=\"#\" data-headword=\"פְּלִיזָא\">פְּלִיזָא</a>. <span class=\"citation\">Bekh. 30ᵃ</span> <span dir=\"rtl\">מזבין ליה במר דכנתא</span> sold it for fat of the ileum (which is permitted; Ar. <a href=\"#\" data-headword=\"מרכנתא\">מרכנתא</a>, suggesting <a href=\"#\" data-headword=\"*מַדְכַנְתָּא\">מַדְכַנְתָּא</a>, q. v.).</div>","alt":[]},"16455":{"h":"מַר IV","r":"M02479","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (pl. forms <a href=\"#\" data-headword=\"מַר IV\">מָרֵא</a>, <a href=\"#\" data-headword=\"מָרֵי\">מָרֵי</a>, <a href=\"#\" data-headword=\"מָארֵי\">מָארֵי</a>) (Arab. <i>marua</i>, cmp. <a href=\"#\" data-headword=\"מָרָא\">מָרָא</a>, <i>to be strong;</i> cmp. <a href=\"#\" data-headword=\"גָּבַר\">גָּבַר</a> a. <a href=\"#\" data-headword=\"גֶּבֶר\">גֶּבֶר</a>) <i>man, lord, master; somebody;</i> (as a title) <i>Mar</i>. <span class=\"citation\">Tosef. Shek. II, 15</span> <span dir=\"rtl\">מפני שמר על הכל</span> because he was ruler &amp;c., v. <a href=\"#\" data-headword=\"*אֲמַרְכֹּול\">אֲמַרְכּוֹל</a>; <span class=\"citation\">Hor. 13ᵃ</span> <span dir=\"rtl\">אמר כולא</span> (prob. to be read <span dir=\"rtl\">מרא כולא</span>).—<span class=\"citation\">Lev. R. s. 31</span> <span dir=\"rtl\">מָרִי נח</span> my lord Noah. <span class=\"citation\">Y. Peah VIII, end, 21ᵇ</span> <span dir=\"rtl\">לא יכעוס מָרִי עלי</span> let my lord not be angry &amp;c.; a. e.—<span class=\"citation\">Targ. Gen. XXXVII, 19</span>. <span class=\"citation\">Targ. Prov. XXIII, 2</span>; a. fr.—<span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">אי מר רבה … ואי מר וכ׳</span> if the one (Moses) is teacher (leader), thou art a pupil (subordinate), and if the other (Korah) is &amp;c. <span class=\"citation\">Ḥull. 105ᵃ</span>, a. fr. <span dir=\"rtl\">מר אמר חדא ומר אמר וכ׳</span> one said one thing, another another thing, but they do not differ. <span class=\"citation\">Yoma 20ᵇ</span> ומר אמר לי Ms. M. (ed. <span dir=\"rtl\">ואת אמרת</span>) and you, Sir, say to me &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מר ניהו רב נינח מר</span> (Rashi <span dir=\"rtl\">מר הוא</span>) the man (you speak of) is a teacher; sit down, Sir. <span class=\"citation\">B. Kam. 60ᵇ</span> <span dir=\"rtl\">מר אמר ליה לימא מר וכ׳</span> one said to him, tell us, Sir &amp;c.—<span class=\"citation\">Ber. 2ᵃ</span>, a. fr. <span dir=\"rtl\">אמר מר</span> it has been said (introducing a discussion on a subject previously touched upon). <span class=\"citation\">Y. Snh. I, 18ᶜ</span> bot., a. e. <span dir=\"rtl\">אכן מָרָהּ דשמעתא וכ׳</span> in such a case the author of the rule would not have maintained it. <span class=\"citation\">Y. Ter. VIII, 45ᶜ</span> <span dir=\"rtl\">הא מרי שמועתא והא מ׳ עובדא</span> here is a master of traditions and a master of practice. <span class=\"citation\">Gen. R. s. 58</span> (expl. <a href=\"#\" data-headword=\"תּוֹשָׁב\">תושב</a>, <span class=\"citation\">Gen. XXIII, 4</span>) <span dir=\"rtl\">מארי ביתא</span> (= <span dir=\"rtl\">בעל הבית</span>) owner of a house, <i>citizen</i>, opp. <span dir=\"rtl\">דיירא</span>. <span class=\"citation\">Succ. 32ᵇ</span>, a. fr. <span dir=\"rtl\">שרי ליה מָרֵיה ל־</span> the Lord forgive him (he is mistaken).—<span class=\"citation\">Ned. 50ᵃ</span> <span dir=\"rtl\">יעביד מָרָנָא עליה</span> let our lord do with this (be contented for the present). <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> [read:] <span dir=\"rtl\">אין את מָרָהּ דנפשך</span> (cmp. <span class=\"citation\">Prov. XXIII, 2</span>) if thou art master over thy desire; <span dir=\"rtl\">אי נפשך מָרָתָךְ</span> if thy desire is master over thee; <span class=\"citation\">Deut. R. s. 2</span> אנא מָרֵי דנפשי אנא I am master over my desire; a. fr.—Pl. <a href=\"#\" data-headword=\"מָרֵי\">מָרֵי</a> = <span dir=\"rtl\">בַּעֲלִים</span> (used as sing. a. pl.; v. supra). <span class=\"citation\">Targ. Is. III, 12</span>; a. fr.—<a href=\"#\" data-headword=\"מָרְוְותָא\">מָרָוָותָא</a>, <a href=\"#\" data-headword=\"מָרוּתָא\">מָרָוָתָא</a> (pl. of <a href=\"#\" data-headword=\"מָרוּתָא\">מָרוּתָא</a>). <span class=\"citation\">Targ. Prov. V, 13</span> (h. text <a href=\"#\" data-headword=\"מורי\">מוֹרָי</a>).—<span class=\"citation\">Gitt. 40ᵃ</span> <span dir=\"rtl\">כלו מ׳ בתראי</span> the owners at second hand (of the settlement of slaves) died out; <span dir=\"rtl\">אהדרו אבני מ׳ קדמאי</span> apply (for emancipation) to the heirs of the original owners. <span class=\"citation\">B. Bath. 3ᵇ</span> <span dir=\"rtl\">קטלינהו לכולהו מָרָוָתֵיה</span> (Var. <span dir=\"rtl\">לכולהו בני מרותיה</span>) he (Herod) killed all of his master’s family. <span class=\"citation\">B. Kam. 103ᵃ</span> מ׳ דכיתנא Ms. M. (ed. <span dir=\"rtl\">מָרָוָותֵיה</span>) the owner of the flax; a. fr.—Mar Samuel, Mar Ukban &amp;c., v. respect. pr. nouns.—Fem. <span dir=\"rtl\">מָרְתָא</span>, <span dir=\"rtl\">מָרְתָה</span> </div><div class=\"sense\"><b>1)</b> <i>mistress</i>, constr. <a href=\"#\" data-headword=\"מָרַת\">מָרַת</a>. <span class=\"citation\">Targ. I Kings XVII, 17</span>. <span class=\"citation\">Targ. Is. XXIV, 2</span>; a. fr.—<span class=\"citation\">Gen. R. s. 52</span>, v. <a href=\"#\" data-headword=\"בַּעֲלָה\">בַּעֲלָה</a>. <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> <span dir=\"rtl\">מ׳ דביתא</span> the hostess. <span class=\"citation\">Y. Peah VIII, 21ᵇ</span> top [read:] <span dir=\"rtl\">הב ליה יתיר דנפשיה מָרָתֵיה</span> give him (the poor man) more, for his appetite is his master (he is used to good living). Y. Ab. Zar. l. c., v. supra; a. fr.</div><div class=\"sense\"><b>—2)</b>  pr. n. f. <i>Martha</i>. <span class=\"citation\">Gitt. 56ᵃ</span>; a. fr. <span dir=\"rtl\">מ׳ בת ביתוס</span>, v. <a href=\"#\" data-headword=\"בַּיְתוֹס\">בַּיְתוֹס</a>.—<span class=\"citation\">M. Kat. 26ᵇ</span> bot. <span dir=\"rtl\">אבא בר מ׳</span> (Ms. M. <a href=\"#\" data-headword=\"מָרַת\">מָרַת</a>); <span class=\"citation\">Yeb. 120ᵃ</span>; <span class=\"citation\">Sabb. 121ᵇ</span>; <span class=\"citation\">Yoma 84ᵃ</span> (v. Rabb. D. S. a. l. note 60); a. e.</div><div class=\"sense\"><b>—3)</b>  pr. n. m. (?). <span class=\"citation\">Snh. 5ᵃ</span> bot. <span class=\"citation\">B. Bath. 52ᵃ</span> (v. Rabb. D. S. a. l. note 8). <span class=\"citation\">Pes. 103ᵃ</span> top <span dir=\"rtl\">מ׳ אמר</span> (Ms. M. 1 <span dir=\"rtl\">רב ברונא</span>; Ms. M. 2 <span dir=\"rtl\">מרונא</span>, v. Rabb. D. S. a. l. note).</div>","alt":["מָר","מָרָא I"]},"16456":{"h":"מָר","r":"M02480","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  (= <a href=\"#\" data-headword=\"מָאר\">מארא</a>, v. <a href=\"#\" data-headword=\"אָרָה\">אָרָה</a>) <i>hoe, rake</i>. <span class=\"citation\">Erub. 77ᵇ</span> <span dir=\"rtl\">דבעי מ׳ וחצינא</span> it requires hoe or pick-axe (to get it out). <span class=\"citation\">Meg. 28ᵃ</span>, v. <a href=\"#\" data-headword=\"דְּרֵי II\"><span dir=\"rtl\">דְּרֵי</span> II</a>. <span class=\"citation\">Taan. 23ᵇ</span> top <span dir=\"rtl\">ציבי ומ׳</span> the wood (he had collected) and the rake. <span class=\"citation\">B. Mets. 82ᵇ</span> <span dir=\"rtl\">מ׳ ופסל וקרדום</span> (Ms. <span dir=\"rtl\">מר</span>, Ar. <span dir=\"rtl\">מר פסל</span>) hoe and mattock and axe; <span class=\"citation\">Ber. 57ᵇ</span> <span dir=\"rtl\">מר פסל וקרדום</span>. <span class=\"citation\">Keth. 64ᵃ</span> בעינא … ומָרָה לקבורה I want a staff to lean on and a hoe to make my grave, i.e. a son to support me in old age and to provide for my burial; <span class=\"citation\">Yeb. 65ᵇ</span>. <span class=\"citation\">Taan. 21ᵇ</span>, v. <a href=\"#\" data-headword=\"זְבִילָא\">זְבִילָא</a>; a. e.—</div><div class=\"sense\"><b>*2)</b>  (= <a href=\"#\" data-headword=\"מָאר\">מארא</a>, denom. of <a href=\"#\" data-headword=\"אוּרָא I\">אוּרָא</a>; cmp. Arab. <i>marvu</i> silices &amp;c.) <i>flint</i> for striking a light. <span class=\"citation\">Zeb. 116ᵇ</span> <span dir=\"rtl\">אפיקו נורא ממ׳ חדתא</span> (Ms. M. <a href=\"#\" data-headword=\"מַגָּאנָא\">ממַגָּאנָא</a>, <span class=\"citation\">Yalk. Lev. 579</span> <a href=\"#\" data-headword=\"מַגָּנָה\">ממַגָּנָה</a>, v. <a href=\"#\" data-headword=\"מַנְגָּנָא\">מַנְגָּנָא</a>; Ms. K. <a href=\"#\" data-headword=\"מָאן\">ממָאנָא</a>; En Yaăk. <span dir=\"rtl\">ממָנָא</span>) produce fire with a flint-stone which has not been used before.</div>","alt":["מָרָא II"]},"16457":{"h":"מָרָא","r":"M02481","html":"<div class=\"sense\">, <i>to be strong</i>, v. <a href=\"#\" data-headword=\"מרי I\">מרי</a>.</div>","alt":[]},"16458":{"h":"מְרָא","r":"M02482","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרֵי\">מְרֵי</a></div>","alt":[]},"16459":{"h":"מֻרָּא","r":"M02483","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹר ²\">מוּרָא</a></div>","alt":[]},"16460":{"h":"מַרְאֶה","r":"M02484","html":"<div class=\"sense\">, m.(b. h.; <i>sight, looks, appearance; color, shade</i>. <span class=\"citation\">Yoma 74ᵇ</span> <span dir=\"rtl\">מַרְאֵה עינים באשה</span> the pleasure of looking at one’s wife. <span class=\"citation\">Tosef. Neg. I, 2</span> <span dir=\"rtl\">מ׳ ראשון</span> the first inspection of a leprous affection (<span class=\"citation\">Lev. XIII, 3</span>), <span dir=\"rtl\">מ׳ שני</span> the second (ib. 5) &amp;c. Ib. 4 <span dir=\"rtl\">כל מ׳ לבן</span> all shades of white; <span dir=\"rtl\">מ׳ סיבות</span> grey color. Ib. 5 <span dir=\"rtl\">מ׳ גבוה</span> the appearance of an elevation; <span dir=\"rtl\">כמ׳ צל בחמה</span> as the appearance of a shade thrown on a sunlit object; Sifra Thazr., <span class=\"citation\">Neg., ch. I</span>; a. fr.—Pl. <span dir=\"rtl\">מַרְאוֹת</span> (with pronom. suffix) <span dir=\"rtl\">מַרְאָיו</span>, <span dir=\"rtl\">מַרְאֶיהָ</span> &amp;c. <span class=\"citation\">Neg. I, 1</span>. Sifra l. c., Par. 2, ch. II <span dir=\"rtl\">במראיו</span> its retaining original color; <span dir=\"rtl\">כהה ממראיו</span> fainter than its original color. <span class=\"citation\">Bekh. VII, 5</span>; v. <a href=\"#\" data-headword=\"חָשׁוּךְ\">חָשׁוּךְ</a>; a. fr.</div>","alt":[]},"16461":{"h":"מַרְאָה","r":"M02485","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מַרְאֶה\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>mirror.</i> <span class=\"citation\">Kel. XIV, 6</span> <span dir=\"rtl\">שעשה בו מ׳</span> (not <span dir=\"rtl\">שעשאה</span>) one part of which he polished to serve as a mirror. <span class=\"citation\">Tosef. Sabb. XIII</span> (<span class=\"citation\">XIV), 16</span>; a. fr.—Pl. <span dir=\"rtl\">מַרְאוֹת</span>. <span class=\"citation\">Gen. R. s. 4</span> <span dir=\"rtl\">מ׳ גדולות</span> magnifying mirrors; <span dir=\"rtl\">מ׳ קטנות</span> diminishing mirrors; a. e.</div><div class=\"sense\"><b>—2)</b> <i>picture</i>.—Pl. as ab. <span class=\"citation\">Gen. R. s. 73</span> <span dir=\"rtl\">היה לך מ׳ בתוך ביתך</span> didst thou have pictures in thy house? <span dir=\"rtl\">שחורה … או לבנה</span> of black persons or of white?</div>","alt":[]},"16462":{"h":"מֻרְאָה","r":"M02486","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּרְאָה\">מוּרְאָה</a></div>","alt":[]},"16463":{"h":"מראטאי","r":"M02487","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְיוֹטָאֵי\">מַרְיוֹטָאֵי</a></div>","alt":[]},"16464":{"h":"מַרְאִית","r":"M02488","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"ראי\">(רָאָה</a>), <a href=\"#\" data-headword=\"מ׳\">מ׳</a> (<a href=\"#\" data-headword=\"ה\">ה</a>)<a href=\"#\" data-headword=\"עַיִן\">עין</a>, <i>appearance, sight, semblance</i>. <span class=\"citation\">Bekh. VII, 3</span> <span dir=\"rtl\">מפני מ׳ הע׳</span> because he is repulsive to look at. <span class=\"citation\">Lev. R. s. 26</span>; <span class=\"citation\">Midr. Till. to Ps. VII</span> <span dir=\"rtl\">אינו מוליך … מפני מ׳ הע׳</span> he does not take his children with him, because he is afraid of the evil eye.—Esp. <span dir=\"rtl\">מפני מ׳</span> (<a href=\"#\" data-headword=\"ה\">ה</a>)<a href=\"#\" data-headword=\"ע׳\">ע׳</a> in order to avoid the semblance of wrong-doing, for appearance sake. <span class=\"citation\">Bets. 9ᵃ</span>, a. fr. <span dir=\"rtl\">כל מקום שאסרו חכמים מפני מ׳ הע׳ אפי׳ וכ׳</span> wherever the scholars have forbidden a thing for appearance sake, it is forbidden even in strictest privacy, cmp. <a href=\"#\" data-headword=\"חֶדֶר\">חֶדֶר</a>; <span class=\"citation\">Y. Erub. VIII, end, 25ᵇ</span>. <span class=\"citation\">Y. M. Kat. I, 80ᵇ</span>. <span dir=\"rtl\">ולית לרבנן מפני מ׳ ע׳</span> do the Rabbis not care for appearance?; a. fr.</div>","alt":[]},"16465":{"h":"מראנא","r":"M02489","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּרָנָא\">מוּרָנָא</a></div>","alt":[]},"16466":{"h":"מְרַאֲשׁוֹת","r":"M02490","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"><i>head-part of the bed, bolster, pillow</i>. <span class=\"citation\">Y. Ber. III, 6ᵈ</span> bot. <span dir=\"rtl\">תולה …</span> (<a href=\"#\" data-headword=\"ב\">ב</a>)<span dir=\"rtl\">מ׳ המטה</span> he may suspend them from the head-board of the bed, opp. <a href=\"#\" data-headword=\"מַרְגְּלוֹת\">מרגלות</a>. <span class=\"citation\">Yoma 78ᵃ</span> <span dir=\"rtl\">מניחה תחת מְרַאֲשׁוֹתָיו</span> put it under his bolster. <span class=\"citation\">Sabb. 12ᵇ</span> <span dir=\"rtl\">שכינה למעלה מראשותיו של</span> (= <span dir=\"rtl\">ממ׳</span>) <a href=\"#\" data-headword=\"חוֹלֶה\">חולה</a> the Divine Presence is above the head-side of the patient; <span class=\"citation\">Yalk. Ps. 741</span>.</div>","alt":[]},"16467":{"h":"מֵרַב","r":"M02491","html":"<div class=\"sense\">, (b. h.) pr. n. f. <i>Merab</i>, daughter of King Saul. <span class=\"citation\">Snh. 19ᵇ</span>; a. e.</div>","alt":["מֵירַב"]},"16468":{"h":"מרבג","r":"M02492","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִרְבּךְ\">מִרְבָּךְ</a> a. <a href=\"#\" data-headword=\"נִדְבָּךְ\"><a href=\"#\" data-headword=\"נִדְבָּךְ\">נִדְבָּךְ</a>.</a></div>","alt":[]},"16469":{"h":"מְרֻבֶּה","r":"M02493","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרוּבֶּה\">מְרוּבֶּה</a></div>","alt":[]},"16470":{"h":"מַרְבּוּעִיתָא","r":"M02494","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְבַּעְתָּא\">מַרְבַּעְתָּא</a></div>","alt":["מַרְבּוּעֲתָא"]},"16471":{"h":"מַרְבְּיָינָא","r":"M02495","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*רְבֵי\">רְבֵי</a>) </div><div class=\"sense\"><b>1)</b> <i>educator, teacher</i>. <span class=\"citation\">Targ. Prov. II, 17</span> ed. Lag. (ed. <a href=\"#\" data-headword=\"מַרְבִּיתָא\">מַרְבִּיתָא</a> <i>teaching</i>; h. text <a href=\"#\" data-headword=\"אַלּוּף\">אלוף</a>).</div><div class=\"sense\"><b>—2)</b>  (= h. <a href=\"#\" data-headword=\"יָלִיד\">יָלִיד</a>) <i>raised</i> (<i>servant</i> or <i>child</i>).—Pl. <span dir=\"rtl\">מַרְבְּיָינִין</span>, constr. <a href=\"#\" data-headword=\"מַרְבְּיָינָא\">מַרְבְּיָינֵי</a>, <span dir=\"rtl\">מַרְבְּיָ׳</span>. <span class=\"citation\">Targ. Y. I Gen. XIV, 14</span> (<span class=\"citation\">II</span> <a href=\"#\" data-headword=\"מרביצי\">מרביצי</a>, corr. acc.). Ib. XVII, 12. <span class=\"citation\">Targ. Y. Num. XIII, 23</span>; <span class=\"citation\">28</span>; a. e.</div><div class=\"sense\"><b>—3)</b>  (<i>pl.</i>) <i>sprouts</i>. <span class=\"citation\">Targ. Ps. LXV, 11</span> <span dir=\"rtl\">מַרְבְּיָנֵי צמחהא</span> (Ms. <span dir=\"rtl\">נִצְיָינָהָא</span>; h. text <span dir=\"rtl\">תלמיה</span>).</div>","alt":["מַרְבְּיָנָא"]},"16472":{"h":"מַרְבְּיָיתָא","r":"M02496","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַרְבְּיָינָא\">preced.</a>) <i>nurse, foster-mother</i>. <span class=\"citation\">Targ. Y. II, Gen. XXXV, 8</span> (Ar. <a href=\"#\" data-headword=\"מַרְבַּנְיָיתָא\">מַרְבַּנְיָיתָא</a>; h. text <span dir=\"rtl\">מינקת</span>).—V. <a href=\"#\" data-headword=\"מַרְבִּינֶתּא\">מַרְבִּינְתָּא</a>.</div>","alt":["מַרְבַּיְיתָא"]},"16473":{"h":"מַרְבְּיָנָא","r":"M02497","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְבְּיָינָא\">מַרְבְּיָינָא</a></div>","alt":[]},"16474":{"h":"מַרְבִּינֶתּא","r":"M02498","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"מַרְבְּיָיתָא\">מַרְבְּיָיתָא</a>. <span class=\"citation\">Kidd. 31ᵇ</span> <span dir=\"rtl\">ההיא מַרְבִּינְתֵּיה הואי</span> (Ar. <span dir=\"rtl\">מַרְבַּנְיָיתֵיה</span>) she (whom he calls his mother) was his foster-mother (or nurse).</div>","alt":[]},"16475":{"h":"מַרְבִּיעָה","r":"M02499","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּרְבִּית II\"><span dir=\"rtl\">מוּרְבִּית</span> II</a></div>","alt":["מַרְבִּיעוֹת"]},"16476":{"h":"מַרְבִּיעֲתָא","r":"M02500","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְבַּעְתָּא\">מַרְבַּעְתָּא</a></div>","alt":[]},"16477":{"h":"מרביצי","r":"M02501","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. II, Gen. XIV, 14</span>, v. <a href=\"#\" data-headword=\"מַרְבְּיָינָא\">מַרְבְּיָינָא</a></div>","alt":[]},"16478":{"h":"מַרְבִּית","r":"M02502","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>increase, profit</i>. <span class=\"citation\">B. Mets. 61ᵃ</span></div><div class=\"sense\"><b>—2)</b> <i>young tree</i>.—Pl. <a href=\"#\" data-headword=\"מַרְבִּיעָה\">מַרְבִּיּוֹת</a>, v. <a href=\"#\" data-headword=\"מוּרְבִּית I\"><span dir=\"rtl\">מוּרְבִּית</span> I</a>.</div>","alt":[]},"16479":{"h":"מַרְבִּיתָא","r":"M02503","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"מוּרְבִּית I\"><span dir=\"rtl\">מוּרְבִּית</span> I</a>, <i>a growing tree</i> (not yet fully developed). <span class=\"citation\">Y. Shebi. I, end, 33ᶜ</span>. <span dir=\"rtl\">ואנן חמיי הדא מ׳ … אתיא בפירי</span> (not <span dir=\"rtl\">בפורי</span>) and yet we see young fig trees come out with full fruit; [<span class=\"citation\">Y. Orl. I, 61ᵃ</span>. <span dir=\"rtl\">הדין מרויתא … לעוביה …</span>, a corrupt gloss transferred from Y. Shebi. l. c.].</div><div class=\"sense\"><b>—2)</b> <i>training, teaching</i>. <span class=\"citation\">Targ. Prov. II, 17</span>, v. <a href=\"#\" data-headword=\"מַרְבְּיָינָא\">מַרְבְּיָינָא</a>.</div>","alt":[]},"16480":{"h":"מַרְבַּיְתָא","r":"M02504","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְבְּיָיתָא\">מַרְבְּיָיתָא</a></div>","alt":[]},"16481":{"h":"מִרְבּךְ","r":"M02505","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">רָבַךְ</span>) <i>an irregular pile.</i> Ohol. III, 7 <span dir=\"rtl\">מ׳ של אבנים</span> (Ar. <a href=\"#\" data-headword=\"מרבג\">מרבג</a>, Var. <span dir=\"rtl\">מרבן</span>) a pile of (large) stones; <span class=\"citation\">Succ. 20ᵇ</span> <a href=\"#\" data-headword=\"מדבך\">מדבך</a> ed. (Ms. M. 2 <a href=\"#\" data-headword=\"נִדְבָּךְ\">נדבך</a>). <span class=\"citation\">Sabb. 125ᵇ</span> <a href=\"#\" data-headword=\"מִרְבּךְ\">מרבך</a> (<a href=\"#\" data-headword=\"מרבג\">מרבג</a>) Ar. (ed. <a href=\"#\" data-headword=\"נִדְבָּךְ\">נדבך</a>).</div>","alt":[]},"16482":{"h":"מַרְבַּנְיָיתָא","r":"M02506","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְבְּיָיתָא\">מַרְבְּיָיתָא</a> a. <a href=\"#\" data-headword=\"מַרְבִּינֶתּא\"><a href=\"#\" data-headword=\"מַרְבִּינֶתּא\">מַרְבִּינְתָּא</a>.</a></div>","alt":["מַרְבַּנְיָתָא"]},"16483":{"h":"מִרְבָּעָה","r":"M02507","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּרְבִּית II\"><span dir=\"rtl\">מוּרְבִּית</span> II</a></div>","alt":["מִרְבָּעוֹת"]},"16484":{"h":"מַרְבַּעְתָּא","r":"M02508","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְבַע\">רְבַע</a>) <i>crounching; den, resting place</i>. <span class=\"citation\">Targ. Am. III, 4</span> <span dir=\"rtl\">מַרְבּוּעִיתֵיה</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">מַרְבּוּעָ׳</span>). Targ. II Esth. I, 2 <a href=\"#\" data-headword=\"מַרְבַּעְתָּא\">מַרְבְּעוּ׳</a>.—<span class=\"citation\">B. Bath. 73ᵃ</span> <span dir=\"rtl\">בי מַרְבַּעְתֵּיה דכוכבא זוטא</span> the resting place of a small star (Ms. F. <span dir=\"rtl\">בי מַעְבַּרְתֵּיה</span> the transit of &amp;c.; v. Rabb. D. S. a. l. note 40). <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">בי מ׳ דרישיה</span> the place where his head rests.</div>","alt":["מַרְבְּעוּתָא","מַרְבְּעִי׳"]},"16485":{"h":"מְרַג","r":"M02509","html":"<div class=\"sense\"><i>to sway to and fro, vacillate</i>.</div><div class=\"sense\"><b>Pa. מַרֵיג</b> <div class=\"sense\"><i>to cause swaying</i>. <span class=\"citation\">Targ. II Sam. VI, 6</span>; <span class=\"citation\">Targ. I Chr. XIII, 9</span>.</div></div><div class=\"sense\"><b>Ithpe. אִתְמְרֵיג</b> <div class=\"sense\"><i>to be swayed, become unsteady</i>. <span class=\"citation\">Targ. O. Deut. XIX, 5</span> Regia a. oth. (ed. Berl. <span dir=\"rtl\">תתמריך</span>, v. Berl. Targ. O. II, p. 55; h. text <a href=\"#\" data-headword=\"דחי\">נדחה</a>).</div></div>","alt":[]},"16486":{"h":"*מַרְגּוּאַן","r":"M02510","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Marguan</i> (prob. Antiochia Margiana, in Central Asia). <span class=\"citation\">Ab. Zar. 31ᵇ</span> (Ms. M. <span dir=\"rtl\">מרגוז</span>, Tosaf. R. Elḥ. <span dir=\"rtl\">מר גזאן</span>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"16487":{"h":"מַרְגּוֹעָא","r":"M02511","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = b. h. <span dir=\"rtl\">מַרְגֵּעָה</span> (cmp. <a href=\"#\" data-headword=\"רְגוֹעִיתָא\">רְגוֹעִיתָא</a>), <i>rest, ease</i>. <span class=\"citation\">Targ. Job XXI, 13</span> (h. text <span dir=\"rtl\">רגע</span>).</div>","alt":[]},"16488":{"h":"מַרְגֵּז","r":"M02512","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְגַז I\">רְגַז</a></div>","alt":["מַרְגְּזָא"]},"16489":{"h":"מרגזאות","r":"M02513","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּרִיסוֹ\">כְּרִיסוֹ</a></div>","alt":[]},"16490":{"h":"מרגזאן","r":"M02514","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*מַרְגּוּאַן\">מַרְגּוּאַן</a></div>","alt":[]},"16491":{"h":"מַרְגְּזַיָּיה","r":"M02515","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (transpos. of <span dir=\"rtl\">מגזר׳</span>; <a href=\"#\" data-headword=\"גְּזַר\">גְּזַר</a>) <i>mincing knives, meat-chopper</i>. <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> bot. <span dir=\"rtl\">כד מכתת במ׳</span> when he chops (meat &amp;c. for sausages) with the chopper, v. <a href=\"#\" data-headword=\"*בגומא\">בגומא</a>.</div>","alt":[]},"16492":{"h":"מַרְגְּזָנִיתָא","r":"M02516","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְגַז I\">רְגַז</a>) <i>irascible, quarrelsome</i>. <span class=\"citation\">Targ. Prov. XXI, 19</span> (Levita <a href=\"#\" data-headword=\"רַגְזָנִיתָא\">רַגְזָנִיתָא</a>).</div>","alt":[]},"16493":{"h":"מַרְגְּלָא I","r":"M02517","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְגַל\">רְגַל</a>, v. <a href=\"#\" data-headword=\"רָגִיל\">רָגִיל</a>) <i>habitual saying, a familiar word;</i> <span dir=\"rtl\">מ׳ בפומיה ד־</span> used to say. <span class=\"citation\">Ber. 17ᵃ</span>.—<span class=\"citation\">Snh. 50ᵇ</span>; <span class=\"citation\">Zeb. 36ᵇ</span> (of a traditional law).</div>","alt":[]},"16494":{"h":"מַרְגְּלָא II","r":"M02518","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַרְגָּלִיתָא\">מַרְגָּלִיתָא</a>) <i>a jewel</i>. <span class=\"citation\">Targ. Job XXVIII, 19</span>, v. <a href=\"#\" data-headword=\"יַרְקָא\">יַרְקָא</a>.—Pl. <a href=\"#\" data-headword=\"מַרְגָּלִיתָא\">מַרְגְּלִיתָא</a></div>","alt":[]},"16495":{"h":"מַרְגְּלוֹת","r":"M02519","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"><i>the bottom-part of a bedstead</i>; (also adv.) <i>at the bottom of</i> &amp;c. <span class=\"citation\">Y. Ber. III, 6ᵈ</span> bot., v. <a href=\"#\" data-headword=\"מְרַאֲשׁוֹת\">מְרַאֲשׁוֹת</a>. <span class=\"citation\">Yalk. Ruth 606</span> <span dir=\"rtl\">נשתהתה … שוכבת מַרְגְּלוֹתָיו</span> (not <span dir=\"rtl\">שוכב</span>) she tarried six hours lying at his feet.</div>","alt":[]},"16496":{"h":"מַרְגָּלִי","r":"M02520","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְגָּלִיתָא\">מַרְגָּלִיתָא</a></div>","alt":["מַרְגַּלְיָיא"]},"16497":{"h":"מַרְגְּלִיטִיס","r":"M02521","html":"<div class=\"sense\"> (not … <span dir=\"rtl\">טוס</span>) m. (μαργαρίτης) <i>margarites chersaios</i>, name of a precious stone. <span class=\"citation\">Ex. R. s. 38</span>, end (corresp. to <a href=\"#\" data-headword=\"יָשְׁפֵּה\">ישפה</a>, <span class=\"citation\">Ex. XXVIII, 20</span>).</div>","alt":[]},"16498":{"h":"מַרְגָּלִית","r":"M02522","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. μαργαρίτης, μαργηλίς &amp;c., prob. of Semitic origin, cmp. <a href=\"#\" data-headword=\"רְגַג\">רגג</a>, <span dir=\"rtl\">רגרג</span>) <i>gem, jewel, pearl</i>, mostly pl. <span dir=\"rtl\">מַרְגָּלִיּוֹת</span>. <span class=\"citation\">Ab. Zar. 8ᵇ</span> <span dir=\"rtl\">מ׳ ואבן טובה וכ׳</span> in setting pearls and a precious stone (for an ornament), which is made the base (subordinate) to the other?—<span class=\"citation\">Gen. R. s. 31</span> (expl. <span dir=\"rtl\">צהר</span>, <span class=\"citation\">Gen. VI, 16</span>) <a href=\"#\" data-headword=\"מַרְגָּלִית\">מרגלית</a> a polished gem; <span class=\"citation\">Y. Pes. I, 27ᵇ</span> top; <span class=\"citation\">Pirké d’R. El. ch. XXIII</span> <span dir=\"rtl\">מ׳ אחת תלויה וכ׳</span> one jewel was suspended in the Ark which lighted up &amp;c.; <span class=\"citation\">Snh. 108ᵇ</span>.—<span class=\"citation\">Y. Shek. II, beg. 46ᶜ</span> <span dir=\"rtl\">ויעשו אותן מ׳</span> why not let them exchange the coins (to be taken to Jerusalem) for a jewel … <span dir=\"rtl\">שמא תזול המ׳</span> the jewel may fall in price. <span class=\"citation\">Yoma 75ᵃ</span> <span dir=\"rtl\">לבן כמ׳</span> white as a pearl; a. fr.</div>","alt":[]},"16499":{"h":"מַרְגָּלִיתָא","r":"M02523","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Ex. XXVIII, 10</span>; a. fr.—Y. Dem. I, 22ᵃ top <span dir=\"rtl\">מרגלי מן דמלכא</span> a jewel out of the crown of the King. <span class=\"citation\">Esth. R. to I, 6</span>, v. <a href=\"#\" data-headword=\"דּוּרָא II\"><span dir=\"rtl\">דּוּרָא</span> II</a>. <span class=\"citation\">Y. Keth. XII, 35ᵇ</span>; <span class=\"citation\">Y. Kil. IX, 32ᶜ</span> bot. <span dir=\"rtl\">אנא מובד מַרְגְּלִיתִי וכ׳</span> I am to give up my pearl (soul) in an unclean land; a. fr.—<span class=\"citation\">Lam. R. to I, 9</span> <span dir=\"rtl\">דא מ׳</span> this <i>precious idea</i> (cmp. <a href=\"#\" data-headword=\"חוֹמֶר II\"><span dir=\"rtl\">חוֹמֶר</span> II</a>); a. e.—Pl. <a href=\"#\" data-headword=\"מַרְגָּלִי\">מַרְגַּלְיָיתָא</a>, <a href=\"#\" data-headword=\"מַרְגָּלִי\">מַרְגַּלְיָין</a>. <span class=\"citation\">Targ. Y. Ex. XXVIII, 9</span>; <span class=\"citation\">11</span>. <span class=\"citation\">Targ. Is. LIV, 12</span> <a href=\"#\" data-headword=\"מַרְגְּנִין\">מַרְגְּלִין</a> (prob. to be read … <a href=\"#\" data-headword=\"גַּלְמָן\">גַּלְיָן</a>). <span class=\"citation\">Targ. Ez. XXVII, 16</span> ed. Lag. (ed. Wil. … <a href=\"#\" data-headword=\"לִין\">לִין</a>); a. fr.</div>","alt":["מַרְגָּלִי","מַרְגַּלְיָיא"]},"16500":{"h":"מַרְגְּלָתָא","r":"M02524","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> , (<i>the bolster at</i>) <i>the bottom of the bed</i>. Y. Maas. Sh. IV, end, 55ᶜ, v. <a href=\"#\" data-headword=\"מַקְנִיתָא\">מַקְנִיתָא</a>.</div>","alt":[]},"16501":{"h":"מַרְגְּנִין","r":"M02525","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (μάραγνα) <i>whips, scourges</i>. <span class=\"citation\">Targ. I Kings XII, 11</span>; <span class=\"citation\">14</span>; <span class=\"citation\">Targ. II Chr. X, 11</span>; <span class=\"citation\">14</span>.</div>","alt":[]},"16502":{"h":"מַרְגְּנִיתָא","r":"M02526","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַרְגָּלִיתָא\">מַרְגָּלִיתָא</a>) <i>pearl</i> or <i>jewel</i>. <span class=\"citation\">B. Bath. 146ᵃ</span> <span dir=\"rtl\">שחקי ליה מ׳ וכ׳</span> they ground for him a pearl worth &amp;c. <span class=\"citation\">Kidd. 26ᵇ</span> <span dir=\"rtl\">תלה בה מ׳ וכ׳</span> he set in it (the needle) a pearl (or a precious stone) worth &amp;c. <span class=\"citation\">Ib. 18ᵃ</span> <span dir=\"rtl\">נקיט מ׳ בידיה</span> he possessed a pearl (a precious slave). <span class=\"citation\">Ber. 33ᵇ</span> <span dir=\"rtl\">תקינו לן מ׳</span> they composed for us a precious prayer. <span class=\"citation\">Yeb. 94ᵃ</span> הרה ליה … למדרש ביה מ׳ R. E. had an opportunity for a most precious interpretation, opp. <span dir=\"rtl\">חספא</span>. <span class=\"citation\">Ib. 92ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"דְּלֵי\">דְּלֵי</a>; a. fr.—Pl. <a href=\"#\" data-headword=\"מַרְבַּנְיָיתָא\">מַרְגַּנְיָיתָא</a>. <span class=\"citation\">R. Hash. 23ᵃ</span> <span dir=\"rtl\">מסקן מ׳</span> they bring up pearls (from the bottom of the sea).</div>","alt":[]},"16503":{"h":"מַרְגֵּשׁוֹת","r":"M02527","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָגַשׁ\">רָגַשׁ</a>) <i>noises</i>. Lam. R. introd. (R. Joḥ. 1) <span dir=\"rtl\">הלשון הזה … צרות מ׳ וכ׳</span> this expression (<span dir=\"rtl\">תשאות</span>, <span class=\"citation\">Is. XXII, 2</span>) serves for three meanings: distress, noises and darkness; <span class=\"citation\">Yalk. Is. 289</span> <span dir=\"rtl\">מתרגשות</span> (corr. acc.).—[<span class=\"citation\">Num. R. s. 14</span> <a href=\"#\" data-headword=\"מַרְגֵּשׁוֹת\">מרגשות</a> some ed., v. <a href=\"#\" data-headword=\"מוּרְגָּשָׁה\">מוּרְגָּשָׁה</a>.]</div>","alt":[]},"16504":{"h":"מָרַד I","r":"M02528","html":"<div class=\"sense\"><b>1)</b> <i>to rebel, refuse obedience; to protest</i>. <span class=\"citation\">Keth. V, 7</span> <span dir=\"rtl\">המוֹרֶדֶת על בעלה</span> she who rebels against her husband (refusing marital duties; oth. opin. refusing to work). Ib. <span dir=\"rtl\">המוֹרֵד על אשתו</span> a husband refusing marital duties (oth. opin. refusing to give her work and support); ib. 63ᵇ. <span class=\"citation\">Snh. 49ᵃ</span>, a. fr. <span dir=\"rtl\">מורד במלכות</span> rebel.—<span class=\"citation\">Meg. 13ᵃ</span> <span dir=\"rtl\">מ׳ בעצת מרגלים</span> he (Caleb) protested against the counsel of the spies. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מרדה בגילולי וכ׳</span> she refused homage to the idols of her father’s house; a. fr.—[<span class=\"citation\">Y. Maas. Sh. I, 52ᵈ</span> top <span dir=\"rtl\">מטבע שמרד</span>, read: <span dir=\"rtl\">של מֶרֶד</span> or <a href=\"#\" data-headword=\"מָרוֹד\">מָרוֹד</a>, q. v.]</div><div class=\"sense\"><b>—2)</b> <i>to incite to rebellion</i>. <span class=\"citation\">Gen. R. s. 23</span>, v. infra.</div><div class=\"sense\"><b>Hif. הִמְרִיד</b> <div class=\"sense\"><i>to make rebellious, to incite</i>. Y. Keth. V, 30ᵇ bot. <span dir=\"rtl\">התורה הִמְרַדְתָּהּ עליו</span> the Law requires her to be rebellious against him (to refuse sexual connection). <span class=\"citation\">Gen. R. s. 26</span> <span dir=\"rtl\">זה הִמְרִידָן עלי</span> this man (Nimrod) made them rebel against me; ib. s. 23 <span dir=\"rtl\">זה המוֹרְדָן עלי</span> (‘Rashi’: <span dir=\"rtl\">המרידן</span>).</div></div>","alt":[]},"16505":{"h":"מָרַד II","r":"M02529","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מָרַד I\">preced.</a>, cmp. <a href=\"#\" data-headword=\"יָרַד\">יָרד</a>) <i>to run, discharge matter; to be sore, inflamed</i>. <span class=\"citation\">Ab. Zar. 28ᵇ</span>; Y. ib. II, 40ᵈ top <span dir=\"rtl\">עין שמָרְדָה</span> an inflamed eye (comment.: ‘which rebels’, i.e. threatens to burst out of its socket).—Sifra Thazr., Neg., Par. 3, ch. IV <span dir=\"rtl\">שחין המוֹרֵד ומכוה המוֹרֶדֶת</span> a running (open) wound from contusion or from a burn; <span class=\"citation\">Neg. VI, 8</span>; <span class=\"citation\">VIII, 5</span> <span dir=\"rtl\">השחין המכוה והקדח המוֹרְדִין</span> (not <span dir=\"rtl\">והמורדין</span>) running wounds from contusion, burn or inflammation; <span class=\"citation\">Tosef. ib. III, 10</span> <span dir=\"rtl\">השחין והמכוה והקרח והמירין</span> ed. Zuck. (Var. <span dir=\"rtl\">והמידק</span>, corr. acc.; v. R. S. to Neg. l. c.; R. S. to <span class=\"citation\">Neg. VI, 8</span> quotes a Var. <span dir=\"rtl\">מורר׳</span>, v. R. S. to <span class=\"citation\">Par. IX, 2</span>; v. <a href=\"#\" data-headword=\"מוֹרִיר\">מוֹרִיר</a>). Sifra l. c., Par. 4, ch. VII <span dir=\"rtl\">מורדת</span>; Y. Pes. VII, 34ᵃ bot. <span dir=\"rtl\">מגרדת</span> (corr. acc.); a. fr.</div>","alt":[]},"16506":{"h":"מְרַד","r":"M02530","html":"<div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"מָרַד I\"><span dir=\"rtl\">מָרַד</span> I</a>, <i>to rebel, run away</i>. <span class=\"citation\">Targ. I Kings XV, 27</span> (h. text <span dir=\"rtl\">קשר</span>). <span class=\"citation\">Targ. II Kings IX, 14</span> (ed. Wil. <span dir=\"rtl\">מריד</span>; h. text <span dir=\"rtl\">קשר</span> <i>Hithpa.</i>). <span class=\"citation\">Targ. Jer. VIII, 5</span> <span dir=\"rtl\">למִמְרַד מן</span> ed. Lag. (ed. <span dir=\"rtl\">למרד</span>) to run away from (desert); a. fr.—<span class=\"citation\">Ber. 44ᵃ</span> <span dir=\"rtl\">עד דמריד</span> until he ran away (bewildered).</div><div class=\"sense\"><b>—2)</b>  cmp. <a href=\"#\" data-headword=\"מֶרֶד I\">מֶרֶד</a> II a. <a href=\"#\" data-headword=\"רָדָה\">רָדָה</a>) <i>to rule</i>. <span class=\"citation\">Targ. Lam. I, 7</span>.</div><div class=\"sense\"><b>Ithpe. אִימְּרִיד</b> <div class=\"sense\"><i>to become rebellious, run away</i>. <span class=\"citation\">Keth. 63ᵇ</span> אִימְּרִידָא Rashi (ed. <span dir=\"rtl\">אִימְרְדָה</span>, Alf. <span dir=\"rtl\">אִימְרְדָא</span>) ran away (from her husband). <span class=\"citation\">B. Mets. 84ᵇ</span> <span dir=\"rtl\">אימרדה אזלה וכ׳</span> (Ms. M. <span dir=\"rtl\">אימרי׳</span>, v. <a href=\"#\" data-headword=\"מרי I\">מְרִי</a>) she ran away and went to her paternal home.</div></div>","alt":["מְרֵיד"]},"16507":{"h":"מֶרֶד I","r":"M02531","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>running away, running against</i>, cmp. <a href=\"#\" data-headword=\"מַעַל\">מַעַל</a>,] <i>desertion, rebellion</i>. <span class=\"citation\">Pes. 55ᵇ</span> <span dir=\"rtl\">אחר שלשה למִרְדָהּ</span> after three days since her (the bird’s) deserting the eggs; <span class=\"citation\">ib.</span> <span dir=\"rtl\">למוֹרְדָהּ</span>. <span class=\"citation\">Midr. Till. to Ps. XC</span> בשביל המ׳ שמרדתי אני וכ׳ I beg for amnesty for the rebellion which I made. <span class=\"citation\">Gen. R. s. 23</span>; s. 26 (ref. to <span dir=\"rtl\">הוחל</span>, <span dir=\"rtl\">החל</span>, <span class=\"citation\">Gen. IV, 26</span>; <span class=\"citation\">VI, 1</span>; <span class=\"citation\">X, 8</span>) <span dir=\"rtl\">לשון מ׳</span> it means desertion from the Lord (cmp. <a href=\"#\" data-headword=\"חָלַל\">חָלַל</a>, <a href=\"#\" data-headword=\"חוּלִּין\">חוּלִּין</a>); a. fr.—<span dir=\"rtl\">איגרת מ׳</span> a document stating a wife’s, or a husband’s, refusal of duties, v. <a href=\"#\" data-headword=\"מָרַד I\"><span dir=\"rtl\">מָרַד</span> I</a>. <span class=\"citation\">Keth. 64ᵃ</span>; Y. ib. V, 30ᵇ bot.; <span class=\"citation\">Y. Kidd. I, 59ᵃ</span> bot.; a. fr.—Pl. <span dir=\"rtl\">מְרָדִים</span> <i>rebellious acts</i>, contrad. to sins of passion <span dir=\"rtl\">(זדונות</span>). <span class=\"citation\">Tosef. Yoma II, 1</span>; <span class=\"citation\">Yoma 36ᵇ</span>; Y. ib. III, 40ᵈ bot., v. <a href=\"#\" data-headword=\"פֶּשַׁע\">פֶּשַׁע</a>.</div>","alt":[]},"16508":{"h":"מֶרֶד II","r":"M02532","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מֶרֶד I\">preced.</a>; cmp. <a href=\"#\" data-headword=\"מַרְדּוּת I\">מרְדּוּת</a> I a. <a href=\"#\" data-headword=\"רָדָה\">רָדָה</a>) [<i>bringingdown</i>,] <i>subjugation</i>. <span class=\"citation\">Gen. R. s. 42</span> (ref. to <span class=\"citation\">Gen. XIV, 4</span>, sq.) <span dir=\"rtl\">בארבע עשר למִרְדָּן</span> in the fourteenth year counting from their subjugation; Yalk. ib. 72.</div>","alt":[]},"16509":{"h":"מֵרַד","r":"M02533","html":"<div class=\"sense\"> (Bibl. chald. <a href=\"#\" data-headword=\"מְרַד\">מְרַד</a>) ch. = h.. <span class=\"citation\">Targ. Josh. XXII, 22</span> <span dir=\"rtl\">מירד</span> ed. Lag. (ed. <a href=\"#\" data-headword=\"מַרְדָּא I\">מרדא</a>). <span class=\"citation\">Targ. II Sam. XV, 12</span> (h. text <span dir=\"rtl\">קשר</span>); a. e.—Pl. <span dir=\"rtl\">מֵרְדִין</span>, <a href=\"#\" data-headword=\"מֵלַךְ\">מֵי׳</a>. <span class=\"citation\">Targ. Job VIII, 4</span>. <span class=\"citation\">Ib. XXXV, 6</span> מְרָדָיִיךְ Ms. (ed. <span dir=\"rtl\">מָרוֹדָךְ</span>, v. <a href=\"#\" data-headword=\"מָרוֹד ²\">מָרוֹדָא</a>).</div>","alt":["מֵרְדָא","מֵי׳"]},"16510":{"h":"מָרְדָא","r":"M02534","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרַד\">מְרַד</a>) <i>rebellious</i>. <span class=\"citation\">Targ. Y. Deut. XX, 20</span> (ed. Amst. a. oth. <a href=\"#\" data-headword=\"מַרְדָּא I\">מַרְדָּא</a>).</div>","alt":[]},"16511":{"h":"מַרְדָּא I","r":"M02535","html":"<div class=\"sense\"><i>baker’s shovel</i>, v. <a href=\"#\" data-headword=\"מַרְדֶּה I\"><span dir=\"rtl\">מַרְדֶּה</span> I</a>.</div>","alt":[]},"16512":{"h":"מַרְדָּא II","r":"M02536","html":"<div class=\"sense\"> name of <i>a bird</i>, v. <a href=\"#\" data-headword=\"מַרְדֶּה II\"><span dir=\"rtl\">מֵרְדֶּה</span> II</a>.</div>","alt":[]},"16513":{"h":"מַרְדָּא III","r":"M02537","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מָרַד II\"><span dir=\"rtl\">מָרַד</span> II</a>) <i>moist, green</i>. <span class=\"citation\">Targ. Is. XVII, 6</span> (h. text <a href=\"#\" data-headword=\"פריה\">פריה</a>); cmp. <a href=\"#\" data-headword=\"רָדָא\">רָדָא</a>.</div>","alt":[]},"16514":{"h":"מִרְדָּא","r":"M02538","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָרַד\">ירד</a>; v. <a href=\"#\" data-headword=\"מֶדֶר\">מֶדֶר</a>) <i>ordure</i>, a material for vessels. <span class=\"citation\">Ab. Zar. 75ᵇ</span> <span dir=\"rtl\">מנא דמ׳</span> (some ed. <a href=\"#\" data-headword=\"מַרְדֶּה II\">מִרְדָּה</a>; Alf. <a href=\"#\" data-headword=\"מַרְמָרָא\">מרמרא</a>, v. Rabb. D. S. a. l. note) a <i>mirda</i> vessel (v. <a href=\"#\" data-headword=\"גָּלָל\">גָּלָל</a>); Tanḥ. ed. Bub. Ḥuck. 2 <span dir=\"rtl\">דמִרְדְּתָא</span>.</div>","alt":[]},"16515":{"h":"מַרְדָּאִיּוֹת","r":"M02539","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְדֵּעַ\">מַרְדֵּעַ</a></div>","alt":[]},"16516":{"h":"מַרְדֶּה I","r":"M02540","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (רָדָה II) <i>baker’s shovel, peel</i>. <span class=\"citation\">Tosef. Kel. B. Mets. III, 7</span>. <span class=\"citation\">Taan. 25ᵃ</span> (Var. <a href=\"#\" data-headword=\"מַרְדָּא I\">מַרְדָּא</a>).</div>","alt":[]},"16517":{"h":"מַרְדֶּה II","r":"M02541","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>mardeh</i> (<i>mardah</i>), name of a lowland bird. <span class=\"citation\">Ḥull. 65ᵇ</span> Ar. (ed. <a href=\"#\" data-headword=\"מַרְדָּא I\">מרדא</a>).</div>","alt":["מַרְדָה)"]},"16518":{"h":"מַרְדּוּ I","r":"M02542","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(?) <a href=\"#\" data-headword=\"מַרְדֶּה II\">same</a>. <span class=\"citation\">Ḥull. 62ᵇ</span> <span dir=\"rtl\">והיינו מ׳</span> and this (‘hen of the marsh’) is <i>mardu</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מ׳ זגיד</span> (Rashi <a href=\"#\" data-headword=\"מרי II\">מרה</a>), v. <a href=\"#\" data-headword=\"זָגֵיד\">זָגיד</a>.</div>","alt":[]},"16519":{"h":"מַרְדּוּ II","r":"M02543","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"מַרְדּוּתָא\">מַרְדּוּתָא</a></div>","alt":[]},"16520":{"h":"מַרְדּוּת I","r":"M02544","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (רָדָה I) <i>chastisement, punishment</i>. <span class=\"citation\">Ber. 7ᵃ</span> <span dir=\"rtl\">טובה מ׳ אחת וכ׳</span> one chastisement in the heart of man (self-reproach) is better than many lashes. <span class=\"citation\">Gen. R. s. 23</span>, beg. <span dir=\"rtl\">כולן לשון מ׳ הן</span> all (those names) have the meaning of chastisement; ib. s. 57 end. <span class=\"citation\">Ex. R. s. 42</span> (play on <span dir=\"rtl\">רד</span>, <span class=\"citation\">Ex. XXXII, 7</span>) <span dir=\"rtl\">מ׳ הם צריכים</span> they need chastisement. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">כל המונע בנו מן המ׳</span> he who refrains from punishing his son; a. e.—[Pl. <span dir=\"rtl\">מַרְדִּיּוֹת</span>. Tanḥ. M’tsora, ed. Bub. 3 <span dir=\"rtl\">אין המרדות הללו משלי וכ׳</span> (corr. acc.) these punishments do not come to thee by mistake (or suddenly, v. <a href=\"#\" data-headword=\"שֶׁלִי\">שֶׁלִי</a>, v. Bub. a. l. note 10), I have warned thee &amp;c.; Tanḥ. ed. 1 <span dir=\"rtl\">אין המרירות הזו וכ׳</span> (read: <span dir=\"rtl\">המַרְדּוּת</span>); <span class=\"citation\">Yalk. Lev. 558</span> <span dir=\"rtl\">אין המִדּוֹת הללו וכ׳</span>.]</div>","alt":[]},"16521":{"h":"מַרְדּוּת II","r":"M02545","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>rebellion, disobedience</i>.—<span dir=\"rtl\">מכת מ׳</span> (<a href=\"#\" data-headword=\"מָכוּת\">מכות</a>, abbrev. <span dir=\"rtl\">מ&quot;מ</span>) <i>punishment for disobedience</i>, left to the discretion of the court, contrad. to the Biblically ordained punishment <a href=\"#\" data-headword=\"מַלְקוּת\">(מַלְקוּת</a>). <span class=\"citation\">Naz. IV, 3</span> (<span class=\"citation\">23ᵃ</span>) <span dir=\"rtl\">אם אינה … תספוג מ׳ מ׳</span> if she cannot receive the lawful punishment of forty lashes, let her receive the punishment for rebellion. <span class=\"citation\">Keth. 45ᵇ</span>. <span class=\"citation\">Sabb. 40ᵇ</span>; <span class=\"citation\">Yeb. 52ᵃ</span>; <span class=\"citation\">Ḥull. 141ᵇ</span>. [Rashi: = <a href=\"#\" data-headword=\"רְדִיָּה\">רדיה</a>, ‘blows enforcing <i>submission</i>’, v. <a href=\"#\" data-headword=\"מֶרֶד I\">מֶרֶד</a> II a. <a href=\"#\" data-headword=\"מַרְדּוּת I\">preced.</a> w.]</div>","alt":[]},"16522":{"h":"מַרְדּוּתָא","r":"M02546","html":"<div class=\"sense\"> , <i>chastisement, correction</i> (corresp. to b. h. <a href=\"#\" data-headword=\"מוּסָר\">מוּסָר</a>). <span class=\"citation\">Targ. Ps. II, 10</span>. <span class=\"citation\">Targ. Prov. XXII, 15</span>. <span class=\"citation\">Targ. Y. II, Lev. XIX, 20</span> <span dir=\"rtl\">מרדו</span> (h. text <a href=\"#\" data-headword=\"בַּקְרַת\">בקרת</a>); a. e.—Pl. <span dir=\"rtl\">מַרְדָּוָותָא</span>. <span class=\"citation\">Targ. Y. ib. XXVI, 18</span>; <span class=\"citation\">23</span>.</div>","alt":["מַרְדּוּ I"]},"16523":{"h":"מַרְדּוּתָא II","r":"M02547","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"מַרְדּוּת II\"><span dir=\"rtl\">מַרְדּוּת</span> II</a>. <span class=\"citation\">Targ. I Sam. XX, 30</span>.</div>","alt":[]},"16524":{"h":"מַרְדְּיָא","r":"M02548","html":"<div class=\"sense\"><i>rudder</i>, v. <a href=\"#\" data-headword=\"מוּרְדְּיָא\">מוּרְדְּיָא</a>.</div>","alt":[]},"16525":{"h":"מָרְדְּיָא","r":"M02549","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְדֵי\">רְדֵי</a>) <i>ploughshare</i>. <span class=\"citation\">Targ. Ps. CXLI, 7</span> (ed. Wil. <span dir=\"rtl\">מְרָדַיָא</span>, corr. acc.).</div>","alt":[]},"16526":{"h":"*מִרְדִּין","r":"M02550","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מֵרַד\">מֵרְדָא</a>) <i>rebellious acts, political crimes</i>, esp. the unauthorized exercise of criminal jurisdiction by Jews under the Parthian government. <span class=\"citation\">B. Kam. 117ᵃ</span> עד האידנא מלכותא דיוונאי הוו … השתא פרסאי נינהו … ואמרי מ׳ מ׳ Ms. M. (v. Rabb. D. S. a. l. note) formerly the rulers were Greeks who cared not about bloodshed (execution by unauthorized courts), but now they are Persians (Parthians) who do care &amp;c., and cry, rebellion! rebellion!—<span class=\"citation\">B. Mets. 39ᵃ</span> <span dir=\"rtl\">בורח מחמת מ׳</span> who flees from persecution for political offenses; <span class=\"citation\">B. Bath. 38ᵇ</span>. [Hai Gaon derives our w. from the Persian, giving it the meaning of <i>murder</i>; Fl. to Levy Talm. Dict. III, p. 317ᵇ suggests <i>murdan</i>, to die.]</div>","alt":[]},"16527":{"h":"מרדין","r":"M02551","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 71</span> <span dir=\"rtl\">(<span dir=\"rtl\">גרדים</span>) <span dir=\"rtl\">גידין ומרדין</span></span>, v. <a href=\"#\" data-headword=\"גַּד I\"><span dir=\"rtl\">גַּד</span> I</a></div>","alt":[]},"16528":{"h":"מָרְדְּכַי","r":"M02552","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Mordecai</i>, </div><div class=\"sense\"><b>1)</b>  the uncle of Esther. <span class=\"citation\">Pes. 117ᵃ</span> מ׳ ואסתר אמרוהו M. and Esther recited (composed) those psalms of Hallel. <span class=\"citation\">Yeb. 24ᵇ</span>, v. <a href=\"#\" data-headword=\"גֵּר\">גֵּר</a>; a. fr.</div><div class=\"sense\"><b>—2)</b>  name of an Amora. <span class=\"citation\">Keth. 87ᵃ</span>. <span class=\"citation\">Ber. 31ᵃ</span>; a. fr.</div>","alt":[]},"16529":{"h":"מַרְדְּכִיתָא","r":"M02553","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (transpos. of <span dir=\"rtl\">מדרכ׳</span>; <a href=\"#\" data-headword=\"דְּרַךְ\">דְּרַךְ</a>; cmp. <a href=\"#\" data-headword=\"מִדְרָא\">מִדְרָא</a> for <a href=\"#\" data-headword=\"מַרְדָּא I\">מרדא</a> &amp;c.) <i>staff, crutch</i>. <span class=\"citation\">Targ. Y. Ex. XXI, 19</span> Ar. (ed. <span dir=\"rtl\">מורנית׳</span>, misplaced Var. <a href=\"#\" data-headword=\"מורנימא\">מורנימא</a>, corr. acc.).</div>","alt":[]},"16530":{"h":"מרדנין","r":"M02554","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Deut. 945</span> some ed., v. <a href=\"#\" data-headword=\"פּוֹרָן\">פּוֹרָן</a></div>","alt":[]},"16531":{"h":"מַרְדֵּעַ","r":"M02555","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">רדע</span> = <a href=\"#\" data-headword=\"רָדָה\">רדה</a> <i>to plough</i>) <i>the handle of the plough</i>, having on one end a broad iron blade <span dir=\"rtl\">(חרחור</span>), on the other a spud <a href=\"#\" data-headword=\"דָּֽרְבָן\">(דרבן</a>). <span class=\"citation\">Kel. XXV, 2</span>; <span class=\"citation\">Tosef. Kel. B. Bath. III, 5</span>. <span class=\"citation\">Num. R. s. 14</span>; <span class=\"citation\">Pesik. R. s. 3</span> <span dir=\"rtl\">המשנה … מ׳ וכ׳</span> the Mishnah calls it <i>mardeʿa</i>, whereas the Bible calls it <i>dar’ban</i> and <i>malmâd</i>. Ib.; <span class=\"citation\">Koh. R. to XII, 11</span> (phonetic etymol.) <span dir=\"rtl\">מר̇ד̇ע̇ שהוא מ̇ור̇ה ד̇עה̇ לפרה</span> <i>mardeʿa</i>, because it teaches the (ploughing) cow sense. <span class=\"citation\">B. Bath. II, 13</span> (<span class=\"citation\">27ᵇ</span>) <span dir=\"rtl\">מלא המ׳ על גבי המחרישה</span> as far as the handle protrudes over the plough (differ. in comment. which take our w. to mean <i>ox-goad</i>). Y. R. Hash. I, 58ᵃ bot. <span dir=\"rtl\">מלא מ׳ אחד</span> a distance equal to the length of &amp;c.—Pl. <span dir=\"rtl\">מַרְדֵּעִים</span>. Ib.—<span dir=\"rtl\">מַרְדֵּעוֹת</span> (fr. <span dir=\"rtl\">מַרְדֵּעָה</span> f.). <span class=\"citation\">Sabb. 12ᵇ</span>; <span class=\"citation\">149ᵃ</span> <span dir=\"rtl\">שתי מ׳</span> the height of two <i>m</i>.—<span class=\"citation\">R. Hash. 24ᵃ</span> (Ms. O. <span dir=\"rtl\">מדרגות</span>, v. Rabb. D. S. a. l. note 80); Tosef. ib. II (I), 2 <a href=\"#\" data-headword=\"מַרְדָּאִיּוֹת\">מַרְדָּאִיּוֹת</a> ed. Zuck. (Var. <span dir=\"rtl\">מרדעות</span>, <span dir=\"rtl\">מדרעות</span>).</div>","alt":[]},"16532":{"h":"מַרְדְּעָא","r":"M02556","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Syr. <span dir=\"rtl\">ברדעתא</span>, P. Sm. 604; Arab. barḍaʿat, v. Fr. Aram. Fremdw., p. 104) <i>a garment made up of patches</i>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד כות׳ 1) <span dir=\"rtl\">מ׳ אית ליה וכ׳</span> (ed. Wil. <span dir=\"rtl\">מדר׳</span>, corr. acc.) he has a garment made up of twenty four patches, v. <span dir=\"rtl\">אִיסְטְחָא II</span></div>","alt":[]},"16533":{"h":"מַרְדַּעַת","r":"M02557","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַרְדְּעָא\">preced.</a>) <i>pack-saddle</i> or <i>cushion</i>, consisting of patches. <span class=\"citation\">Sabb. V, 2</span> (<span class=\"citation\">52ᵇ</span>) <span dir=\"rtl\">חמור יוצא במ׳ וכ׳</span> an ass may be driven out (on the Sabbath) with the cushion tied on his back (as a protection from cold); ib. 53ᵃ. <span class=\"citation\">Tosef. Kil. V, 18</span> <span dir=\"rtl\">לא יתן את המ׳ וכ׳</span> one must not put a cushion of patches on his shoulder (on account of the mixture of stuffs, <a href=\"#\" data-headword=\"כִּלְאַיִם\">כִּלְאַיִם</a>). <span class=\"citation\">Y. Bicc. III, 65ᵈ</span> top <span dir=\"rtl\">הטלית שעליו כמ׳ וכ׳</span> his official cloak is as befitting to him as an ass’ pack-saddle; Midr. Sam. ch. VII; a. e.</div>","alt":[]},"16534":{"h":"מַרְדְּקָא","r":"M02558","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּרְדְּקָא\">מוּרְדְּקָא</a></div>","alt":[]},"16535":{"h":"מָרָדְתָּא","r":"M02559","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרַד\">מְרַד</a>) </div><div class=\"sense\"><b>1)</b> <i>running about, turbulent</i>. <span class=\"citation\">Targ. Prov. VII, 11</span> (Ms. <a href=\"#\" data-headword=\"מַרְדּוּתָא\">מרדותא</a>, read: <span dir=\"rtl\">מָרוֹדְ׳</span>).—</div><div class=\"sense\"><b>*2)</b>  <a href=\"#\" data-headword=\"כְּנִישָׁא\">כְּנִישְׁתָּא מ׳</a> name of a synagogue in Caesarea (<i>the turbulent synagogue</i>, v. Josephus B. J. II, 14, 5). <span class=\"citation\">Y. Naz. VII, 56ᵃ</span>; Y. Ber. III, 6ᵃ bot. <a href=\"#\" data-headword=\"מדרתא\">מדרתא</a> (ed. Krot. <span dir=\"rtl\">מדדתה</span>); <span class=\"citation\">Lam. R. to I, 3</span> <a href=\"#\" data-headword=\"מְדוּכְתָּא\">מדוכתא</a>; <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">מדוכת׳</span> (prob. to be read: <span dir=\"rtl\">מרודת׳</span>).</div>","alt":["(מָרְדֵתָא)"]},"16536":{"h":"מִרְדְּתָא","r":"M02560","html":"<div class=\"sense\">, Tanḥ. ed. Bub. Ḥuck. 2, v. <a href=\"#\" data-headword=\"מִרְדָּא\">מִרְדָּא</a></div>","alt":[]},"16537":{"h":"מָרָה I","r":"M02561","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b>  fem. of <a href=\"#\" data-headword=\"מַר II\"><span dir=\"rtl\">מַר</span> II</a>, <i>bitter</i>.</div><div class=\"sense\"><b>—2)</b> <i>bitter taste</i>. <span class=\"citation\">Y. Ber. VI, 10ᵃ</span> <span dir=\"rtl\">בטלה מָרָתָן</span> their bitter taste is gone.</div><div class=\"sense\"><b>—3)</b> <i>drop, poison</i> (v. <a href=\"#\" data-headword=\"אֶרֶס\">אֶרֶס</a>). <span class=\"citation\">Ter. VIII, 5</span> <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a> the serpent’s discharge.—Esp. <i>gall, bile</i>. <span class=\"citation\">Ḥull. III, 1</span>; a. fr.—<span class=\"citation\">B. Mets. 107ᵇ</span> (ref. to <span class=\"citation\">Ex. XXIII, 25</span>) <span dir=\"rtl\">זו מ׳</span> that means (overflow of) bile, v. <a href=\"#\" data-headword=\"חָלָה\">חָלָה</a>.—Trnsf. <i>austerity, gravity</i>. <span class=\"citation\">Cant. R. to IV, 4</span> (play on <a href=\"#\" data-headword=\"מַרְיָה\">מֹרִיָּה</a>) <span dir=\"rtl\">שממנו יוצאת מ׳ לעולם</span> (not <span dir=\"rtl\">יוצא</span>) from it austerity (responsibility) went forth to the world. <span class=\"citation\">Keth. 103ᵇ</span> <span dir=\"rtl\">זרוק מ׳ בתלמידים</span> cast bile among the students (be austere against them). <span class=\"citation\">Sifré Deut. 323</span> (ref. to <span class=\"citation\">Deut. XXXII, 32</span> <span dir=\"rtl\">אשכלת מררת</span>) <span dir=\"rtl\">הגדולים שבכם מָרָתָן פרוסה בכם כאשכל</span> as to the great among you, their bile (austere rebuke) is distributed among you as the juice in the grapes; Yalk. ib. 946 <span dir=\"rtl\">מרתן פרוסה בהן וכ׳</span> their bile is distributed within them.</div>","alt":[]},"16538":{"h":"מָרָה II","r":"M02562","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>Marah</i>, a station in the desert (so named from its bitter waters). <span class=\"citation\">Snh. 56ᵇ</span>; <span class=\"citation\">Hor. 8ᵇ</span>; a. e.</div>","alt":[]},"16539":{"h":"מָרָה III","r":"M02563","html":"<div class=\"sense\"><i>hoe</i>, v. <a href=\"#\" data-headword=\"מָר\"><span dir=\"rtl\">מָרָא</span> II</a>.</div>","alt":[]},"16540":{"h":"מָרָה IV","r":"M02564","html":"<div class=\"sense\"><b>1)</b> <i>to be fat</i>; </div><div class=\"sense\"><b>2)</b> <i>to be disobedient</i>, v. <a href=\"#\" data-headword=\"מרי I\"><span dir=\"rtl\">מרי</span> I</a>, II.</div>","alt":[]},"16541":{"h":"*מַרְהַבְיָא","r":"M02565","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*רְהַב\">רְהַב</a>) <i>pride, haughtiness</i>. <span class=\"citation\">Targ. Ps. XXXV, 16</span> (ed. Wil. <span dir=\"rtl\">מַדְחֲכַיָּא</span> (v. <a href=\"#\" data-headword=\"דְּחֵיךְ\">דְּחַךְ</a>) <i>sports</i>).</div>","alt":[]},"16542":{"h":"מַרְוָא","r":"M02566","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְוֵי\">רְוֵי</a>; cmp. Lat. salvia, v. Sm. Ant. s. v. Elelisphacos) <i>marva</i>, a medicinal plant; <a href=\"#\" data-headword=\"מַדְוֵי\">מ׳ חיוורא</a> <i>white marva, sage</i>. <span class=\"citation\">Sabb. 109ᵇ</span> (a defin. of <span dir=\"rtl\">אזוב יון</span>; Ms. M. <a href=\"#\" data-headword=\"מַדְוֵי\">מַדְוִי</a>, <a href=\"#\" data-headword=\"מַדְוֵי\">מַדְוְיָא</a>; cmp. <a href=\"#\" data-headword=\"*דָּווּתָא\">דָּווּתָא</a>).</div>","alt":[]},"16543":{"h":"מָרְוָא","r":"M02567","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַר IV\"><span dir=\"rtl\">מַר</span> IV</a>) <i>power, dominion; tyranny</i>. <span class=\"citation\">Targ. Nah. III, 14</span> <span dir=\"rtl\">אסגי מ׳ וכ׳</span> increase the yoke of tyranny and force them &amp;c. <span class=\"citation\">Targ. Is. XXVIII, 20</span>. <span class=\"citation\">Ib. XLVII, 2</span> Regia (ed. <a href=\"#\" data-headword=\"מְרוֹעָא\">מְרוֹעָא</a>).—V. <a href=\"#\" data-headword=\"מָרוּתָא\">מָרוּתָא</a>.</div>","alt":["מָרְוָוא"]},"16544":{"h":"מְרַוָּא","r":"M02568","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְוֵי\">רְוֵי</a>) <i>intoxicating drink</i>. <span class=\"citation\">Targ. Ps. LXIX, 13</span> Ms. (ed. <a href=\"#\" data-headword=\"מַרְוָת\">מַרְוָת</a>).—V. <a href=\"#\" data-headword=\"מְרַוֵּי\">מְרַוֵּי</a>.</div>","alt":[]},"16545":{"h":"מְרוּבֶּה","r":"M02569","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רָבָה\">רָבָה</a>) <i>large, numerous, frequent</i>; opp. <a href=\"#\" data-headword=\"מוּעָט\">מוּעָט</a>; pl. <span dir=\"rtl\">מְרוּבִּים</span>, <span dir=\"rtl\">מְרוּבּוֹת</span>. <span class=\"citation\">Ḥag. I, 5</span>; a. fr.—Sifra Tsav ch. XV, Par. 11 <span dir=\"rtl\">(<a href=\"#\" data-headword=\"מִדָּה\">מדה</a>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a></span> the more frequent act, v. <a href=\"#\" data-headword=\"מוּעָט\">מוּעָט</a>. <span class=\"citation\">Pes. 37ᵃ</span>; <span class=\"citation\">Bets. 22ᵇ</span> <span dir=\"rtl\">פת מ׳</span>, v. <a href=\"#\" data-headword=\"עָב I\"><span dir=\"rtl\">עָב</span> I</a>; a. fr.—<span class=\"citation\">R. Hash. 4ᵇ</span>, a. fr. <a href=\"#\" data-headword=\"מְרוּבֶּה\">מְרוּבֶּה</a> the larger sphere, v. <a href=\"#\" data-headword=\"מוּעָט\">מוּעָט</a>.—מְרוּבֶּה בְגָדִים <i>the priest distinguished by a larger number of official garments</i> (v. <span class=\"citation\">Yoma VII, 5</span>), i.e. <i>the high priest</i> during the second Temple when no anointing took place. Sifra Tsav, Par. 3, ch. V (ref. to <span class=\"citation\">Lev. IV, 5</span>) <span dir=\"rtl\">מ׳ ב׳ מנין</span> how do you know that the law refers to the high priest even when he has not been anointed? <span class=\"citation\">Hor. III, 4</span>. <span class=\"citation\">Ib. 12ᵃ</span>; a. fr.</div>","alt":["מְרוּבָּה"]},"16546":{"h":"מְרוּבָּע","r":"M02570","html":"<div class=\"sense\"><i>square</i>, v. <a href=\"#\" data-headword=\"רָבַע\">רָבַע</a>.</div>","alt":[]},"16547":{"h":"מָרוּד","r":"M02571","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"יָרַד\">יָרַד</a>; cmp. <a href=\"#\" data-headword=\"יָרוּד\">יָרוּד</a>), <a href=\"#\" data-headword=\"הִימְנוֹן\">הַמָּ׳</a> <i>the lowest, youngest</i>. <span class=\"citation\">Gen. R. s. 23</span>, beg. <span dir=\"rtl\">המ׳ שבכולם</span> Ar. s. v. <span dir=\"rtl\">המרוד</span> (ed. <span dir=\"rtl\">הבָּרוּר שבהם</span>).</div>","alt":[]},"16548":{"h":"מָרוֹד","r":"M02572","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (מָרַד I) <i>rebel</i>. <span class=\"citation\">Tosef. Maas. Sh. I, 5</span> <span dir=\"rtl\">מטבע מ׳</span> (not <span dir=\"rtl\">המטבע</span>, Var. <a href=\"#\" data-headword=\"מָדוֹר\">מדור</a>, corr. acc.) a coin issued by a rebel (Bar Kokhba); Y. ib. I, 52ᵈ top, v. <a href=\"#\" data-headword=\"מָרַד I\"><span dir=\"rtl\">מָרַד</span> I</a>.</div>","alt":[]},"16549":{"h":"מָרוֹד ²","r":"M02573","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Lev. XXIV, 10</span>. <span class=\"citation\">Targ. Y. I Num. XXIV, 19</span> (not <a href=\"#\" data-headword=\"מְרוֹרָא\">מרורא</a>); a. e.—Pl. <span dir=\"rtl\">מְרוֹדִין</span>, <span dir=\"rtl\">מְרוֹדַיָּא</span>. <span class=\"citation\">Targ. Job XXIV, 13</span> (ed. Wil. <span dir=\"rtl\">מָרְדִין</span>; oth. ed. <span dir=\"rtl\">מוֹרְדִין</span>). <span class=\"citation\">Targ. Is. XXX, 1</span>; a. e.</div>","alt":["מָרוֹדָא I"]},"16550":{"h":"מָרוֹד ³","r":"M02574","html":"<div class=\"sense\"> (or <a href=\"#\" data-headword=\"מָנִיכָא\">מְ׳</a>) m. (<a href=\"#\" data-headword=\"מְרַד\">מְרַד</a>; cmp. <a href=\"#\" data-headword=\"יָרוֹד\">יָרוֹד</a> a. b. h. <a href=\"#\" data-headword=\"מָרוּד\">מָרוּד</a>, pl. <span dir=\"rtl\">מְרוּדִים</span>) <i>running wild</i>, esp. <i>the wild ass</i>. <span class=\"citation\">Targ. O. Gen. XVI, 12</span> (h. text <a href=\"#\" data-headword=\"פרא\">פרא</a>). <span class=\"citation\">Targ. Job. VI, 5</span> (Var. <span dir=\"rtl\">ערודאה</span>). <span class=\"citation\">Ib. XXXIX, 5</span>; a. e.—Pl. <span dir=\"rtl\">מְרוֹדַיָּא</span>. <span class=\"citation\">Ib. XXIV, 5</span>.</div>","alt":["מָרוֹדָא II"]},"16551":{"h":"מְרוֹדָא","r":"M02575","html":"<div class=\"sense\"> (or <span dir=\"rtl\">מָ׳</span>) m. (<a href=\"#\" data-headword=\"מְרַד\">מְרַד</a>) <i>rebelliousness</i>. <span class=\"citation\">Targ. Ps. L, 16</span> (ed. Wil. <a href=\"#\" data-headword=\"מְרוֹמָא I\">מרומא</a>, corr. acc.).—Pl. <span dir=\"rtl\">מְרוֹדִין</span>, <span dir=\"rtl\">מְרוֹדַיָּא</span>. <span class=\"citation\">Targ. Lam. I, 5</span> <span dir=\"rtl\">מְרוֹדָהָא</span> (some ed. <span dir=\"rtl\">מרור׳</span>, corr. acc.). <span class=\"citation\">Targ. Ps. XXXII, 1</span>; <span class=\"citation\">5</span>.</div>","alt":[]},"16552":{"h":"מְרוֹדָנִית","r":"M02576","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (מָרַד II) <i>running</i>.—Pl. <span dir=\"rtl\">מְרוֹדָנִיֹּות</span>. <span class=\"citation\">Tosef. Bekh. V, 3</span> (ed. Zuck. <a href=\"#\" data-headword=\"מצודניות\">מצודניות</a>), v. <a href=\"#\" data-headword=\"צִירָן\">צִירָן</a></div>","alt":[]},"16553":{"h":"מַרְוָוא","r":"M02577","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְוָא\">מַרְוָא</a></div>","alt":[]},"16554":{"h":"מַרְוִוית","r":"M02578","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְוִית\">מַרְוִית</a></div>","alt":[]},"16555":{"h":"מָרְוְותָא","r":"M02579","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָרוּתָא\">מָרוּתָא</a></div>","alt":[]},"16556":{"h":"מרוח","r":"M02580","html":"<div class=\"sense\">, Y. Taan. IV, 65ᵇ bot., read: <a href=\"#\" data-headword=\"מִחְוַר\">מִחְוַר</a>, v. <a href=\"#\" data-headword=\"חֲוַר\">חֲוַר</a></div>","alt":[]},"16557":{"h":"מְרוֹחַ","r":"M02581","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"מָרַח\">מָרַח</a>) </div><div class=\"sense\"><b>1)</b>  (denom. of <span dir=\"rtl\">רוח</span>) <i>filled with air</i>. <span class=\"citation\">Bekh. VII, 5</span> (expl. <span class=\"citation\">Lev. XXI, 20</span>) <span dir=\"rtl\">כל שרוח וכ׳</span> he who has wind in his testicles; Tosef. ib. V, 4 (v. <a href=\"#\" data-headword=\"קֵילֵיטֵיס\">קילֵיטֵיס</a>); <span class=\"citation\">Yalk. Lev. 632</span>.</div><div class=\"sense\"><b>—2)</b>  (= <span dir=\"rtl\">מְמוֹרָח</span>, v. <a href=\"#\" data-headword=\"מָרַח\">מָרַח</a>) <i>smashed</i>. Ib. (R. Yishm.) <span dir=\"rtl\">שנמרחו וכ׳</span>; (Tosef. l. c. <a href=\"#\" data-headword=\"שָׁחוּף\">שחוף</a>).—[</div><div class=\"sense\"><b>3)</b>  <span dir=\"rtl\">מ׳ אשך</span> = <span dir=\"rtl\">מַרְאֵה חשֶׁךְ</span> <i>black complexion</i>. Bekh. l. c., opin. of R. Antigonos.]</div>","alt":[]},"16558":{"h":"מְרוּטָה","r":"M02582","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָרַט\">מָרַט</a>; sub. <a href=\"#\" data-headword=\"שַׂעֲרָה\">שערה</a>) <i>plucked hair</i>, nickname of a baldheaded person. <span class=\"citation\">Ex. R. s. 24</span>; Tanḥ. <span class=\"citation\">B’shall. 18</span>; <span class=\"citation\">Yalk. Ex. 255</span>.</div>","alt":[]},"16559":{"h":"מְרַוֵּי","r":"M02583","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְוֵי\">רְוֵי</a>) <i>intoxicating drink</i>. <span class=\"citation\">Targ. O. Lev. X, 9</span> (Y. <span dir=\"rtl\">מדעם מַרְוי</span>). <span class=\"citation\">Targ. Zech. XII, 2</span> <a href=\"#\" data-headword=\"מְרַוֵּי\">מַרְוֵי</a>.—V. <a href=\"#\" data-headword=\"מְרַוָּא\">מְרַוָּא</a>.</div>","alt":[]},"16560":{"h":"מְרַוְיָא","r":"M02584","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְוֵי\">רְוֵי</a></div>","alt":[]},"16561":{"h":"מַרְוִית","r":"M02585","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"רָוָה\">רָוָה</a>) <i>dripping olives</i>. <span class=\"citation\">Y. Maasr. I, 49ᵃ</span> top [read:] <span dir=\"rtl\">משיִרְווּ מ׳ שנייה וכ׳</span> from the time that the olives of the second year in the store-house begin to drip. (from the heat).</div>","alt":["מַרְוִיּוֹת"]},"16562":{"h":"מרויתא","r":"M02586","html":"<div class=\"sense\">, <span class=\"citation\">Y. Orl. I, 61ᵃ</span>, v. <a href=\"#\" data-headword=\"מַרְבִּיתָא\">מַרְבִּיתָא</a></div>","alt":[]},"16563":{"h":"מרוך","r":"M02587","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹרֶךְ\">מוֹרֶךְ</a></div>","alt":[]},"16564":{"h":"מרום","r":"M02588","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. B. Kam. I, 4</span> Var., v. <a href=\"#\" data-headword=\"מָרוּת\">מָרוּת</a></div>","alt":[]},"16565":{"h":"מֵרוֹם","r":"M02589","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Merom</i>. <span class=\"citation\">Y. Taan. IV, 68ᵇ</span> top; <span class=\"citation\">Y. Meg. IV, 75ᵃ</span> bot. <span dir=\"rtl\"><span dir=\"rtl\">לעזר בר מ׳</span>(א</span>); <span class=\"citation\">Treat. Sof’rim XXI, 7</span> <span dir=\"rtl\">ברבי מקום</span> (corr. acc.). <span class=\"citation\">Gen. R. s. 66</span> <span dir=\"rtl\">בן מֵרוֹן</span>; <span class=\"citation\">Cant. R. to VII, 1</span> <span dir=\"rtl\">ב&quot;ר מרון</span>; <span class=\"citation\">Ruth R. to II, 5</span> <a href=\"#\" data-headword=\"מִרְיָם\">מרים</a>; <span class=\"citation\">Yalk. ib. 601</span> <span dir=\"rtl\">מריון</span> (corr. acc.).</div>","alt":[]},"16566":{"h":"מָרוֹם","r":"M02590","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>height, on high</i>. <span class=\"citation\">Lev. R. s. 5</span>; <span class=\"citation\">Yalk. Is. 290</span>, v. <a href=\"#\" data-headword=\"חָצַב\">חָצַב</a>.—Pl. <span dir=\"rtl\">מְרוֹמִים</span>, constr. <a href=\"#\" data-headword=\"מְמוֹמֵי\">מְרוֹמֵי</a>. <span class=\"citation\">Nidd. 16ᵇ</span> (cit. fr. Ben Sira) <span dir=\"rtl\">המושיב שבת במ׳ קרת</span> he who places his (scholar’s) seat on the heights of the city.</div>","alt":[]},"16567":{"h":"מְרוֹמָא I","r":"M02591","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ps. LXXV, 6</span>; a. e.—<span class=\"citation\">Y. Taan. I, 64ᵇ</span> bot. <span dir=\"rtl\">מְרוֹם מובלה</span>, v. <a href=\"#\" data-headword=\"מוּבָל\">מוּבְלָא</a>.—Pl. <span dir=\"rtl\">מְרוֹמַיָּא</span>. <span class=\"citation\">Targ. Job XVI, 19</span>.</div>","alt":[]},"16568":{"h":"מְרוֹמָא II","r":"M02592","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרוֹמָא I\">preced.</a>) <i>uplifted</i>. <span class=\"citation\">Targ. Y. Ex. VI, 6</span>, v. <a href=\"#\" data-headword=\"מְרָמַם\">מְרָמַם</a>.</div>","alt":[]},"16569":{"h":"מְרוּמֶּה","r":"M02593","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רמי\">רָמָה</a>) <i>fraudulent</i>; <span dir=\"rtl\">דין מ׳</span> a case in which the court has reason to suspect legal trickery or conspiracy. <span class=\"citation\">Snh. 32ᵇ</span>. <span class=\"citation\">Shebu. 30ᵇ</span></div>","alt":[]},"16570":{"h":"מָרוֹן I","r":"M02594","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מרי II\">מָרָה</a>) <i>rebellion</i>; <span dir=\"rtl\">בני מ׳</span> <i>rebels</i> who surrender, v. <a href=\"#\" data-headword=\"*אִימְרָנָא\">אִימְרָנָא</a>. <span class=\"citation\">R. Hash. I, 2</span> (<span class=\"citation\">16ᵃ</span>) (differ. in comment.); v. also next w.—[<span class=\"citation\">B. Bath. I, 6</span> Ms. M., v. <a href=\"#\" data-headword=\"*מוֹרָן\">מוֹרָן</a>.]</div>","alt":[]},"16571":{"h":"מָרוֹן II","r":"M02595","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Beth Maron</i>, a place the access to which was by a narrow path. <span class=\"citation\">R. Hash. 18ᵃ</span> (expl. <span dir=\"rtl\">בני מרון</span>, v. <a href=\"#\" data-headword=\"מָרוֹן I\">preced.</a>) <span dir=\"rtl\">כמעלות בית מ׳</span> like going up the ascent to B. M. (in single file; Var. <span dir=\"rtl\">בית חורון</span>). <span class=\"citation\">Erub. 22ᵇ</span> (v. Rabb. D. S. a. l. note 20).—V. <a href=\"#\" data-headword=\"מֵרוֹן\">next w.</a></div>","alt":["בֵּית מָ׳"]},"16572":{"h":"מֵרוֹן","r":"M02596","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><b>1)</b>  pr. n. pl. <i>Meron</i>, in Galilee, south of Giscala. <span class=\"citation\">Y. Shebi. IX, 38ᵈ</span> bot. <span class=\"citation\">Tosef. Dem. IV, 13</span> <span dir=\"rtl\">מי׳</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"מירוק\">מירוק</a>). Tanḥ. ed. Bub., P’kudé 7 <span dir=\"rtl\">בקעה שעל פני מ׳ וכ׳</span> the valley in front of M., his native town; <span class=\"citation\">Ex. R. s. 52</span> <span dir=\"rtl\">בקעה אחת שעל פגי מרון</span> some ed. (corr. acc.). <span class=\"citation\">Cant. R. to VIII, 1</span> <span dir=\"rtl\">מי׳</span>; <span class=\"citation\">Ex. R. s. 5</span>, beg. <span dir=\"rtl\">בית מר׳</span> (not <span dir=\"rtl\">מד׳</span>). <span class=\"citation\">Y. Taan. IV, 68ᵈ</span> (in a fragmentary passage) <span dir=\"rtl\">מי׳ קרתה</span> Meron (in connection with Jojarib) designates the place (of the family).</div><div class=\"sense\"><b>—2)</b>  pr. n. m., v. <a href=\"#\" data-headword=\"מֵרוֹם\">מֵרוֹם</a>.—[<span class=\"citation\">Ḥull. 60ᵇ</span> <a href=\"#\" data-headword=\"מֵרוֹן\">מרון</a>, <span dir=\"rtl\">מירון</span> Ar., v. <a href=\"#\" data-headword=\"הֲמִירָם\">הֲמִירָם</a>.]</div>","alt":["מֵירוֹן"]},"16573":{"h":"מֵרוֹנָאָה","r":"M02597","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מֵרוֹן\">preced.</a>) <i>of Meron</i>.—Pl. <span dir=\"rtl\">מֵרוֹנָאֵי</span>. <span class=\"citation\">Koh. R. to XI, 2</span>; Pesik. B’shall., p. 94ᵃ sq. <span dir=\"rtl\">בני מֵרוֹנָיֵא</span>.</div>","alt":[]},"16574":{"h":"מֵרוֹנִי","r":"M02598","html":"<div class=\"sense\">, (or <a href=\"#\" data-headword=\"מֵרוֹנִי\">מָרוֹנִי</a> <i>of Maron</i>). <span class=\"citation\">B. Bath. 156ᵇ</span> (Ms. F. <a href=\"#\" data-headword=\"מדוני\">מָדוֹנִי</a>, v. Rabb. D. S. a. l. note 3); <span class=\"citation\">Kidd. 26ᵇ</span> <span dir=\"rtl\">מד׳</span>; <span class=\"citation\">Y. Peah IV, 17ᵈ</span> <span dir=\"rtl\">מד׳</span>.</div>","alt":[]},"16575":{"h":"מרוס","r":"M02599","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. B. Kam. I, 4</span>, v. <a href=\"#\" data-headword=\"מָרוּת\">מָרוּת</a></div>","alt":[]},"16576":{"h":"מְרוֹעָא","r":"M02600","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְעַע\">רְעַע</a>) (<i>evil</i>) <i>occurrence, visitation</i> (cmp. <a href=\"#\" data-headword=\"אֲרַע I\"><span dir=\"rtl\">אֲרַע</span> I</a>). <span class=\"citation\">Targ. Hos. XI, 7</span>. <span class=\"citation\">Targ. Mic. VI, 3</span>. <span class=\"citation\">Targ. Is. XLVII, 2</span> (v. <span dir=\"rtl\">מַרְוָא II</span>).</div>","alt":[]},"16577":{"h":"מרוּצָה I","r":"M02601","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>running</i>. <span class=\"citation\">Yalk. Gen. 109</span> <span dir=\"rtl\">הכיר בו שמְרוּצָתוֹ לרעה</span> (some ed. <span dir=\"rtl\">שמְרִיצָ׳</span>) he (Eliezer) recognized that his (Laban’s) running was for evil. <span class=\"citation\">Midr. Till. to Ps. LXIII</span> ed. Bub. <span dir=\"rtl\">היה רץ … במ׳</span> would run after the horse in speed.</div>","alt":[]},"16578":{"h":"מְרוּצָה II","r":"M02602","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>oppression, arrogance</i>. Ruth R. introd., v. <a href=\"#\" data-headword=\"טִירוּנְיָא\">טִירוּנְיָא</a></div>","alt":[]},"16579":{"h":"מָרוֹקָא I","r":"M02603","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָרַק\">מָרַק</a>) <i>a substance used for polishing</i>, prob. <i>pumice</i> (v. <a href=\"#\" data-headword=\"מָרֵקָה\">מָרֵקָה</a>). <span class=\"citation\">B. Mets. 47ᵃ</span>, sq. <span dir=\"rtl\">קונין במ׳</span> (Ar. ed. Koh. <span dir=\"rtl\">במרקא</span>) you may take vicarious possession with a vessel made of <i>maroḳa</i> (although it is too brittle for practical use; Tosaf.: ‘date-stones used for smoothing parchment’; Rashi: ‘a vessel made of baked ordure’, v. <a href=\"#\" data-headword=\"גָּלָל\">גָּלָל</a>). Ib. <a href=\"#\" data-headword=\"מוֹרִיקָא\">מוריקא</a> ed. (Ms. M. <a href=\"#\" data-headword=\"מָרוֹקָא I\">מרוקא</a>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"16580":{"h":"מָרוֹקָא II","r":"M02604","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מוֹרִיקָא\">מוֹרִיקָא</a>) <i>saffron-colored</i>.—Pl. <span dir=\"rtl\">מָרוֹקִין</span>. <span class=\"citation\">Targ. Esth. I, 6</span>.</div>","alt":[]},"16581":{"h":"מָרוֹר","r":"M02605","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  (adj.) <i>bitter</i>.—Pl. <span dir=\"rtl\">מְרוֹרִים</span>, <span dir=\"rtl\">מְרוֹרִין</span>. <span class=\"citation\">Snh. 108ᵇ</span>; <span class=\"citation\">Erub. 18ᵇ</span> <span dir=\"rtl\">יהיו מזונותי מ׳ וכ׳</span> let my food be bitter as an olive leaf but given at thy (the Lord’s) hand &amp;c.; a. e.</div><div class=\"sense\"><b>—2)</b> <i>bitter herb</i>, esp. <i>maror</i>, (cmp. πικρίς) a plant, prob. <i>Cichorium Itybus, Succory</i>. <span class=\"citation\">Pes. II, 6</span>, expl. <span class=\"citation\">ib. 39ᵃ</span> מרריתא דאגמא Ms. M. (ed. only <span dir=\"rtl\">מרירתא</span>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מה מ׳ תחילתו רך וכ׳</span> Ms. M. (ed. incorr.) as <i>maror</i> is soft (mild) in its beginning and hard (pungent) at its end (root). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ממאי דהאי מ׳ וכ׳</span> how can you tell that the <i>maror</i> (<span dir=\"rtl\">מְרֹרִים</span>, <span class=\"citation\">Ex. XII, 8</span>) means an herb, perhaps the gall of a <i>kufia</i> is meant? Ib. <span dir=\"rtl\">אימא מ׳ חד</span> but may I not say, <i>maror</i> means one certain species exclusively? Ib.ᵇ <span dir=\"rtl\">כל שיש בו טעם מ׳</span> whatever has the taste of <i>maror</i> (bitter, v. supra). Ib. <span dir=\"rtl\">מ׳ דרבנן</span> bitter herbs which are subject to tithes merely by rabbinical enactment; a. fr.—Pl. <span dir=\"rtl\">מְרוֹרִים</span>, <span dir=\"rtl\">מְרוֹרִין</span>. Ib.ᵃ; a. e.</div>","alt":[]},"16582":{"h":"מְרוֹרָא","r":"M02606","html":"<div class=\"sense\"><b>1)</b> <i>bitterness, bitter taste</i>. <span class=\"citation\">Targ. I Sam. XV, 32</span> מְרוֹר Regia, v. <a href=\"#\" data-headword=\"מָרִיר II\"><span dir=\"rtl\">מָרִיר</span> II</a>.—<span class=\"citation\">Ab. Zar. 31ᵇ</span> <span dir=\"rtl\">מ׳ דכשותא</span> the bitter sap of cuscuta.</div><div class=\"sense\"><b>—2)</b> <i>bitter herb</i>.—Pl. <span dir=\"rtl\">מְרוֹרִין</span>. Y. Meg. IV, 74ᵈ bot.; <span class=\"citation\">Y. Bicc. III, end, 65ᵈ</span>, v. <a href=\"#\" data-headword=\"יֵרוֹקָנָא\">ירֵוֹקָנָא</a>.—</div><div class=\"sense\"><b>*3)</b>  (trnsf.) <i>evil-doer</i>.—Pl. <span dir=\"rtl\">מְרוֹרַיָּא</span>. <span class=\"citation\">Targ. Y. I Deut. XXXII, 2</span> [prob. to be read: <span dir=\"rtl\">מְרוֹדַיָּא</span>, v. <a href=\"#\" data-headword=\"מָרוֹד ²\">מָרוֹדָא</a>.—<span class=\"citation\">Targ. Lam. I, 5</span> <span dir=\"rtl\">מרורהא</span>, v. <a href=\"#\" data-headword=\"מְרוֹדָא\">מְרוֹדָא</a>].</div>","alt":[]},"16583":{"h":"מְרוֹרָה","r":"M02607","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> ; <a href=\"#\" data-headword=\"מְרוֹרָא\">preced.</a> wds.) <i>venom</i>. <span class=\"citation\">Pirké d’R. El. ch. XIV</span> <span dir=\"rtl\">מְרוֹרַת פתנים</span>, v. <a href=\"#\" data-headword=\"פֶּתֶן\">פֶּתֶן</a>.—Pl. <a href=\"#\" data-headword=\"מְכוֹרוֹת\">מְרוֹרוֹת</a> <i>troubles, evils</i>. Esth. R. introd. to Par. 5 (ref. to <span dir=\"rtl\">מררת</span>, <span class=\"citation\">Deut. XXXII, 32</span>) <span dir=\"rtl\">הללו הביאו מ׳ לעולם</span> (some ed. <span dir=\"rtl\">מְרֹרוֹת</span>) it is they (the grapes) that brought troubles into the world; <span class=\"citation\">Lev. R. s. 12</span> <a href=\"#\" data-headword=\"מרירות\">מרירות</a> (corr. acc.); <span class=\"citation\">Gen. R. s. 15</span> <span dir=\"rtl\">אותן האשכלות הביאו מ׳ וכ׳</span>; <span class=\"citation\">Yalk. Deut. 946</span> (some ed. <span dir=\"rtl\">מר דו</span>, corr. acc.).</div>","alt":[]},"16584":{"h":"מרושא","r":"M02608","html":"<div class=\"sense\">, <span class=\"citation\">Erub. 69ᵃ</span> Ms. O., v. <a href=\"#\" data-headword=\"*מְדוּשָּׁא\">מְדוּשָּׁא</a></div>","alt":[]},"16585":{"h":"מרושין","r":"M02609","html":"<div class=\"sense\"><i>vessels</i> (?). <span class=\"citation\">Y. Ter. VIII, 45ᵈ</span> bot. <span dir=\"rtl\">ושוי … על ארבעה מ׳ דמיין</span> (prob. to be read: <a href=\"#\" data-headword=\"חַרְשִׁין\">חרשׂין</a> = <span dir=\"rtl\">חרסין</span>, v. <a href=\"#\" data-headword=\"חֶרֶס I\"><span dir=\"rtl\">חֶרֶס</span> I</a>) and he put the posts of his bedstead into four vessels filled with water (cmp. <span class=\"citation\">Ab. Zar. 32ᵃ</span>; Y. ib. II, 41ᵇ <span dir=\"rtl\">לסמוך המטה</span>).</div>","alt":[]},"16586":{"h":"מרושניא","r":"M02610","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשְׁרוּנְיָא\">מַשְׁרוּנְיָא</a></div>","alt":[]},"16587":{"h":"מַרְוָת","r":"M02611","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>intoxicating drink</i>, v. <a href=\"#\" data-headword=\"מְרַוָּא\">מְרַוָּא</a>.</div>","alt":[]},"16588":{"h":"מָרוּת","r":"M02612","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָר\">מָר</a>) </div><div class=\"sense\"><b>1)</b> <i>authority, dominion</i>. <span class=\"citation\">Pesik. R. s. 40</span> (play on <a href=\"#\" data-headword=\"מַרְיָה\">מֹרִיָּה</a>) <span dir=\"rtl\">ארץ שמָרוּתוֹ … בתוכה</span> (not <span dir=\"rtl\">לתוכה</span>) the district in which the lordship of the world resides; <span dir=\"rtl\">ואף המקום מ׳ הוא על וכ׳</span> and the place, too, is the ruler of all other places (ref. to <span dir=\"rtl\">בעלתה</span>, <span class=\"citation\">I Chr. XIII, 6</span>, as a surname of Zion, v. <a href=\"#\" data-headword=\"בַּעֲלָה\">בַּעֲלָה</a>). <span class=\"citation\">Ber. 48ᵃ</span> (in Chald. dict.) <span dir=\"rtl\">קא חזית דלא מקבלי מ׳</span> you see that they (the Pharisees) recognize no (royal) authority.</div><div class=\"sense\"><b>—2)</b> <i>domestication</i>. <span class=\"citation\">Sabb. 106ᵇ</span> (v. <a href=\"#\" data-headword=\"דְּרוֹר\">דְּרוֹר</a>) <span dir=\"rtl\">שאינה מקבלה מ׳</span> it does not submit to domestication. <span class=\"citation\">Tosef. B. Kam. I, 4</span> אם היו מ׳ Var. in ed. Zuck. (sub. <span dir=\"rtl\">של</span>; ed. <a href=\"#\" data-headword=\"מרום\">מרום</a>, <a href=\"#\" data-headword=\"מרוס\">מרוס</a>; ed. Zuck. <a href=\"#\" data-headword=\"תַּרְבּוּת\">תַּרְבּוּת</a>) if they (the animals) were domesticated, opp. <span dir=\"rtl\">באו מן המדבר</span>.</div>","alt":[]},"16589":{"h":"מָרוּתָא","r":"M02613","html":"<div class=\"sense\">, <i>authority, dominion</i> (v. <a href=\"#\" data-headword=\"מָרְוָא\">מָרְוָא</a>). <span class=\"citation\">Targ. I Sam. I, 11</span> (v. <a href=\"#\" data-headword=\"מוֹרָה II\"><span dir=\"rtl\">מוֹרָה</span> II</a>). <span class=\"citation\">Targ. Ez. XVI, 9</span> <a href=\"#\" data-headword=\"מָרוּתָא\">מַרְוָתָא</a> ed. Wil.; a. fr.—<span class=\"citation\">Gen. R. s. 55</span> (play on <a href=\"#\" data-headword=\"מַרְיָה\">מֹרִיָּה</a>) <span dir=\"rtl\">אתר מרוו׳ דעלמא</span> ed. Wil. (oth. ed. <a href=\"#\" data-headword=\"מָרוּתָא\">מרותא</a>) the seat of the dominion of the world, v. preced.—Pl. <a href=\"#\" data-headword=\"מָרְוְותָא\">מַרְוָותָא</a>, v. <a href=\"#\" data-headword=\"מָר\">מָר</a>.</div>","alt":["מָרְוְתָא","מָרְוְו׳"]},"16590":{"h":"מַרְזֵב","r":"M02614","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רזב\">רזב</a>, transpos. of <a href=\"#\" data-headword=\"בְּרַז\">ברז</a>; cmp. <a href=\"#\" data-headword=\"בָּרֵיז\">בָּרֵיז</a>) </div><div class=\"sense\"><b>1)</b> <i>tube, spout;</i> esp. <i>the movable tube attached to the roof gutters</i> <a href=\"#\" data-headword=\"מַזְחִילָה\">(מַזְחִילָה</a>). <span class=\"citation\">B. Bath. III, 6</span> <span dir=\"rtl\">המ׳ אין לו חזקה</span> no claim, based on undisturbed use, can be made for the special position of the pipe discharging the water into the neighbor’s yard; expl. <span class=\"citation\">ib. 58ᵇ</span>; Y. ib. III, end, 14ᵇ <span dir=\"rtl\">מקום המ׳ בחצר יש … מקום קילוחו וכ׳</span> the right of a pipe for the discharge of water into the neighbor’s court can be claimed on the basis of undisturbed use, but not the special place of its discharge; (<span class=\"citation\">Tosef. ib. II, 13</span> <span dir=\"rtl\">צינור</span>). <span class=\"citation\">Yeb. 75ᵇ</span> <span dir=\"rtl\">כמ׳</span> if the mutilated membrum has the shape of a spout (leaving the urinary canal unprotected). <span class=\"citation\">Sabb. 146ᵇ</span> <span dir=\"rtl\">גזירה משום מ׳</span> it is forbidden, lest he shape a regular tapping tube (v. <a href=\"#\" data-headword=\"בִּרְזָא I\"><span dir=\"rtl\">בִּרְזָא</span> I</a>).</div><div class=\"sense\"><b>—2)</b>  a sort of <i>cape</i>, having the shape of a gutter, formed by throwing the edges of a garment over the shoulders backward. Ib. 147ᵃ, v. <a href=\"#\" data-headword=\"כִּיס ²\">כִּיסָא</a>.</div>","alt":[]},"16591":{"h":"מַרְזְבָא","r":"M02615","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job XXXVIII, 25</span> <span dir=\"rtl\">מַרְזְ׳</span> (ed. Lag. <a href=\"#\" data-headword=\"מַרְזֵחָא\">מַרְזֵי׳</a>).—<span class=\"citation\">Ḥull. 105ᵇ</span> <span dir=\"rtl\">אותבוה תותי מרזי׳</span> they put it under a spout. <span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">תותי מרזב׳</span>.—Pl. <span dir=\"rtl\">מַרְזְבִין</span>, <span dir=\"rtl\">מַרְזְבֵי</span>, <span dir=\"rtl\">מַרְזְבַיָּא</span>, <a href=\"#\" data-headword=\"מַרְזֵחָא\">מַרְזֵי׳</a>. <span class=\"citation\">Targ. Koh. II, 8</span> (h. text <span dir=\"rtl\">שדה ושדות</span>). <span class=\"citation\">Targ. Job XXVIII, 4</span>; a. e.—<span class=\"citation\">Snh. 109ᵃ</span>; <span class=\"citation\">M. Kat. 25ᵇ</span> <span dir=\"rtl\">מ׳ דציפורי</span> the spouts of the roofs of Sepphoris.</div>","alt":["מַרְזֵיבָא"]},"16592":{"h":"מַרְזַבְנָא","r":"M02616","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. marzbân, Vullers II, 1161) [<i>custodian of borderland</i>,] <i>prefect, duke</i>.—Pl. <a href=\"#\" data-headword=\"מַרְזַבְנָא\">מַרְזַבְנֵי</a>. <span class=\"citation\">Meg. 6ᵇ</span> (Ms. O. <a href=\"#\" data-headword=\"מַרְזוּבְנָן\">מַרְזוּבְנָן</a>, v. Rabb. D. S. a. l. notes 70 a. 90).</div>","alt":[]},"16593":{"h":"מַרְזַבְתָּא","r":"M02617","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְזַפְתָּא\">מַרְזַפְתָּא</a></div>","alt":[]},"16594":{"h":"מַרְזוּ","r":"M02618","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רזֵי\">רְזֵי</a></div>","alt":[]},"16595":{"h":"מַרְזוֹבוֹת","r":"M02619","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַרְזוֹפָא\">מַרְזוֹפָא</a>) <i>hammers</i>, as instruments of torture. <span class=\"citation\">Lev. R. s. 27</span> במ׳ ובמגלבין Ar. (ed.; <span class=\"citation\">Num. R. s. 10</span>, beg.; <span class=\"citation\">Cant. R. to V, 16</span> <span dir=\"rtl\">בנור ובזפת</span>, read: <span dir=\"rtl\">במַרְזֵפוֹת</span> or <span dir=\"rtl\">במַרְזְפָתָא</span>) with hammers and whips.</div>","alt":[]},"16596":{"h":"מַרְזוּבְלֵי","r":"M02620","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רזב\">רזב</a>, transpos. of <a href=\"#\" data-headword=\"בְּרַז\">ברז</a>, as in <a href=\"#\" data-headword=\"מַרְזֵב\">מַרְזֵב</a>; cmp. <a href=\"#\" data-headword=\"*בּוּרְיָא II\"><span dir=\"rtl\">בּוּרְיָא</span> II</a>, חוֹצֶלֶת &amp;c.) <i>mats</i> (used for partitions), <i>matting</i>. <span class=\"citation\">Succ. 20ᵃ</span>, explaining <span dir=\"rtl\">חוצלות</span> (v. <a href=\"#\" data-headword=\"חוֹצֶלֶת\">חוֹצֶלֶת</a>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a> (some ed. <span dir=\"rtl\">מרזובלים</span>); <span class=\"citation\">ib.</span> <span dir=\"rtl\">מאי מ׳ … מזבלי וכ׳</span> what is <i>marzublé?</i> R. A. (judging by phonetic resemblance) says, bags filled with foliage; R. S. says, real matting. Ib. <span dir=\"rtl\">מ׳ של וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">מרזובלים</span>).</div>","alt":[]},"16597":{"h":"מַרְזוּבְנָן","r":"M02621","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְזַבְנָא\">מַרְזַבְנָא</a></div>","alt":[]},"16598":{"h":"מַרְזוֹחַ","r":"M02622","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַרְזֵחַ\">מַרְזֵחַ</a>) <i>banqueters, merry-makers</i>. <span class=\"citation\">Lev. R. s. 5</span> (ref. to <span class=\"citation\">Am. VI, 7</span>) [read:] <span dir=\"rtl\">מהו מרזח סרוחים מרזח מ׳</span> what is <i>mirzaḥ s’ruḥim?</i> The banqueting of the feasters.</div>","alt":["מַרְזוֹחִים"]},"16599":{"h":"מַרְזוֹפָא","r":"M02623","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">רזף</span>, transpos. of <a href=\"#\" data-headword=\"פָּרַז\">פרז</a>; cmp. <a href=\"#\" data-headword=\"מַרְזֵב\">מַרְזֵב</a>) <i>hammer</i> (= h. <a href=\"#\" data-headword=\"מַקֶּבֶת\">מַקֶּבֶת</a>).—Pl. <span dir=\"rtl\">מַרְזוֹפִין</span>. <span class=\"citation\">Targ. Ps. LXXIII, 10</span> (h. text <a href=\"#\" data-headword=\"הָלַם\">הֲלֹם</a>, v. <a href=\"#\" data-headword=\"הָלַם\">הָלַם</a>). <span class=\"citation\">Ib. LXXIV, 6</span> <span dir=\"rtl\">מחין כבמ׳</span> (some ed. <span dir=\"rtl\">בכמר׳</span>, ed. Wil. <span dir=\"rtl\">במ׳</span>, corr. acc.; h. text <span dir=\"rtl\">יַהֲלֹמ׳</span>).—V. <a href=\"#\" data-headword=\"מַרְזַפְתָּא\">מַרְזַפְתָּא</a>.</div>","alt":[]},"16600":{"h":"מַרְזֵחַ","r":"M02624","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>merry-making, banquet</i>, also <i>the banquet given to mourners to cheer them up</i>. <span class=\"citation\">Lev. R. s. 5</span>, v. <a href=\"#\" data-headword=\"מַרְזוֹחַ\">מַרְזוֹחַ</a>.—[<span class=\"citation\">M. Kat. 28ᵇ</span>, v. <a href=\"#\" data-headword=\"מַר II\"><span dir=\"rtl\">מַר</span> II</a>.]—Pl. <a href=\"#\" data-headword=\"מַרְזוֹחַ\">מַרְזֵחִים</a>, <span dir=\"rtl\">מַרְזֵחִין</span>, <a href=\"#\" data-headword=\"מַרְזֵחָא\">מַרְזֵי׳</a>. <span class=\"citation\">Sifré Num. 131</span> <span dir=\"rtl\">חזרו לעשות להם מ׳</span> they (the Moabites) again arranged (idolatrous) banquets for them. <span class=\"citation\">Koh. R. to VII, 1</span>, end <span dir=\"rtl\">הכל סופדין עושה לו מ׳ …</span> all people lament and clap hands over the death of the righteous man (Samuel), and this wicked man (Nabal) holds banquets; <span class=\"citation\">Yalk. Sam. 134</span>; Midr. Sam. ch. XXIII. <span class=\"citation\">Esth. R. to I, 2</span>; <span class=\"citation\">ib. to I, 9</span>; a. e.</div>","alt":[]},"16601":{"h":"מַרְזֵחָא","r":"M02625","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מַרְזֵחַ\">same</a>. <span class=\"citation\">Keth. 69ᵃ</span>, v. infra.—Pl. <span dir=\"rtl\">מַרְזְחִין</span>, <span dir=\"rtl\">מַרְזֵיחִין</span>. <span class=\"citation\">Targ. Am. VI, 7</span>. <span class=\"citation\">Targ. Y. I Num. XXV, 2</span> (v. <span class=\"citation\">Sifré Num. 131</span>, quot. in <a href=\"#\" data-headword=\"מַרְזֵחַ\">preced.</a>).—Esp. (<i>banquet</i>) <i>exhilarating the mourner;</i> (<a href=\"#\" data-headword=\"בֵּיתָא I\">בֵּית</a>) <a href=\"#\" data-headword=\"מְשָׁכָא\">בֵּי מ׳</a> <i>the place of the mourners’ meal</i>. <span class=\"citation\">Targ. Jer. XVI, 5</span>.—<span class=\"citation\">Keth. 69ᵃ</span> <span dir=\"rtl\">מאן יתיב בי מ׳ וכ׳</span> who sits at the head at mourners’ meals? expl. <span class=\"citation\">ib. 69ᵇ</span> <span dir=\"rtl\">מהו מ׳ אֵבֶל</span> (<i>be</i>-) <i>marzeḥa</i> means (house of) mourning (ref. to Jer. l. c.).</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"מַרְזוֹחַ\">מַרְזוֹחַ</a>) pl. <span dir=\"rtl\">מַרְזְחַיָּיא</span> <i>those who cheer the mourners</i>. Targ. II Esth. I, 3 ed. Frf. (v. <a href=\"#\" data-headword=\"מְסַחֲרַיָּא\">מְסַחֲרַיָּא</a>).—Y. Ber. III, 6ᵃ top (reprehending the excesses at mourners’ meals). <span dir=\"rtl\">לאתקבלון … למחר מ׳</span> (not <span dir=\"rtl\">מזרח׳</span>) after my death do not receive today mourning (condolence) and to-morrow merry-makers.</div>","alt":["מַרְזֵי׳"]},"16602":{"h":"מַרְזֵיבָא","r":"M02626","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְזְבָא\">מַרְזֵבָא</a></div>","alt":[]},"16603":{"h":"מַרְזֵיחַ","r":"M02627","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְזֵחַ\">מַרְזֵחַ</a>, <a href=\"#\" data-headword=\"מַרְזֵחָא\"><a href=\"#\" data-headword=\"מַרְזֵחָא\">מַרְזֵחָא</a>.</a></div>","alt":["מַרְזֵיחָא"]},"16604":{"h":"מַרְזְמָא","r":"M02628","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*מוּרְזְמָה\">מוּרְזְמָה</a></div>","alt":[]},"16605":{"h":"מַרְזַפְתָּא","r":"M02629","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"אַרְזַפְתָּא I\"><span dir=\"rtl\">אַרְזַפְתָּא</span> I</a>, <i>hammer</i>. <span class=\"citation\">Targ. Jud. IV, 21</span> (quot. in Rashi to <span class=\"citation\">Ber. 34ᵃ</span> top; ed. <a href=\"#\" data-headword=\"אָרָמוּתָא\">אַרְ׳</a>).—<span class=\"citation\">Ber. 34ᵃ</span> <span dir=\"rtl\">מחינן ליה במ׳ דנפחא</span> we strike him with a smith’s hammer, i.e. he must be taught his duty; <span class=\"citation\">Meg. 25ᵃ</span> (some ed. <a href=\"#\" data-headword=\"אָרָמוּתָא\">אר׳</a>). Tanḥ. Ḥuck. 1; (<span class=\"citation\">Gitt. 56ᵇ</span> <a href=\"#\" data-headword=\"אָרָמוּתָא\">אר׳</a>).</div>","alt":[]},"16606":{"h":"מָרַח","r":"M02630","html":"<div class=\"sense\"><i>to soften; to poultice</i>.</div><div class=\"sense\"><b>Pi. מֵירֵחַ</b> <div class=\"sense\"><b>1)</b> <i>to strike a plaster, rub a salve;</i> in gen. <i>to mash, crush</i>. <span class=\"citation\">Tosef. Sabb. V</span> (<span class=\"citation\">VI), 6</span> <span dir=\"rtl\">המְמָרֵחַ בשבת</span> he who mashes ingredients for a plaster on the Sabbath; <span class=\"citation\">Erub. 102ᵇ</span>; Y. ib. X, 26ᶜ.—<span class=\"citation\">Sabb. 75ᵇ</span> <span dir=\"rtl\">הממ׳ רטיה וכ׳</span> he who spreads and presses the poultice over a sore; Y. ib. VII, 10ᵈ top. Ib. XXII, 3 (146ᵃ) he must not put on wax <span dir=\"rtl\">מפני שהוא ממרח</span> (Mish. Pes. <span dir=\"rtl\">מַמְרִיחַ</span>, v. Rabb. D. S. a. l. note 90) because it is an act resembling the spreading of plaster. Sifra Sh’mini, Par. 8, ch. X; <span class=\"citation\">Kel. V, 11</span> <span dir=\"rtl\">מֵרְחָהּ בטיט</span> if he smeared clay over it; <span class=\"citation\">Tosef. Kel. B. Kam. IV, 10</span>; <span class=\"citation\">12</span>. <span class=\"citation\">Ib. VII, 10</span> <span dir=\"rtl\">ומי׳ שפתותיה עם הכותל</span> and connected its rims with the wall by plaster or pitch; a. fr.—Part. pass. <span dir=\"rtl\">מְמוֹרָח</span> <i>crushed</i>. <span class=\"citation\">Bekh. 44ᵇ</span> <span dir=\"rtl\">האי ממ׳ אשך וכ׳</span> (not <span dir=\"rtl\">ממרוח</span>) if <i>m’roaḥ</i> meant <i>crushed</i>, it ought to read <i>m’moraḥ</i> &amp;c.; <span class=\"citation\">Yalk. Lev. 632</span>, v. <a href=\"#\" data-headword=\"מְרוֹחַ\">מְרוֹחַ</a>.</div><div class=\"sense\"><b>—2)</b> <i>to pass</i> (the hand) <i>over a viscid mass, to wipe off, rub off</i>. Y. Sabb. VII, 10ᵃ bot. <span dir=\"rtl\">מְמָרְחוֹ בידו אחת</span> he may wipe (or brush) it off with one hand; (Bab. <span class=\"citation\">ib. 141ᵃ</span> <span dir=\"rtl\">מגרר בצפרן</span>).</div><div class=\"sense\"><b>—3)</b> <i>to give a pile of grain an even shape, to finish the process of storing up.</i> <span class=\"citation\">Maasr. I, 6</span> <span dir=\"rtl\">משיְמָרֵחַ ואם אינו מְמָרֵחַ וכ׳</span> (Y. ed. <span dir=\"rtl\">מְמָרֵיחַ</span> or <span dir=\"rtl\">מַמְרִיחַ</span>) (is subject to tithes) as soon as he evens the pile, and if he does not even &amp;c.; expl. Y. ib. I, 49ᵃ bot. <span dir=\"rtl\">מן דו ישפר וכ׳</span> when he gives a finish to the surface of the pile. Ib. <span dir=\"rtl\">בשאין בדעתו למָרֵחַ</span> (not <span dir=\"rtl\">לימרח</span>) when he has not the intention to even the pile; a. fr.—Part. pass. <span dir=\"rtl\">מְמוֹרָח</span>, f. <span dir=\"rtl\">מְמוֹרַחַת</span>; pl. <span dir=\"rtl\">מְמוֹרָחִין</span>; <span dir=\"rtl\">מְמוֹרָחוֹת</span>. <span class=\"citation\">Bekh. 11ᵃ</span>, sq. <span dir=\"rtl\">טבלים ממ׳</span> (Ar. <span dir=\"rtl\">מְרוּחִים</span>) untithed grain stored up in proper shape. Y. Peah IV, 16ᶜ bot. <span dir=\"rtl\">כרי ממ׳</span> a finished pile; a. e.—<span class=\"citation\">Tosef. Ter. IV, 15</span> <a href=\"#\" data-headword=\"מוּרַחַת\">מוּרַחַת</a> = <span dir=\"rtl\">ממורחת</span>.</div><div class=\"sense\"><b>—4)</b>  (denom. of <a href=\"#\" data-headword=\"רַחַת\">רַחַת</a>) <i>to winnow</i>. Part. pass. as ab. <span class=\"citation\">Tosef. Maasr. II, 17</span> <span dir=\"rtl\">מצא תבואה ממ׳ עשויה כרי וכ׳</span> if one finds winnowed grain (which has been abandoned), if it is made up into a pile, you dare not take it, opp. <span dir=\"rtl\">מפוזרת</span> scattered; Y. ib. III, 50ᶜ bot. <span dir=\"rtl\">פירות ממורחין</span>.</div></div><div class=\"sense\"><b>Nif. נִמְרַח</b> <div class=\"sense\"><b>1)</b> <i>to be crushed into a viscid mass</i>. <span class=\"citation\">Bekh. VII, 5</span> (expl. <span dir=\"rtl\">מרוח אשך</span>, <span class=\"citation\">Lev. XXI, 20</span>) <span dir=\"rtl\">כל שנִמְרְחוּ אשכיו</span> (Bab. ed., 44ᵇ, <span dir=\"rtl\">נימחו</span>) whose testicles are crushed; (refuted ib. in Ib.) <span dir=\"rtl\">האי ממורח וכ׳</span>, v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to be smeared over</i>. <span class=\"citation\">Tosef. Kel. B. Kam. VII, 10</span> <span dir=\"rtl\">עד שתִּמָּרֵחַ עם השפה</span> until it is smeared over so as to be even with the rim.</div></div><div class=\"sense\"><b>Hithpa. הִתְמָרֵחַ</b> </div><div class=\"sense\"><b>Nithpa. נִתְמָרֵחַ</b> <div class=\"sense\"><i>to be shaped into an even pile, to be finished</i>. Y. Peah I, beg. 15ᵃ <span dir=\"rtl\">עד שלא נתמ׳ הכר</span> as long as the pile is not struck off; a. e. [Y. Maasr. I, 49ᵃ bot. <span dir=\"rtl\">תבואה משיתמרח</span>, read: <span dir=\"rtl\">משימרח</span>, v. supra.]</div></div>","alt":[]},"16607":{"h":"מְרַח I","r":"M02631","html":"<div class=\"sense\"><i>Pa</i>. <a href=\"#\" data-headword=\"מָרַח\">מַרַח</a> same, <i>to strike off the pile, finish</i>. <span class=\"citation\">Bekh. 11ᵇ</span> <span dir=\"rtl\">דמַרְחִינְהוּ מאן</span> who, do you mean, finished the pile?</div>","alt":[]},"16608":{"h":"מְרַח II","r":"M02632","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"רִיחַ\">רוּחַ</a>) <i>to blow up</i>.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מָרִיחַ\">מָרִיחַ</a> <i>haughty, bold</i>. <span class=\"citation\">Targ. Prov. XIV, 13</span> (ed. Wil. <a href=\"#\" data-headword=\"מדיח\">מדיח</a>, corr. acc.; h. text <a href=\"#\" data-headword=\"סוּג\">סוג</a>).—V. <a href=\"#\" data-headword=\"מְרִיחָא\">מְרִיחָא</a>.</div>","alt":[]},"16609":{"h":"מְרַחֲמָא","r":"M02633","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַם\">רְחַם</a>) <i>friend</i>.—Pl. <span dir=\"rtl\">מְרַחֲמִין</span>, <span dir=\"rtl\">מְרַחֲמֵי</span>. <span class=\"citation\">Targ. Lam. I, 19</span>. <span class=\"citation\">Targ. O. Gen. XXVI, 26</span> <a href=\"#\" data-headword=\"מְרַחֲקָא\">מֵרַ׳</a> (ed. Berl. <span dir=\"rtl\">רחמוהי</span>, v. Berl. Targ. O. II, p. 10); <span class=\"citation\">Gen. R. s. 65</span> <a href=\"#\" data-headword=\"מְרַחֲקָא\">מְרַ׳</a>.—<span class=\"citation\">Sabb. 32ᵃ</span>, v. <a href=\"#\" data-headword=\"בִּזְיוּנָא I\"><span dir=\"rtl\">בִּזְיוּנָא</span> I</a>.</div>","alt":[]},"16610":{"h":"מְרַחְמָנָא","r":"M02634","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרַחֲמָא\">preced.</a>) <i>friendly, compassionate</i>.—Pl. <a href=\"#\" data-headword=\"מְרַחְמָנָא\">מְרַחְמָנֵי</a>. Targ. II Esth. I, 2 (3) <span dir=\"rtl\">נבייא מ׳</span> (ed. Lag. a. oth. <span dir=\"rtl\">מְרַחְמוֹנֵי</span>). Ib. <span dir=\"rtl\">אמהתא מְרַחֲמַנְיָא</span> (Var. for <span dir=\"rtl\">מהימנייא</span>, read: <span dir=\"rtl\">מְרַחֲמַנְיָין</span>).</div>","alt":[]},"16611":{"h":"מֶרְחָץ","r":"M02635","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"רָחַץ\">רָחַץ</a>) <i>bath</i>. <span class=\"citation\">Y. Ber. IX, 14ᵇ</span> top <span dir=\"rtl\">תפילת המ׳</span> prayer on entering and on leaving the bath-house. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מ׳ שהיא נסוקת</span> a heated (vapor) bath. <span class=\"citation\">Ab. Zar. III, 4</span>, v. <a href=\"#\" data-headword=\"אַפְרוֹדִיטֵי\">אַפְרוֹרִיטֵי</a>; a. fr.—Pl. <span dir=\"rtl\">מֶרְחֲצָאוֹת</span>. <span class=\"citation\">Ib. 2ᵇ</span>; <span class=\"citation\">Sabb. 33ᵇ</span>. <span class=\"citation\">Cant. R. to I, 6</span> <span dir=\"rtl\">במעט מרחץ מן המֶרְחֲצָיוֹת</span> with a slight bath in one of the bath-houses. <span class=\"citation\">Arakh. 32ᵃ</span> <span dir=\"rtl\">בתי מ׳</span>; Sifra B’har, ch. V, Par. 4; <span class=\"citation\">Y. Maasr. III, end, 51ᵃ</span> <span dir=\"rtl\">מרחציות</span>; a. fr.</div>","alt":[]},"16612":{"h":"מֶרְחָק","r":"M02636","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>distance</i>. <span class=\"citation\">Yalk. Prov. 964</span> <span dir=\"rtl\">שבאת ממ׳</span> for she (Sarah) came from a distant land; a. e.</div>","alt":[]},"16613":{"h":"מְרָחַק","r":"M02637","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַק\">רְחַק</a>) <i>abominable, unclean</i>. <span class=\"citation\">Targ. Job XV, 16</span> (h. text <span dir=\"rtl\">נתעב</span>). <span class=\"citation\">Targ. O. Lev. VII, 18</span> (h. text <span dir=\"rtl\">פגול</span>). <span class=\"citation\">Targ. O. Deut. VII, 26</span> <span dir=\"rtl\">דמ׳</span> that which is abominable (cmp. <a href=\"#\" data-headword=\"דִּמְחַמְרָא\">דִּמְחַמְרָא</a>). <span class=\"citation\">Targ. Lev. XX, 21</span> (ed. Berl. <span dir=\"rtl\">מְרָחַקָא</span>; h. text <span dir=\"rtl\">נדה</span>); a. fr.—Pl. <span dir=\"rtl\">מְרַחֲקִין</span>. <span class=\"citation\">Targ. Y. Deut. XXIV, 4</span>.</div>","alt":["מְרַחֲקָא"]},"16614":{"h":"מְרַחֲקָא","r":"M02638","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרָחַק\">preced.</a>) <i>abomination</i>. <span class=\"citation\">Targ. Deut. XXIV, 4</span>. <span class=\"citation\">Targ. Prov. XIII, 19</span>; a. fr.</div>","alt":["מְרָ׳","מְרַחַקְתָּא"]},"16615":{"h":"מַרְחֶשְׁוָון","r":"M02639","html":"<div class=\"sense\"> (Assyr. <i>Araaḥ samna</i>, Schr. KAT<sup>2</sup>, 380) <i>Marḥeshvan</i>, the eighth month of the Jewish calendar, containing twenty nine or thirty days, varying between the fifth of October and the second of December. <span class=\"citation\">Targ. Y. Deut. XI, 14</span>. Targ. II Esth. III, 7.—<span class=\"citation\">R. Hash. 11ᵇ</span></div>","alt":["מַרְחֶשְׁוָן"]},"16616":{"h":"מַרְחֶשֶׁת I","r":"M02640","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"רָחַשׁ\">רָחַשׁ</a>) <i>deep and covered pan</i>. <span class=\"citation\">Men. V, 8</span>; Sifra Vayikra, N’dab., Par. 10, ch. XII; a. e.; v. <a href=\"#\" data-headword=\"מַחֲבַת\">מַחֲבַת</a>.</div>","alt":[]},"16617":{"h":"מַרְחֶשֶׁת II","r":"M02641","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Marḥesheth</i> (v. Hildesh. Beitr., p. 31). <span class=\"citation\">Y. Shebi. VI, 36ᶜ</span>; <span class=\"citation\">Tosef. Shebi. IV, 11</span> <span dir=\"rtl\">מחר׳</span> ed. Zuck. (Var. <span dir=\"rtl\">מרח׳</span>); <span class=\"citation\">Sifré Deut. 51</span> <a href=\"#\" data-headword=\"מַרְעֶשֶׁת\">מַרְעֶשֶׁת</a>; <span class=\"citation\">Yalk. ib. 874</span> <a href=\"#\" data-headword=\"מַרְעֶשֶׁת\">מַרְעַשְׁתָּא</a>.</div>","alt":[]},"16618":{"h":"מָרַט","r":"M02642","html":"<div class=\"sense\"> (b. h.) <i>to pluck off</i> (hair, wool &amp;c.); <i>to pull</i>. <span class=\"citation\">Tosef. Sabb. IX</span> (<span class=\"citation\">X), 20</span>; <span class=\"citation\">Sabb. 74ᵇ</span> <span dir=\"rtl\">והמוֹרְטוֹ</span> and he who plucks the down off the large feather of the wing. <span class=\"citation\">B. Mets. 68ᵇ</span> <span dir=\"rtl\">גוזזות ושוטפות ומוֹרְטוֹת</span> (Ar. <span dir=\"rtl\">גזוזות</span>) they yield wool by being shorn, by passing through water, and by being plucked (in passing bushes &amp;c.; [prob. to be read <span dir=\"rtl\">גזוזות ושטופות ומְרוּטוֹת</span>].</div><div class=\"sense\"><b>Pi. מֵירֵט</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מַרְחֶשֶׁת II\">same</a>. <span class=\"citation\">Naz. 39ᵇ</span> <span dir=\"rtl\">תלש מ׳ סיפסף וכ׳</span> if he pinced his hair (near the root), plucked it off, or trimmed it &amp;c.; (Ar. s. v. <a href=\"#\" data-headword=\"סִפְסֵף\">ספסף</a>: ‘created a bald spot by using a depilatory’). Sabb. l. c. <span dir=\"rtl\">מְמָרֵט חייב משום ממחק</span> he who plucks the down (v. supra) is guilty of an act coming under the head of scraping (leather).—<i>Part. pass</i>. <span dir=\"rtl\">מְמוֹרָט</span> <i>bald-headed</i>. <span class=\"citation\">Naz. 46ᵇ</span>; <span class=\"citation\">Yoma 61ᵇ</span> <span dir=\"rtl\">נזיר ממ׳</span>; <span class=\"citation\">Tosef. Naz. I, 6</span> <span dir=\"rtl\">המוֹרָט</span>; Y. ib. VI, end, 55ᵈ <span dir=\"rtl\">נזיר ומירט</span> (read: <span dir=\"rtl\">נזיר ממ׳</span> or <a href=\"#\" data-headword=\"מוֹרָט\">מורט</a>).</div><div class=\"sense\"><b>—2)</b> <i>to smooth, polish</i>. <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">נחשת ממורט</span> (prob. to be read: <span dir=\"rtl\">מְמוֹרֶטֶת</span>) polished bronze.</div></div><div class=\"sense\"><b>Nif. נִמְרַט</b> <div class=\"sense\"><i>to be plucked, to be bald</i>. Sifra Thazr., Par. 5, ch. X <span dir=\"rtl\">נ׳ ראשו וכ׳</span> if his head became bald through sickness.</div></div>","alt":[]},"16619":{"h":"מְרַט I","r":"M02643","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Lev. XXI, 5</span>. <span class=\"citation\">Targ. Jer. XVI, 6</span>; a. e.—Part. <a href=\"#\" data-headword=\"מְרַט I\">מָרֵיט</a>, pl. <span dir=\"rtl\">מָרְטִין</span>. <span class=\"citation\">Targ. Is. L, 6</span> ed. Lag. (oth. ed. <span dir=\"rtl\">מָרְטָן</span>; ed. Wil. <span dir=\"rtl\">מוֹרְטִין</span>).</div><div class=\"sense\"><b>Ithpe. אִתְמְרֵיט</b> <div class=\"sense\"><i>to be laid bare, to have the shoulder uncovered</i> (in mourning), v. <a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a>. <span class=\"citation\">Targ. Ez. XXIX, 18</span> (ed. Wil. <span dir=\"rtl\">אִתְמְרט</span>; h. text <a href=\"#\" data-headword=\"מְרוּטָה\">מְרוּטָה</a>; Pesh. <span dir=\"rtl\">חליץ</span>).</div></div><div class=\"sense\"><b>Pa. מָרֵיט</b> <div class=\"sense\">, v. infra.</div></div><div class=\"sense\"><b>Palp. מַרְטֵיט</b> <div class=\"sense\"><i>to pull to pieces, to divide, plunder</i>. <span class=\"citation\">Targ. Job XVI, 11</span> <span dir=\"rtl\">מְמַרְטֵט</span> ed. Lag. (Ms. <a href=\"#\" data-headword=\"מְרַט I\">מרטיט</a>, Var. <span dir=\"rtl\">מְמָרֵט</span> <i>Pa.;</i> h. text <span dir=\"rtl\">ירטני</span>). <span class=\"citation\">Targ. Ps. XXXIX, 3</span> <span dir=\"rtl\">כיבי ממרטיט</span> he lacerates my wound (h. text <a href=\"#\" data-headword=\"עָכַר\">נעכר</a>).—<span class=\"citation\">Ḥull. 92ᵇ</span> <span dir=\"rtl\">ממרטט ליה</span> he pulled the fatty fibres out (going to the root). </div></div><div class=\"sense\"><b>Ithpalp. אִיתְמַרְטֵט  אִימַּ׳</b> <div class=\"sense\"><i>to be torn to pieces, dismembered</i>. <span class=\"citation\">Ab. Zar. 69ᵃ</span> <span dir=\"rtl\">אִימַּרְטוּטֵי אִימַּ׳</span> (the mouse in the liquid) was dismembered. <span class=\"citation\">Nidd. 56ᵇ</span> <span dir=\"rtl\">אִמַּרְטוּטֵי אימרטיט</span> it would have been dismembered.—[<span class=\"citation\">Koh. R. to X, 16</span> <span dir=\"rtl\">איתמרטת</span>, read: <span dir=\"rtl\">איתמרעת</span>, v. <a href=\"#\" data-headword=\"מְרַע I\"><span dir=\"rtl\">מְרַע</span> I</a>.]</div></div>","alt":[]},"16620":{"h":"מְרַט II","r":"M02644","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרַט I\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>baldness</i>. <span class=\"citation\">Targ. O. Deut. XIV, 1</span>. <span class=\"citation\">Targ. Is. XV, 2</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>plucked wool, tuft</i>. <span class=\"citation\">Sabb. 49ᵃ</span> <span dir=\"rtl\">ממ׳ דביני אטמי</span> of wool plucked from between the flanks (of a living animal, which contains moisture).</div>","alt":["מְרָטָא"]},"16621":{"h":"מַרְטוּט","r":"M02645","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרַט II\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>tuft of plucked wool</i>, &amp;c.; <i>lint</i>. <span class=\"citation\">Y. Kil. IX, end, 32ᵈ</span> <span dir=\"rtl\">סיפלני דמ׳ עמר</span> a compress of wool lint; <span dir=\"rtl\">דמ׳ דכיתן</span> of linen lint. <span class=\"citation\">Y. Sabb. IV, end, 7ᵃ</span> <span dir=\"rtl\">אילו מאן דנסב מ׳ וכ׳</span> if one takes a tuft of wool and puts it on his head in cold weather. <span class=\"citation\">Y. Yoma VIII, 44ᵈ</span> top; <span class=\"citation\">Y. Taan. I, 64ᶜ</span> <span dir=\"rtl\">תרי מ׳</span> soaked a tuft.</div><div class=\"sense\"><b>—2)</b> <i>a garment made of</i> (<i>plucked</i>) <i>wool</i> (v. P. Sm. 2224; Arab. <i>mirṭ</i> species indumenti ex lana &amp;c.), <i>a coarse garment</i>. <span class=\"citation\">Targ. Prov. XXV, 20</span>. <span class=\"citation\">Ib. XXVII, 13</span>.—Pl. <span dir=\"rtl\">מַרְטוּטִין</span>. <span class=\"citation\">Y. Maas. Sh. I, 52ᵈ</span> bot. <span dir=\"rtl\">עד כדון … תליין ביה מַרְטוּטֵיכוֹן</span> (not … <span dir=\"rtl\">טכין</span>) R. S. is still alive, and you hang your garments on him, i.e. you refer to him as your authority!</div>","alt":["מַרְטוּטָא","מַרְטוּטָה"]},"16622":{"h":"מרטוסא","r":"M02646","html":"<div class=\"sense\">, read: <span dir=\"rtl\">מַרְסִיסָה</span> m. (<a href=\"#\" data-headword=\"רְסַס\">רְסַס</a>; cmp. <a href=\"#\" data-headword=\"הַרְסָנָא\">הַרְסְנָא</a>) <i>hash of small fish</i> or <i>locusts preserved in salt</i>. <span class=\"citation\">Y. Ab. Zar. II, 42ᵃ</span> top (v. <a href=\"#\" data-headword=\"חוורנס\">חוורנס</a>).</div>","alt":["מרטיסה"]},"16623":{"h":"מרטיוטאי","r":"M02647","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְיוֹטָאֵי\">מַרְיוֹטָאֵי</a></div>","alt":[]},"16624":{"h":"מרטנאי","r":"M02648","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוּרְטַנְיָא\">מוּרְטַנְיָא</a></div>","alt":["מַרְטַנְיָא"]},"16625":{"h":"מַרְטְקָא","r":"M02649","html":"<div class=\"sense\">, m.</div><div class=\"sense\"><b>1)</b>  (transp. of <a href=\"#\" data-headword=\"מַטְרְקָא\">מַטְרְקָא</a>, q. v.) <i>whip</i>. <span class=\"citation\">Yoma 77ᵃ</span></div><div class=\"sense\"><b>—2)</b> <i>withered flesh</i>, v. <a href=\"#\" data-headword=\"מוּרְדְּקָא\">מוּרְדְּקָא</a>.</div>","alt":[]},"16626":{"h":"מָרֵי","r":"M02650","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָר\">מָר</a></div>","alt":[]},"16627":{"h":"מרי I","r":"M02651","html":"<div class=\"sense\"> (b. h.) <i>to be strong, fat</i>.</div><div class=\"sense\"><b>Hif. הִמְרִיא</b> <div class=\"sense\"><i>to fatten, stuff</i>. <span class=\"citation\">Sabb. XXIV, 3</span> (<span class=\"citation\">155ᵇ</span>) <span dir=\"rtl\">אין מַמְרִים וכ׳</span> (Y. ed. <span dir=\"rtl\">מַמְרִין</span>; Bab. ed. <span dir=\"rtl\">מאמירין</span>, v. <a href=\"#\" data-headword=\"אָמַר II\"><span dir=\"rtl\">אָמַר</span> II</a>) you must not stuff calves (on the Sabbath), v. <a href=\"#\" data-headword=\"הַמְרָאָה I\"><span dir=\"rtl\">הַמְרָאָה</span> I</a>.</div></div>","alt":["מָרָא"]},"16628":{"h":"מרי II","r":"M02652","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"מרי I\">preced.</a>; cmp. <a href=\"#\" data-headword=\"מָר\">מָר</a>, <i>to rebel against</i>. Part. <a href=\"#\" data-headword=\"מוֹרֶה I\">מוֹרֶה</a>.—<span dir=\"rtl\">סורר ומ׳</span> (<a href=\"#\" data-headword=\"בֵּן\">בן</a>) <i>the rebellious son</i>, amenable to the law (<span class=\"citation\">Deut. XXI, 18–21</span>). <span class=\"citation\">Snh. VIII, 1</span> <span dir=\"rtl\">מאימתי נעשה בן ס׳ ומ׳</span> when is one to be dealt with as a <i>sorer umoreh?</i> <span class=\"citation\">Ib. 68ᵇ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"מוֹרִיר\">מוֹרִים</a>, <span dir=\"rtl\">מוֹרִין</span>, v. <a href=\"#\" data-headword=\"מוֹרֶה II\"><span dir=\"rtl\">מוֹרֶה</span> II</a>, a. <a href=\"#\" data-headword=\"מוֹרוֹס\">מוֹרוֹס</a>.</div><div class=\"sense\"><b>Hif. הִמְרָה</b> <div class=\"sense\"><b>1)</b> <i>to make strong, energetic</i>. <span class=\"citation\">Gen. R. s. 42</span>, end (play on <a href=\"#\" data-headword=\"מַמְרֵא I\">מַמְרֵא</a>) <span dir=\"rtl\">שה׳ פנים וכ׳</span> he showed a stern countenance against Abraham (rebuking him).</div><div class=\"sense\"><b>—2)</b> <i>to provoke, to rebel</i>. Y. Kidd. IV, beg. 65ᵇ (play on <a href=\"#\" data-headword=\"אָמַר I\">אמר</a>, <span class=\"citation\">Neh. VII, 61</span>) <span dir=\"rtl\">שהִימְרוּ לאל וכ׳</span> they provoked God with their evil doings. <span class=\"citation\">Ex. R. s. 1</span>, end <span dir=\"rtl\">שעתידים להַמְרוֹת וכ׳</span> that they will rebel at the Red Sea; a. fr.—Esp. <i>to disregard the authority of the Supreme Court</i> (v. <a href=\"#\" data-headword=\"מַמְרֵא II\"><span dir=\"rtl\">מַמְרֵא</span> II</a>). <span class=\"citation\">Snh. 14ᵇ</span>; <span class=\"citation\">Sot. 45ᵃ</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to incite one against the other, to arrange a race; to bet</i>. <span class=\"citation\">Snh. 25ᵇ</span> (expl. <span dir=\"rtl\">מפריחי יונים</span>) <span dir=\"rtl\">שמַמְרִין וכ׳</span> those who race doves (and bet on them). <span class=\"citation\">Sabb. 31ᵃ</span> top <span dir=\"rtl\">שהִמְרוּ זה את זה</span> who entered a wager.</div></div>","alt":["מָרָה"]},"16629":{"h":"מְרֵי","r":"M02653","html":"<div class=\"sense\">; <i>Af</i>. <a href=\"#\" data-headword=\"אַמְרִי\">אַמְרֵי</a> <i>to provoke</i>. [<span class=\"citation\">Targ. Zech. XII, 10</span>, v. <a href=\"#\" data-headword=\"מְרַר\">מְרר</a>].—<span class=\"citation\">Sot. 35ᵇ</span> top <span dir=\"rtl\">מאן אַמְרִיךְ דאִימַּרְיַית</span> (Ar. ed. Koh. s. v. <a href=\"#\" data-headword=\"אָמַר I\">אמר</a>: <span dir=\"rtl\">אימרייך דאימרת</span>, corr. acc.) who provoked thee that thou didst get angry?; <span class=\"citation\">Num. R. s. 5</span>, end.—<span class=\"citation\">Gen. R. s. 42</span> (play on <span dir=\"rtl\">א̇מ̇ר̇פל̇</span>) <span dir=\"rtl\">דא̇מ̇ר̇י וא̇פ̇ל̇י וכ׳</span></div><div class=\"sense\"><b>Ithpe. אִימְּרֵי  אִמְּ׳</b> <div class=\"sense\"><b>1)</b> <i>to get angry</i>. Num. R. l. c. <span dir=\"rtl\">דאִמַּרְיַת</span>; Sot. l. c., v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to quarrel, rebel</i>. <span class=\"citation\">B. Mets. 84ᵇ</span> אִימַּרְיָא Ms. M., v. <a href=\"#\" data-headword=\"מְרַד\">מְרַד</a>.—<span class=\"citation\">Ḥull. 58ᵇ</span> אִימְּרָאִי … לבקא Ar., v. <a href=\"#\" data-headword=\"בַּקָּא\">בַּקָּא</a> (ed. <span dir=\"rtl\">אִימְּרָא … מב׳</span> she ran away in anger from &amp;c., v. <a href=\"#\" data-headword=\"מְרַד\">מְרַד</a>). <span class=\"citation\">Keth. 63ᵇ</span> <a href=\"#\" data-headword=\"אִימַר\">אימראי</a> quot. in Rashi to <span class=\"citation\">Job XXXIX, 18</span> (ed. <span dir=\"rtl\">אימרדה</span>).</div><div class=\"sense\"><b>—3)</b> <i>to refuse to abide by a bargain</i>; <i>to retract</i>. <span class=\"citation\">B. Mets. 77ᵃ</span> <span dir=\"rtl\">אייקרא … ואִימְּרוּ פועלים</span> labor became dearer, and the laborers struck. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ואימרי בעה&quot;ב</span> Ar. (ed. <span dir=\"rtl\">ואימר</span>, fr. <a href=\"#\" data-headword=\"יָמַר\">ימר</a>, v. <a href=\"#\" data-headword=\"מוּר I\"><span dir=\"rtl\">מוּר</span> I</a></div></div>","alt":["מְרָא"]},"16630":{"h":"מָרִי","r":"M02654","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Mari</i>, name of several persons. <span class=\"citation\">Sabb. 154ᵃ</span> (v. marginal note); <span class=\"citation\">B. Mets. 110ᵃ</span> <span dir=\"rtl\">מ׳ ברה דבת שמואל</span>; <span class=\"citation\">B. Bath. 149ᵃ</span> <span dir=\"rtl\">(<span dir=\"rtl\">דאיסור גיורא</span>) <span dir=\"rtl\">מ׳ בריה</span></span>.—<span class=\"citation\">Y. Ber. VI, 10ᵇ</span> top <span dir=\"rtl\">רב יצחק בר מ׳</span> (Bab. <span class=\"citation\">ib. 51ᵃ</span> top <span dir=\"rtl\">יצחק קסקסאה</span>); cmp. <a href=\"#\" data-headword=\"מָרְיוֹן\">מָרְיוֹן</a>.—<span class=\"citation\">B. Mets. 39ᵇ</span>, v. <a href=\"#\" data-headword=\"אִיסָק\">אִיסָק</a>.—<span class=\"citation\">Bets. 28ᵇ</span> <span dir=\"rtl\">מ׳ בריה דרב בינזא</span>; a. several others.</div>","alt":["מָארִי"]},"16631":{"h":"מַרְיָא","r":"M02655","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְיָיא\">מרְיָיא</a></div>","alt":[]},"16632":{"h":"*מְרִיבָג","r":"M02656","html":"<div class=\"sense\"> name of a <i>jewel</i> in the high priest’s breastplate. <span class=\"citation\">Targ. Cant. V, 14</span> (corresp. to <span dir=\"rtl\">שהם</span>, <span class=\"citation\">Ex. XXVIII, 20</span>).</div>","alt":[]},"16633":{"h":"מְרִיבָה","r":"M02657","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>strife</i>. <span class=\"citation\">Num. R. s. 3</span> <span dir=\"rtl\">המטילים מ׳ וכ׳</span> those who caused strife between him and her. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אף הם היו בעלי מ׳</span> they, too, were men of strife. <span class=\"citation\">Pesik. R. s. 20</span> <span dir=\"rtl\">מימיכם אנשי מ׳ אתם</span> you have at all times been in the opposition. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אתם עומדים במדינה</span> (corr. acc.) you are of the opposition. <span class=\"citation\">Midr. Till. to Ps. CIII</span> עשיתי מ׳ I entered a contest. <span class=\"citation\">B. Mets. 59ᵃ</span>; a. fr.</div>","alt":[]},"16634":{"h":"מְרִיגַז","r":"M02658","html":"<div class=\"sense\"> a word in an incantation. <span class=\"citation\">Sabb. 67ᵃ</span>, v. <a href=\"#\" data-headword=\"מוֹרִיגַן\">מוֹרִיגַן</a></div>","alt":[]},"16635":{"h":"מְרֵיד","r":"M02659","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרַד\">מְרַד</a></div>","alt":[]},"16636":{"h":"מְרִידָא","r":"M02660","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרֵיד\">preced.</a>) <i>rebellious</i>. <span class=\"citation\">Targ. Prov. XVII, 11</span> <span dir=\"rtl\">גברא מ׳</span> ed. Will. (ed. Lag. <span dir=\"rtl\">מרירא</span>; h. text <a href=\"#\" data-headword=\"מרי I\">מרי</a>).</div>","alt":[]},"16637":{"h":"מְרִידָה","r":"M02661","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָרַד I\">מָרַד</a>) <i>rebellion</i>. Nom. R. s. 18, beg.; Tanḥ. Kor. 1., a. e.</div>","alt":[]},"16638":{"h":"מרידתא","r":"M02662","html":"<div class=\"sense\">, <span class=\"citation\">Ḥull. 59ᵃ</span> top, v. <a href=\"#\" data-headword=\"מְרָרִיתָא\">מְרָרִיתָא</a>, a. <a href=\"#\" data-headword=\"נוּרִיתָא\">נוּרִיתָא</a>.</div>","alt":[]},"16639":{"h":"מַרְיָה","r":"M02663","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְיָיא\">מַרְיָיה</a></div>","alt":[]},"16640":{"h":"מַרְיוֹטָאֵי","r":"M02664","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (Μαρεώτης) <i>the people of Mareotis</i>, a district of Lower Egypt with the town of Marea. <span class=\"citation\">Targ. Y. Gen. X, 13</span> (some ed. <span dir=\"rtl\">מַרְטִיֹּוטָ׳</span>); <span class=\"citation\">Targ. I Chr. I, 11</span> ed. Rahmer (ed. Lag. <a href=\"#\" data-headword=\"מראטאי\">מראטאי</a>, read <span dir=\"rtl\">יו</span> for <a href=\"#\" data-headword=\"א\">א</a>; h. text <span dir=\"rtl\">ענמים</span>).</div>","alt":[]},"16641":{"h":"מריולא","r":"M02665","html":"<div class=\"sense\">, <span class=\"citation\">Pes. 39ᵃ</span> Mus., v. <a href=\"#\" data-headword=\"*יְרוֹאָר\">יְרוֹאָר</a></div>","alt":[]},"16642":{"h":"מָרְיוֹן","r":"M02666","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Μαρίων) <i>Marion</i>, name of several persons. <span class=\"citation\">Y. Succ. II, 53ᵃ</span> <span dir=\"rtl\">יצחק בר מ׳</span> (cmp. <a href=\"#\" data-headword=\"מָרִי\">מָרִי</a>); <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">מור׳</span>; <span class=\"citation\">Yalk. Hos. 518</span>; a. e.—<span class=\"citation\">M. Kat. 11ᵇ</span> <span dir=\"rtl\">מ׳ בריה דרבין</span>.—<span class=\"citation\">B. Bath. 12ᵇ</span> <span dir=\"rtl\">כי נכסי דבי בר מ׳</span> (Ms. M. <span dir=\"rtl\">מור׳</span>; v. Rabb. D. S. a. l. note 10) as (improved as) the estate of the house of Bar M.—<span class=\"citation\">B. Mets. 84ᵇ</span> בני בר מ׳ Ms. M. (ed. <span dir=\"rtl\">בני בירי</span>).—<span class=\"citation\">Yalk. Ruth 601</span>, v. <a href=\"#\" data-headword=\"מֵרוֹם\">מֵרוֹם</a>.</div>","alt":[]},"16643":{"h":"מֶרְיוֹן","r":"M02667","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מרי II\">מָרָה</a>) <i>rebel</i>.—Pl. <span dir=\"rtl\">מֶרְיוֹנִים</span>. Pesik. Ekhah, p. 122ᵇ, v. <a href=\"#\" data-headword=\"*אטקטיא\">אטקטיא</a> (v., however, <a href=\"#\" data-headword=\"אַרְכִי III\"><span dir=\"rtl\">אַרְכִי</span> III</a>).</div>","alt":[]},"16644":{"h":"מָרִיחַ","r":"M02668","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרַח II\"><span dir=\"rtl\">מְרַח</span> II</a></div>","alt":[]},"16645":{"h":"מְרִיחָא","r":"M02669","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָרִיחַ\">preced.</a>) <i>a haughty man</i>. <span class=\"citation\">Targ. Prov. XXI, 24</span> (h. text <a href=\"#\" data-headword=\"יָהִיר\">יהיר</a>).</div>","alt":[]},"16646":{"h":"מַרְיָיא","r":"M02670","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Marya</i> (cmp. <a href=\"#\" data-headword=\"מָרִי\">מָרִי</a>). <span class=\"citation\">Y. Pes. V, 32ᶜ</span> bot.; <span class=\"citation\">Y. Peah I, 15ᶜ</span> top <a href=\"#\" data-headword=\"מַרְיָא\">מריא</a>; <span class=\"citation\">Y. Ter. XI, beg., 47ᶜ</span> <a href=\"#\" data-headword=\"מַרְיָה\">מריה</a>; <span class=\"citation\">Y. Ab. Zar. II, 41ᶜ</span> top <a href=\"#\" data-headword=\"מָדַיי\">מדייא</a> (corr. acc.); <span class=\"citation\">Y. Bicc. II, 64ᵈ</span> <a href=\"#\" data-headword=\"מַרְיָא\">מריא</a>; <span class=\"citation\">Y. Erub. VII, beg. 24ᵇ</span> <span dir=\"rtl\">כד מ׳</span> (corr. acc.).</div>","alt":["מַרְיָיה"]},"16647":{"h":"מִרְיָם","r":"M02671","html":"<div class=\"sense\"> (b. h.) pr. n. f. <i>Miriam</i>, </div><div class=\"sense\"><b>1)</b>  sister of Moses. <span class=\"citation\">Sot. I, 9</span> (<span class=\"citation\">9ᵇ</span>).). <span class=\"citation\">Ex. R. s. 1</span>; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  name of several persons. <span class=\"citation\">Lam. R. to I, 16</span>, v. <a href=\"#\" data-headword=\"בַּיְתוֹס\">בַּיְתוֹס</a>.—Ib.; <span class=\"citation\">Pesik. R. s. 29-30</span>-30 (ed. Fr. p. 140ᵃ) M., daughter of Naḳdimon.—Lam. R. l. c. M., daughter of Naḥtom; <span class=\"citation\">Yalk. Deut. 938</span> (of Tanḥum).—M. the hair-dresser; M. the children’s nurse, v. <a href=\"#\" data-headword=\"גְּדַל I\"><span dir=\"rtl\">גְּדַל</span> I</a>, II.—M. a member of the priestly family of Bilgah. <span class=\"citation\">Tosef. Succ. IV, 28</span>; <span class=\"citation\">Succ. 56ᵇ</span>; Y. ib. V, end, 55ᵈ; a. others.</div><div class=\"sense\"><b>—3)</b> <i>Imma Miriam</i>. <span class=\"citation\">Keth. 87ᵃ</span>; <span class=\"citation\">88ᵇ</span>.—[<span class=\"citation\">Ruth R. to II, 5</span>, v. <a href=\"#\" data-headword=\"מֵרוֹם\">מֵרוֹם</a>.]</div>","alt":[]},"16648":{"h":"מרימות","r":"M02672","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to I, 6</span>, read: <span dir=\"rtl\">מרכבות</span>, v. <a href=\"#\" data-headword=\"מֶרְכָּבָה\">מֶרְכָּבָה</a></div>","alt":[]},"16649":{"h":"מְרֵימַר","r":"M02673","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>M’remar</i>, name of several Amoraim. <span class=\"citation\">Ḥull. 62ᵇ</span>. <span class=\"citation\">B. Bath. 3ᵇ</span>. <span class=\"citation\">Ab. Zar. 33ᵇ</span> <span dir=\"rtl\">בעו מיניה ממ׳</span> (<span class=\"citation\">Pes. 30ᵇ</span> <span dir=\"rtl\">מאמימר</span>). Ib. <span dir=\"rtl\">דריש מ׳</span>; a. fr.</div>","alt":[]},"16650":{"h":"מָרִינוֹס","r":"M02674","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Μαρῖνος) <i>Marinus</i>, name of several persons. <span class=\"citation\">Tosef. Toh. VII, 7</span>.—<span class=\"citation\">B. Bath. 56ᵃ</span>.—<span class=\"citation\">Lam. R. to II, 22</span>. <span class=\"citation\">Y. Gitt. IV, 46ᵃ</span></div>","alt":[]},"16651":{"h":"מְרִיעַ","r":"M02675","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מְרַע I\">מְרַע</a>) <i>weak, ailing</i>. <span class=\"citation\">Targ. Mal. I, 8</span> <span dir=\"rtl\">דמ׳</span> (ed. Lag. <span dir=\"rtl\">דמרע</span>) that which is sick; <span class=\"citation\">ib. 13</span>.—Pl. <span dir=\"rtl\">מְרִיעִין</span>, <span dir=\"rtl\">מְרִיעַיָּא</span>, <span dir=\"rtl\">מְרִיעֵי</span>. <span class=\"citation\">Targ. Y. Ex. XVIII, 20</span>. <span class=\"citation\">Targ. Ez. XXXIV, 4</span> (ed. Lag. <span dir=\"rtl\">מְרָעַיָּא</span>).—<span class=\"citation\">R. Hash. 16ᵃ</span> <span dir=\"rtl\">מצלינן … אקצירי ואמ׳</span> we pray now for the sick and the ailing; <span class=\"citation\">Ned. 49ᵇ</span> <span dir=\"rtl\">קצירי קצירי ממש מ׳ רבנן</span> by <i>ḳ’tsire</i> we mean the really sick, by <i>m’riʿé</i> we mean the scholars (in delicate health).</div>","alt":[]},"16652":{"h":"מְרֵיעוּת","r":"M02676","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"רֵעַ\">רֵעַ</a>) <i>friendship, sociability, social gathering</i>. <span class=\"citation\">M. Kat. 22ᵇ</span>.—[<span class=\"citation\">Tosef. Shebi. II, 4</span>, v. <a href=\"#\" data-headword=\"מוּרְבִּית II\"><span dir=\"rtl\">מוּרְבִּית</span> II</a>.]</div>","alt":[]},"16653":{"h":"מְרִיצָה I","r":"M02677","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָצַץ\">רָצַץ</a>) <i>a tool for crushing</i> bones, stones &amp;c. <span class=\"citation\">Shek. VIII, 2</span> חוץ מן … והמ׳ והמיוחדין וכ׳ Ms. M. (ed. <span dir=\"rtl\">המיוחדין</span>, v. Rabb. D. S. a. l. note; Ms. M. <span dir=\"rtl\">והמרחצ׳</span>; Y. ed. omits our w.) except the basket (for gathering disinterred bones for burial), the shovel, and the crusher, and things specially designated for burial purposes. Y. ib. 51ᵃ bot. <span dir=\"rtl\">מ&quot;ד מ׳ שמריצה את האבן</span> (v. Rabb. D. S. to Bab. ed., p. 68ᵃ; Bab. ed. add <span dir=\"rtl\">לבית הקברות</span>) he who calls the tool <i>m’ritsah</i> (instead of <a href=\"#\" data-headword=\"צִפּוֹרֶן\">צפורן</a>) does so, because it makes the stones run (fr. <a href=\"#\" data-headword=\"רוּץ\">רוּץ</a>), i.e. makes them portable.</div>","alt":[]},"16654":{"h":"מְרִיצָה II","r":"M02678","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מרוּצָה I\"><span dir=\"rtl\">מְרוּצָה</span> I</a></div>","alt":[]},"16655":{"h":"מְרִיק","r":"M02679","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרַק\">מְרַק</a></div>","alt":[]},"16656":{"h":"מָרֵיקָא","r":"M02680","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָרֵקָה\">מָרֵקָה</a></div>","alt":["מָרֵיקָה"]},"16657":{"h":"מְרִיקָה","r":"M02681","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָרַק\">מָרַק</a>) <i>scouring, washing</i>. Sifra Tsav, Par. 3, ch. VII <span dir=\"rtl\">מ׳ כמְרִיקַת הכוס</span> the <i>m’riḳah</i> (<span class=\"citation\">Lev. VI, 21</span>) means like washing a cup, contrad. to <a href=\"#\" data-headword=\"שְׁטִיפָה\">שטיפה</a> (rinsing); <span class=\"citation\">Zeb. XI, 7</span>. <span class=\"citation\">Tosef. ib. X, 14</span> <span dir=\"rtl\">מְרִיקָתָן</span> their being washed; a. fr.</div>","alt":[]},"16658":{"h":"מָרִיר I","r":"M02682","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרַר\">מְרַר</a>) <i>bitter</i>; <i>embittered, grieving</i>. <span class=\"citation\">Targ. I Sam. XXII, 2</span>. <span class=\"citation\">Targ. O. Gen. XXVII, 34</span> <span dir=\"rtl\">מָ׳</span> ed. Berl. (ed. <a href=\"#\" data-headword=\"מָנִיכָא\">מְ׳</a>); Y. <a href=\"#\" data-headword=\"מְרִירְתָּא\">מְרִירְתָּא</a>. Targ. II Esth. IV, 1; a. fr.—[<span class=\"citation\">Targ. Prov. XVII, 11</span> <span dir=\"rtl\">גברא מ׳</span> (ed. Wil. <a href=\"#\" data-headword=\"מְרִידָא\">מְרִידָא</a>; h. text <a href=\"#\" data-headword=\"מרי I\">מרי</a>).]—<span class=\"citation\">Ber. 56ᵃ</span> <span dir=\"rtl\">מ׳ עסקך כי חסא</span> thy business will be bitter (thy goods disliked) like lettuce (v. <a href=\"#\" data-headword=\"חָסָא I\"><span dir=\"rtl\">חָסָא</span> I</a>). <span class=\"citation\">Sabb. 127ᵇ</span> bot. <span class=\"citation\">B. Mets. 113ᵇ</span>; a. fr.—<span class=\"citation\">B. Bath. 20ᵃ</span> bot. <span dir=\"rtl\">במרירתא</span> bitter (salt) is meant.—Pl. <a href=\"#\" data-headword=\"מְרִירִי\">מְרִירִין</a>, <span dir=\"rtl\">מָרִירַיָּא</span>, <a href=\"#\" data-headword=\"מָנִיכָא\">מְ׳</a>; f. <a href=\"#\" data-headword=\"מָרִיר I\">מְרִירָן</a>. <span class=\"citation\">Targ. Ex. XV, 23</span>. <span class=\"citation\">Targ. Num. V, 18</span>, sq. <span class=\"citation\">Targ. I Kings II, 8</span> (ed. Lag. <span dir=\"rtl\">מרירא</span>, corr. acc.).—[<span class=\"citation\">Targ. Y. Num. V, 24</span> <a href=\"#\" data-headword=\"מְרִירַיְתָא\">מְרִירַיְתָא</a>, read: … <span dir=\"rtl\">רַיָּא</span>].—<span class=\"citation\">Lam. R. to III, 40</span>, v. <a href=\"#\" data-headword=\"בְּסִימָא\">בְּסִימָא</a>.</div>","alt":["מָרִירָא","מְרִירָא","מְרִירְתָּא"]},"16659":{"h":"מָרִיר II","r":"M02683","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָרִיר I\">preced.</a>) <i>bitterness, bitter disposition, grief</i>. <span class=\"citation\">Targ. I Sam. XV, 32</span> <span dir=\"rtl\">מְרִיר מותא</span> (Regia <a href=\"#\" data-headword=\"מָרוֹר\">מְרוֹר</a>) the bitterness of death. <span class=\"citation\">Targ. Ez. III, 14</span>. <span class=\"citation\">Targ. Is. XXXVIII, 17</span>; a. fr.—V. <a href=\"#\" data-headword=\"מְרִירְתָּא\">מְרִירְתָּא</a>.</div>","alt":["מְרִירָא"]},"16660":{"h":"מְרִירָה","r":"M02684","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מָרִיר II\">preced.</a> wds.) [b. h. <i>bile</i>,] <i>bitterness</i>, trnsf. </div><div class=\"sense\"><b>1)</b> <i>sin</i>. <span class=\"citation\">Ex. R. s. 43</span> (ref. to <span dir=\"rtl\">ויחל</span>, <span class=\"citation\">Ex. XXXII, 11</span>) <span dir=\"rtl\">חַלֵּי מְרִירָתָן וכ׳</span> sweeten thou the bitterness of Israel (pardon their sins) and heal them.—Pl. <a href=\"#\" data-headword=\"מרירות\">מְרִירוֹת</a>. Ib. <span dir=\"rtl\">מי שיחלה המ׳ שלנו</span> one to sweeten our bitternesses (to pray for us). <span class=\"citation\">Lev. R. s. 12</span> (ref. to <span class=\"citation\">Deut. XXXII, 32</span>) <span dir=\"rtl\">הללו שהביאו מ׳ וכ׳</span> it is they (the grapes) that brought sins &amp;c.— (v. <a href=\"#\" data-headword=\"מְרִירוּ\">next w.</a>; cmp. <a href=\"#\" data-headword=\"לַעֲנָה II\"><span dir=\"rtl\">לַעֲנָה</span> II</a>) <i>curse</i>. <span class=\"citation\">Midr. Till. to Ps. XC, 9</span> (expl. <a href=\"#\" data-headword=\"הֶגֶה\">הֶגֶה</a> ib.; cmp. <a href=\"#\" data-headword=\"הָגָה\">הָגָה</a> a. <a href=\"#\" data-headword=\"אָגָא\">אָגָא</a>) <span dir=\"rtl\">זו מ׳</span> that means ‘curse’.</div>","alt":[]},"16661":{"h":"מְרִירוּ","r":"M02685","html":"<div class=\"sense\"><b>1)</b> <i>bitterness</i>. <span class=\"citation\">Targ. Prov. XIV, 10</span>. <span class=\"citation\">Targ. Ps. LXXV, 9</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"מְרַרְתָּא\">מְרִרְתָּא</a>). <span class=\"citation\">Targ. Esth. IV, 1</span>.</div><div class=\"sense\"><b>—2)</b> <i>curse</i>. <span class=\"citation\">Targ. O. Num. V, 24</span>; <span class=\"citation\">27</span> (Ms. I, III <a href=\"#\" data-headword=\"מְרָר\">מְרָר</a>; ed. Berl. a. Y. <a href=\"#\" data-headword=\"לְוָט\">לְוָט</a>; h. text <a href=\"#\" data-headword=\"מִרְיָם\">מָרִים</a>); v. <a href=\"#\" data-headword=\"מְרִירָה\">preced.</a></div>","alt":["מְרִירוּתָא"]},"16662":{"h":"מַרְיְרוֹאָר","r":"M02686","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*יְרוֹאָר\">יְרוֹאָר</a></div>","alt":[]},"16663":{"h":"מרירות","r":"M02687","html":"<div class=\"sense\">, Tanḥ. M’tsora 1 <span dir=\"rtl\">המ׳ זו</span>, v. <a href=\"#\" data-headword=\"מַרְדּוּת I\"><span dir=\"rtl\">מַרְדּוּת</span> I</a></div>","alt":[]},"16664":{"h":"מְרִירוּתָא","r":"M02688","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרִירוּ\">מְרִירוּ</a></div>","alt":[]},"16665":{"h":"מְרִירִי","r":"M02689","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"מְרִירוּתָא\">preced.</a> arts.) [<i>poisonous</i>,] <span dir=\"rtl\">קֶטֶב מ׳</span> or <a href=\"#\" data-headword=\"מ׳\">מ׳</a> (Ḳeṭeb) <i>M’riri</i>, name of a demon. <span class=\"citation\">Num. R. s. 12</span>; <span class=\"citation\">Lam. R. to I, 3</span>; Tanḥ. Naso 23; <span class=\"citation\">Midr. Till. to Ps. XCI, 6</span>; <span class=\"citation\">Yalk. Ps. 842</span>. <span class=\"citation\">Pes. 111ᵇ</span>. <span class=\"citation\">Ber. 5ᵃ</span> (quot. fr. <span class=\"citation\">Deut. XXXII, 24</span>).</div>","alt":[]},"16666":{"h":"מְרִירַיְתָא","r":"M02690","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָרִיר I\"><span dir=\"rtl\">מָרִיר</span> I</a></div>","alt":[]},"16667":{"h":"מְרִירְתָּא","r":"M02691","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרַר\">מְרַר</a>) </div><div class=\"sense\"><b>1)</b> <i>bitter</i>, v. <a href=\"#\" data-headword=\"מָרִיר I\"><span dir=\"rtl\">מָרִיר</span> I</a>. I.</div><div class=\"sense\"><b>—2)</b>  also <a href=\"#\" data-headword=\"מְרִירְתָּא\">מְרֵירְתָּא</a>, <a href=\"#\" data-headword=\"מְרַרְתָּא\">מְרַרְתָּא</a> = h. <a href=\"#\" data-headword=\"מרי II\">מָרָה</a>, <i>gall, bile</i>. <span class=\"citation\">Targ. Y. Ex. XXIII, 25</span> <span dir=\"rtl\">מחת מ׳</span> affection of the gall, v. <a href=\"#\" data-headword=\"מָרָה IV\"><span dir=\"rtl\">מָרָה</span> I</a>; a. e.—<span class=\"citation\">Keth. 50ᵃ</span> <span dir=\"rtl\">מרר׳ דדַיָּה וכ׳</span> the gall of a white <i>dayah</i> (v. <a href=\"#\" data-headword=\"דַּיָּה\">דַּיָּה</a>). <span class=\"citation\">Pes. 39ᵃ</span>, v. <a href=\"#\" data-headword=\"כּוּפְיָא\">כּוּפְיָא</a>. [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">במרור מרירתא</span>; <span dir=\"rtl\">אמררתא</span>, v. <a href=\"#\" data-headword=\"מְרָרִיתָא\">מְרָרִיתָא</a>.]</div>","alt":[]},"16668":{"h":"מָרֵישׁ","r":"M02692","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contr. of <span dir=\"rtl\">מארש</span>, v. <a href=\"#\" data-headword=\"אָרַס\">אָרַס</a>; cmp. Targ. of <span dir=\"rtl\">מורשי</span>, <span class=\"citation\">Job XVII, 11</span>: <span dir=\"rtl\">לוחי</span>) <i>joist, beam</i> (cmp. <a href=\"#\" data-headword=\"כָּשׁוֹרָא\">כְּשׁוּרָא</a>). <span class=\"citation\">Gitt. V, 5</span> <span dir=\"rtl\">המ׳ הגזול וכ׳</span> an illegally taken joist which was placed in a group of buildings. <span class=\"citation\">B. Kam. 66ᵇ</span> (ref. to Gitt. l. c.) <span dir=\"rtl\">והרי מ׳ כשורא וכ׳</span> here is the case of the <i>maresh</i> (where the stolen object changed its name), before it was placed it was named <a href=\"#\" data-headword=\"כָּשׁוֹרָא\">כשורא</a>, and now it is <a href=\"#\" data-headword=\"טְלַל III\">טללא</a> (ceiling); a. fr.—Pl. <span dir=\"rtl\">מָרֵישׁוֹת</span>. Ib. 67ᵃ, v. <a href=\"#\" data-headword=\"עוֹב\">עוֹב</a>. <span class=\"citation\">Y. B. Bath. I, beg. 12ᵈ</span> <span dir=\"rtl\">תיפתר ע׳&#x27;י מָרֵישָׁיו</span> it means (a protection) by means of its timber (roofing).</div>","alt":[]},"16669":{"h":"מָרֵישָׁא","r":"M02693","html":"<div class=\"sense\">; (collect.) <i>timber</i>. Targ. <span class=\"citation\">Hab. II, 11</span>. <span class=\"citation\">Targ. I Kings VI, 36</span>; a. e.</div>","alt":[]},"16670":{"h":"מְרֵית","r":"M02694","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מֵירַת\">מֵירַת</a>), <span dir=\"rtl\">חמר מ׳</span> <i>first flow of trodden grapes, sweet wine</i>. <span class=\"citation\">Targ. Is. XLIX, 26</span> (h. text <a href=\"#\" data-headword=\"עָסִיס\">עסיס</a>); a. e.</div>","alt":["(מְרַת)"]},"16671":{"h":"מֹרֶךְ","r":"M02695","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹרֶךְ\">מוֹרֶךְ</a></div>","alt":[]},"16672":{"h":"מָרַךְ","r":"M02696","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מֹרֶךְ\">מֹרֶךְ</a>; <a href=\"#\" data-headword=\"רָכַךְ\">רָכַךְ</a>) <i>to be soft; to soften</i>.</div><div class=\"sense\"><b>Nithpa. נִתְמָרֵךְ</b> <div class=\"sense\"><i>to be softened; liquefied</i> (of the brain or the spinal column). <span class=\"citation\">Ḥull. 45ᵇ</span>, v. <a href=\"#\" data-headword=\"הַמְרָכָה\">הַמְרָכָה</a>.</div></div>","alt":[]},"16673":{"h":"מְרַךְ","r":"M02697","html":"<div class=\"sense\"><b>Itphe. אִתְמְרִיךְ</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"מוֹרֶךְ\">מוֹרֶךְ</a>) <i>to be faint, become unsteady</i>. <span class=\"citation\">Targ. O. Deut. XIX, 5</span> ed. Berl., v. <a href=\"#\" data-headword=\"מְרַג\">מְרַג</a>.</div></div>","alt":[]},"16674":{"h":"מֶרְכָּב","r":"M02698","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>riding seat, saddle, handle of the saddle</i>, esp. (<span dir=\"rtl\">טומאת</span>) <a href=\"#\" data-headword=\"מ׳\">מ׳</a> <i>that degree of uncleanness which arises from an unclean man’s riding</i> (<span class=\"citation\">Lev. XV, 9</span>); <i>unclean saddle</i>. <span class=\"citation\">Tosef. Kel. B. Bath. II, 7</span>; <span class=\"citation\">Erub. 27ᵃ</span> <span dir=\"rtl\">האוכף טמא מושב והתפוס טמא מ׳</span> the saddle itself (on which an unclean man sat) is unclean as a seat, and its handle is unclean as a riding implement. <span class=\"citation\">Kel. I, 3</span>. <span class=\"citation\">Zab. V, 8</span>; a. fr.</div>","alt":[]},"16675":{"h":"מַרְכְּבָא","r":"M02699","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lev. XV, 9</span>; a. e.</div>","alt":["מֶרְ׳"]},"16676":{"h":"מֶרְכָּבָה","r":"M02700","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מַרְכְּבָא\">preced.</a>) <i>chariot</i>. <span class=\"citation\">Esth. R. to I, 2</span> (ref. to <span class=\"citation\">II Chr. IX, 17</span>) [read:] <span dir=\"rtl\">שהיה עשוי כמֶרְכַּבְתּוֹ של מי וכ׳</span> it was made like the chariot of him who spoke and the world existed. <span class=\"citation\">Num. R. s. 12</span> אגרת … ומֶרְכַּבְתָּהּ Igrath … and her chariot; a. e.—Esp. <i>the divine chariot of the vision of Ezekiel</i> (<span class=\"citation\">Ez. I</span>); <span dir=\"rtl\">מעשה מ׳</span>, or <a href=\"#\" data-headword=\"מ׳\">מ׳</a> <i>the mystic speculations on the divine chariot, esoterics</i>. <span class=\"citation\">Gen. R. s. 82</span> <span dir=\"rtl\">האבות הן הן המ׳</span> the patriarchs are the divine chariot. <span class=\"citation\">Ḥag. II, 1</span>. <span class=\"citation\">Ib. 13ᵃ</span> אגמרך במעשה המ׳ I shall instruct thee in the secret of the vision of Ezekiel. Ib. <span dir=\"rtl\">עד היכן מעשה המ׳</span> up to which verse (in <span class=\"citation\">Ez. I</span>) do the speculations on ‘the Chariot’ go (the communication of which is subject to certain restrictions)?—Tosef. Meg. IV (III), 28. <span class=\"citation\">Cant. R. to I, 4</span> (ref. to <span dir=\"rtl\">חדריו</span> ib.) <span dir=\"rtl\">מנין … ויגלה להם חדרי מ׳</span> how should Ezekiel be able to reveal to them the inwardness of the Chariot? Ib. 10 <span dir=\"rtl\">שמא בחדרי מ׳ וכ׳</span> hast thou perhaps been studying the secrets of the Chariot?; <span class=\"citation\">Lev. R. s. 16</span> <span dir=\"rtl\">בסדרי מ׳</span> (corr. acc.); a. fr.—Pl. <span dir=\"rtl\">מֶרְכָּבוֹת</span>. Pesik. Baḥod., p. 107ᵇ; <span class=\"citation\">Pesik. R. s. 21</span>; a. fr.</div>","alt":[]},"16677":{"h":"מַרְכְּבָנָא","r":"M02701","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מֶרְכָּבָה\">preced.</a> wds.) <i>chariot-driver</i>. <span class=\"citation\">Targ. I Kings XXII, 34</span>.</div>","alt":[]},"16678":{"h":"מַרְכַּבְתָּא","r":"M02702","html":"<div class=\"sense\"> יקרא <i>the divine Chariot</i>. <span class=\"citation\">Targ. I Kings VII, 33</span>; a. e.</div>","alt":[]},"16679":{"h":"מַרְכּוֹב","r":"M02703","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְכּוֹף\">מַרְכּיֹף</a></div>","alt":[]},"16680":{"h":"מַרְכּוֹל","r":"M02704","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְכָּל\">מַרְכָּל</a></div>","alt":[]},"16681":{"h":"מַרְכּוֹף","r":"M02705","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"*אַרְכּוֹף\">אַרְכּוֹף</a>) <i>markof</i>, name of a <i>musical instrument</i> made stationary. <span class=\"citation\">Kel. XV, 6</span> <span dir=\"rtl\">המ׳ טהור</span> the <i>m</i>. (used in the Temple) is not susceptible of uncleanness. <span class=\"citation\">Ib. XVI, 7</span> <span dir=\"rtl\">מ׳ של זמר</span> the <i>m</i>. used for the accompaniment of songs; <span class=\"citation\">Tosef. Kel. B. Mets. V, 10</span>.</div>","alt":["(מַרְכּוֹב)"]},"16682":{"h":"מָרְכְּיוֹתָא","r":"M02706","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹרְכִיוָותָא\">מוֹרְכִיוָותָא</a>,</div>","alt":[]},"16683":{"h":"מַרְכָּל","r":"M02707","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"*אֲמַרְכֹּול\">אֲמַרְכּוֹל</a>. <span class=\"citation\">Y. Sabb. X, 12ᶜ</span>. <span class=\"citation\">Y. Shek. V, 49ᵃ</span>; a. e.—Pl. <span dir=\"rtl\">מַרְכּוֹלִין</span>. <span class=\"citation\">Shek. V, 3</span> Y. ed.; a. e.</div>","alt":["מַרְכּוֹל"]},"16684":{"h":"מרכנתא","r":"M02708","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַר III\"><span dir=\"rtl\">מַר</span> III</a></div>","alt":[]},"16685":{"h":"מְרָמָא","r":"M02709","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרָמַם\">מְרָמַם</a></div>","alt":[]},"16686":{"h":"מִרְמָה","r":"M02710","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>fraud, guile</i>. <span class=\"citation\">Num. R. s. 20</span>. <span class=\"citation\">Koh. R. to I, 16</span> <span dir=\"rtl\">הלב עושה מ׳</span> the heart plans fraud; a. fr.</div>","alt":[]},"16687":{"h":"מַרְמָהוּז","r":"M02711","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. Löw Pfl., p. 252) <i>Origanum Marjorana, marjoram</i>, an aromatic plant. <span class=\"citation\">Gitt. 69ᵇ</span> top <span dir=\"rtl\">גווזא דמ׳</span> Ar. ed. Koh. (other ed. Ar. … <a href=\"#\" data-headword=\"הוֹן I\">הון</a>; Talm. ed. … <a href=\"#\" data-headword=\"*הִין I\">הין</a>) a piece of the stem of marjoram.</div>","alt":[]},"16688":{"h":"מרמוטא","r":"M02712","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מרמיטה\">מרמיטה</a></div>","alt":[]},"16689":{"h":"מַרְמוּצִי","r":"M02713","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְמַץ I\">רמץ</a>, v. <a href=\"#\" data-headword=\"רִמְצָא\">רִמְצָא</a>) <i>a wound from stepping on a pointed stone</i>. <span class=\"citation\">Koh. R. to VI, 11</span> <span dir=\"rtl\">או חדא מ׳</span> (not <a href=\"#\" data-headword=\"חַד I\">חד</a>), v. <a href=\"#\" data-headword=\"מַרְצוּמִי\">מַרְצוּמִי</a>.</div>","alt":[]},"16690":{"h":"מרמטא","r":"M02714","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מרמיטה\">next w.</a></div>","alt":[]},"16691":{"h":"מרמיטה","r":"M02715","html":"<div class=\"sense\">, a corruption, prob. to be read: <span dir=\"rtl\">מַדְמֵמָה</span> f. (<a href=\"#\" data-headword=\"דָּמַם\">דמם</a>) <i>trance, catalepsy</i>. <span class=\"citation\">Gen. R. s. 17</span> (and thence copied in s. 44; <span class=\"citation\">Yalk. Gen. 23</span> <a href=\"#\" data-headword=\"מרמטא\">מרמטא</a>; <span class=\"citation\">Yalk. Sam. 139</span> <span dir=\"rtl\">דורמיטא</span>).</div>","alt":[]},"16692":{"h":"מַרְמֵיר","r":"M02716","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרַר\">מְרַר</a></div>","alt":[]},"16693":{"h":"מַרְמִירָא","r":"M02717","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (marmor, μάρμαρος) <i>marble</i>, in gen. <i>polished stone</i>. <span class=\"citation\">Targ. Y. Deut. IX, 9</span>, sq.; a. e.—Pl. <span dir=\"rtl\">מַרְמִירִין</span>, <span dir=\"rtl\">מַרְמִירַיָּא</span>. <span class=\"citation\">Ib. V, 19</span>. <span class=\"citation\">Targ. Esth. I, 6</span>. <span class=\"citation\">Targ. I Chr. XXIX, 2</span>. <span class=\"citation\">Targ. Lam. III, 9</span>.—V. <a href=\"#\" data-headword=\"מַרְמָרָא\">מַרְמָרָא</a>.</div>","alt":["מַרְמֵי׳"]},"16694":{"h":"מְרָמַם","r":"M02718","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוּם\">רוּם</a>) <i>uplifted, high</i>. <span class=\"citation\">Targ. O. Ex. VI, 6</span> (ed. Vien. <a href=\"#\" data-headword=\"מְרָמָא\">מְרָמָא</a>; Y. <a href=\"#\" data-headword=\"מְרוֹמָא I\">מְרוֹמָא</a>). <span class=\"citation\">Targ. Y. I Ex. XIV, 8</span>; a. fr.</div>","alt":["מְרַמְמָא"]},"16695":{"h":"מִרְמָס","r":"M02719","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>that which is trodden upon</i>. Tanḥ. ed. Bub., <span class=\"citation\">B’resh. 23</span>; Yalk. Dan. 1066 <span dir=\"rtl\">עד מתי הם מ׳ לאו׳&#x27;ה</span> how long will they be trodden upon by the nations? <span class=\"citation\">Gen. R. s. 21</span> <span dir=\"rtl\">מ׳ לפני מלאך וכ׳</span> trodden upon by the angel of death.</div>","alt":[]},"16696":{"h":"מְרַמְצָא","r":"M02720","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְמַץ I\">רְמַץ</a>) <i>casing, ouch</i>.—Pl. <a href=\"#\" data-headword=\"מְרַמְצָא\">מְרַמְצָן</a>, <span dir=\"rtl\">מְרַמְצָתָא</span>. <span class=\"citation\">Targ. Ex. XXVIII, 13</span>, sq. (h. text <span dir=\"rtl\">משבצות</span>); a. e.—V. <a href=\"#\" data-headword=\"רְמַץ I\"><span dir=\"rtl\">רְמַץ</span> I</a>.</div>","alt":[]},"16697":{"h":"מִרְמֵר","r":"M02721","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָרַר\">מָרַר</a>, <a href=\"#\" data-headword=\"מְרַר\"><a href=\"#\" data-headword=\"מְרַר\">מְרַר</a>.</a></div>","alt":["מַרְמֵר"]},"16698":{"h":"מרמר","r":"M02722","html":"<div class=\"sense\">, Y. B. Bath. X, 17ᶜ some ed., read: <a href=\"#\" data-headword=\"מִדְּמַר\">מִדְּמַר</a>, v. <a href=\"#\" data-headword=\"מַר IV\"><span dir=\"rtl\">מֵר</span> I</a></div>","alt":[]},"16699":{"h":"מַרְמָרָא","r":"M02723","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מַרְמִירָא\">מַרְמִירָא</a>) <i>white marble</i>. <span class=\"citation\">Succ. 51ᵇ</span> <span dir=\"rtl\">שישא כוחלא ומ׳</span> yellow, black and white marble; <span class=\"citation\">B. Bath. 4ᵃ</span>; <span class=\"citation\">Yalk. Deut. 913</span>.—Pl. <span dir=\"rtl\">מַרְמָרִין</span> (marmora) <i>marble</i> or <i>cemented pavement</i>. <span class=\"citation\">Targ. Esth. I, 6</span>.—<span class=\"citation\">Y. Ter. VIII, 45ᵈ</span> bot. <span dir=\"rtl\">יתבי בחר ביתא אזלו מ׳</span> sat in a house the pavement (of which) was worn out.</div>","alt":[]},"16700":{"h":"מֶרֶס","r":"M02724","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Meres</i>, one of the attendants of King Ahasver. <span class=\"citation\">Esth. R. to I, 14</span>, v. <a href=\"#\" data-headword=\"מָרַס\">next w.</a></div>","alt":[]},"16701":{"h":"מָרַס","r":"M02725","html":"<div class=\"sense\">, <i>Pi.</i> <a href=\"#\" data-headword=\"מִירָם\">מֵירֵס</a> (denom. of <a href=\"#\" data-headword=\"מֶרֶס\">מֶרֶס</a> fr. <span dir=\"rtl\">רסס</span>) <i>to crush</i>; <i>to rub; to stir</i>. <span class=\"citation\">Esth. R. to I, 14</span> (play on <a href=\"#\" data-headword=\"מֶרֶס\">מֶרֶס</a> ib.) <span dir=\"rtl\">שהיה מְמָרֵס את העופות</span> he prepared the hash of birds; ib. (play on <a href=\"#\" data-headword=\"מַרְסְנָא\">מרסנא</a>, ib.) <span dir=\"rtl\">שהיה ממרס את הסלתות</span> he stirred the flour (making dough). Ib. <span dir=\"rtl\">מי ממ׳ לפניך את הדם</span> (not <span dir=\"rtl\">העופות</span>, v. infra) who will stir before thee the blood (of the sacrifices)?; <span dir=\"rtl\">מי ממ׳ … הסלתות</span> who will stir the flour (for the meal offerings)? Ib. (play on <span dir=\"rtl\">מ̇ר̇ס̇ מ̇ר̇ס̇נא ממ̇ו כ̇ן</span>, ib.) <span dir=\"rtl\">ממ̇ר̇ס̇ אני מ̇סר̇ס̇ וממ̇ע̇ך וכ׳</span> I will crush, chop and dissolve their lives &amp;c.; <span class=\"citation\">Meg. 12ᵇ</span> <span dir=\"rtl\">כלום מֵ֗ירְ֗ס֗וּ בדם לפניך</span> did they ever stir the blood (of sacrifices) before thee? <span dir=\"rtl\">כלום מ̇ירס̇ו לפניך במנ̇חות</span> did they ever stir the flour for the meal offerings &amp;c.?; <span class=\"citation\">Yalk. Esth. 1051</span> <span dir=\"rtl\">מֵרְסוּ</span>. <span class=\"citation\">Yoma IV, 3</span>; <span class=\"citation\">V, 3</span>; a. fr.—<span class=\"citation\">Shebi. II, 10</span> <span dir=\"rtl\">מְמָרְסִין באורז וכ׳</span> you may, in the Sabbatical year, stir (mix) the ground of a rice field with water (so as to make it dough-like).</div>","alt":[]},"16702":{"h":"מְרַס","r":"M02726","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Esth. I, 14</span>.—<span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">נִימַרְסֵיה וכ׳</span>, and let him rub it (the garlic) with oil.—Part. pass. <span dir=\"rtl\">מְרִיס</span>. <span class=\"citation\">Targ. O. Lev. XXI, 20</span> (h. text <a href=\"#\" data-headword=\"מרוח\">מרוח</a>, v. <a href=\"#\" data-headword=\"מָרַח\">מָרַח</a>). <span class=\"citation\">Ib. XXII, 24</span> (h. text <span dir=\"rtl\">מעוך</span>).</div>","alt":[]},"16703":{"h":"מַרְסְנָא","r":"M02727","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Mars’na</i>, one of the attendants of King Ahasver. <span class=\"citation\">Esth. R. to I, 14</span>; a. e., v. <a href=\"#\" data-headword=\"מָרַס\">מָרַס</a>.</div>","alt":[]},"16704":{"h":"מֵרַע","r":"M02728","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָעַע\">רָעַע</a>) <i>shaking, weakening</i>. <span class=\"citation\">Y. B. Mets. I, end, 8ᵃ</span> <span dir=\"rtl\">מפני מ׳ כחן וכ׳</span> because this would injure the privilege of the purchaser.</div>","alt":["מֵי׳"]},"16705":{"h":"מְרַע I","r":"M02729","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מְרַע II\">next w.</a>) </div><div class=\"sense\"><b>1)</b> <i>to become</i> or <i>be weak, fall sick</i>. <span class=\"citation\">Targ. Is. XIV, 10</span>. <span class=\"citation\">Ib. XXIII, 4</span> (h. text <span dir=\"rtl\">חלתי</span>). <span class=\"citation\">Targ. Ps. XLI, 9</span> (h. text <span dir=\"rtl\">שכב</span>, v. <a href=\"#\" data-headword=\"מְרַע II\">next w.</a>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be shaken, quake</i>. <span class=\"citation\">Targ. Mic. IV, 10</span>.</div><div class=\"sense\"><b>Af. אַמְרַע</b> <div class=\"sense\"><i>to make sick, afflict</i>. <span class=\"citation\">Targ. O. Deut. XXIX, 21</span>. <span class=\"citation\">Targ. Y. II, Gen. III, 15</span>.</div></div><div class=\"sense\"><b>Pa. מָרַע</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מֵרַע\">same</a>. <span class=\"citation\">Targ. Jer. XIV, 17</span>; <span class=\"citation\">Targ. Nah. III, 19</span> (not <span dir=\"rtl\">מִמְרָ׳</span>) <i>grievous</i> (h. text <a href=\"#\" data-headword=\"נַחֲלָה\">נחלה</a>).—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מְמַרַע\">מְמַרַע</a> <i>suffering, unwell</i>. <span class=\"citation\">Targ. Jer. XIV, 18</span>. <span class=\"citation\">Targ. I Sam. XIX, 14</span> ed. Lag. (oth. ed. <span dir=\"rtl\">שכיב מרע</span>, v. <a href=\"#\" data-headword=\"מְרַע II\">next w.</a>). <span class=\"citation\">Targ. I Kings XIV, 5</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"מְרַע I\">מרע</a>); a. e.</div></div><div class=\"sense\"><b>Ithpa. אִתְמַרַע</b> </div><div class=\"sense\"><b>Ithpe. אִתְמְרַע</b> <div class=\"sense\"><b>1)</b> <i>to fall sick</i>. <span class=\"citation\">Targ. I Kings XIV, 1</span> (ed. Lag. <a href=\"#\" data-headword=\"מְרַע I\">מרע</a>). <span class=\"citation\">Ib. XXII, 34</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"מְרַע I\">מרע</a>). <span class=\"citation\">Targ. II Sam. XIII, 2</span>; a. e.—<span class=\"citation\">Koh. R. to X, 16</span> (ref. to <a href=\"#\" data-headword=\"שְׁכָבָה\">שכבה</a>, <span class=\"citation\">I Kings III, 19</span>) <span dir=\"rtl\">אִיתְמַרְעַת עלוי</span> (not … <span dir=\"rtl\">רטת</span>) she fell sick (fainted and fell) upon him (cmp. Targ. to <span class=\"citation\">Ps. XLI, 9</span>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to feign sickness</i>. <span class=\"citation\">Targ. II Sam. XIII, 5</span>. sq.</div><div class=\"sense\"><b>—3)</b> <i>to be shaken, quake</i>. <span class=\"citation\">Targ. Jer. LI, 29</span>.</div></div>","alt":[]},"16706":{"h":"מְרַע II","r":"M02730","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"רְעַע\">רְעַע</a>) <i>sick, suffering</i>. <span class=\"citation\">Targ. Y. Gen. XVIII, 1</span> <span dir=\"rtl\">מ׳ מִכֵּיבָא וכ׳</span> (not <a href=\"#\" data-headword=\"מַכִּיר\">מַכִּי׳</a>) suffering from the wound &amp;c.; <span class=\"citation\">Targ. Y. I Deut. XXXIV, 6</span> <span dir=\"rtl\">מ׳ מִגְּזֵרַת וכ׳</span>. <span class=\"citation\">Targ. O. Gen. XLVIII, 1</span> <a href=\"#\" data-headword=\"מְרַע II\">מְרָע</a> ed. Berl. (oth. ed. a. Y. <span dir=\"rtl\">שכיב מ׳</span>); a. fr.—Esp. (in Talm. also in Hebr. dict.) <span dir=\"rtl\">שכיב מ׳</span> <i>dangerously ill, expected to die</i>. <span class=\"citation\">Targ. I Sam. XIX, 14</span> (v. <a href=\"#\" data-headword=\"מְרַע I\">preced.</a>).—<span class=\"citation\">B. Bath. IX, 6</span> <span dir=\"rtl\">שכיב מ׳ שכתב וכ׳</span> if a sick man assigns all of his property to a stranger (as an unqualified donation, v. <a href=\"#\" data-headword=\"מַתָּנָה\">מַתָּנָה</a>). Ib. <span dir=\"rtl\">לא כתב בה ש׳ מ׳</span> if it was not stated in the document that he was sick; <span dir=\"rtl\">הוא אומר ש׳ מ׳ היה</span> he (the donor) says that he was sick (at the time), opp. <span dir=\"rtl\">בריא</span>. Ib. 152ᵃ, a. fr. <span dir=\"rtl\">מתנת ש׳ מ׳</span> the donation of a sick man; a. v. fr.—Pl. <span dir=\"rtl\">מַרְעִין</span>, <span dir=\"rtl\">מַרְעַיָּא</span>. Targ. Y. I Deut. l. c. <span class=\"citation\">Targ. Ps. CXXVI, 1</span> <span dir=\"rtl\">היך מ׳ וכ׳</span> like the sick when recovering (h. text <span dir=\"rtl\">כחלמים</span>, v. <a href=\"#\" data-headword=\"חָלַם I\"><span dir=\"rtl\">חָלַם</span> I</a>). <span class=\"citation\">Targ. Ez. XXXIV, 4</span>; a. e.; v. <a href=\"#\" data-headword=\"מְרִיעַ\">מְרִיעַ</a>.—<i>Fem</i>. <a href=\"#\" data-headword=\"מְרַע III\">מַרְעָא</a>, <span dir=\"rtl\">מְרַעֲתָא</span>, <a href=\"#\" data-headword=\"מְרָעִיתָא\">מְרָעיתָא</a>. <span class=\"citation\">Targ. Ps. LXIX, 21</span> <span dir=\"rtl\">והא היא מרעא</span> ed. Lag. (Var. <a href=\"#\" data-headword=\"מוֹץ ³\">מוצא</a>, cler. error; ed. Wil. <span dir=\"rtl\">והא היא תקיפא</span>; h. text <span dir=\"rtl\">וָאָנוּשָׁה</span>). <span class=\"citation\">Targ. Cant. II, 5</span>. <span class=\"citation\">Ib. V, 8</span>. <span class=\"citation\">Targ. Koh. V, 12</span>; <span class=\"citation\">15</span>; a. e.—Pl. <span dir=\"rtl\">מְרָעְאָן</span>. <span class=\"citation\">Targ. Y. Gen. XXX, 36</span> (some ed. <span dir=\"rtl\">מַרְעָאָן</span>).</div>","alt":["מְרָע"]},"16707":{"h":"מְרַע III","r":"M02731","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"מְרַע II\">preced.</a>) <i>evil, sickness, affliction</i>. <span class=\"citation\">Targ. I Kings VIII, 37</span>. <span class=\"citation\">Targ. Koh. VI, 2</span>; a. fr.—<span class=\"citation\">B. Bath. 153ᵃ</span> (in a formula of a deed of donation) <span dir=\"rtl\">ומגו מַרְעֵיה וכ׳</span> and in consequence of (this) his sickness he departed &amp;c.—Pl. <span dir=\"rtl\">מַרְעִין</span>. <span class=\"citation\">Targ. O. Ex. XXIII, 25</span>. <span class=\"citation\">Targ. Ps. CXVI, 3</span> מַרְעֵי Ms. (ed. <a href=\"#\" data-headword=\"מַרְעֵי I\">מְרָעֵי</a>); a. fr.</div>","alt":["מַרְעָא"]},"16708":{"h":"מִרְעָא","r":"M02732","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְעֵי I\"><span dir=\"rtl\">מַרְעֵי</span> I</a></div>","alt":[]},"16709":{"h":"מִרְעֶה","r":"M02733","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>pasture</i>. <span class=\"citation\">Pesik. R. s. 16</span>; <span class=\"citation\">Yalk. Kings 176</span> (expl. <a href=\"#\" data-headword=\"רעי\">רעי</a>, <span class=\"citation\">I Kings V, 3</span>) <span dir=\"rtl\">מן המ׳</span> directly from the pasture ground. <span class=\"citation\">Num. R. s. 10</span> <span dir=\"rtl\">כל המ׳</span> the whole flock; a. e.</div>","alt":[]},"16710":{"h":"מַרְעוּ","r":"M02734","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"מְרַע III\"><span dir=\"rtl\">מְרַע</span> III</a>. <span class=\"citation\">Targ. Ps. LXXVII, 11</span> <span dir=\"rtl\">מַרְעוּתִי</span> (ed. Wil. <a href=\"#\" data-headword=\"מַרְכְּבָא\">מֵרְ׳</a>; Ms. <span dir=\"rtl\">מַרְעִיתִי</span>). <span class=\"citation\">Ib. XXXV, 13</span>; v. <a href=\"#\" data-headword=\"מַרְעִית II\"><span dir=\"rtl\">מַרְעִיתָא</span> I</a></div>","alt":["מַרְעוּתָא"]},"16711":{"h":"מַרְעֵי I","r":"M02735","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. Y. I Gen. XIII, 7</span>. Targ. II Esth. IV, 1.—Pl. <span dir=\"rtl\">מִרְעַיָּיא</span>, <a href=\"#\" data-headword=\"מַרְעֵי I\">מִירְ׳</a>. <span class=\"citation\">Tem. 18ᵃ</span> <span dir=\"rtl\">אפי׳ ממִירְעַיְיהוּ</span> even if you have to take them away from their pastures, v. <a href=\"#\" data-headword=\"מוֹרִיגָא\">מוֹרִיגָא</a>.—[<span class=\"citation\">Targ. Y. Deut. XXXIII, 24</span>, v. <span dir=\"rtl\">רְעֵי II</span>.]</div>","alt":["מִירְעָא","מִרְ׳"]},"16712":{"h":"מַרְעֵי II","r":"M02736","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רְעִי III\"><span dir=\"rtl\">רְעִי</span> II</a>) <i>dung</i>. <span class=\"citation\">Targ. Y. II, Lev. XVI, 27</span> <span dir=\"rtl\">מַרְעַיְיהוֹן</span>.</div>","alt":[]},"16713":{"h":"מַרְעֵילָא","r":"M02737","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְעֵלָא\">מַרְעֵלָא</a></div>","alt":[]},"16714":{"h":"מַרְעִית I","r":"M02738","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>pasture-ground, pasture</i>. <span class=\"citation\">Pesik. R. s. 26</span>, end <span dir=\"rtl\">והיא עשויה מ׳ וכ׳</span> and she (Zion) has become a pasture-ground for the beasts of the field. <span class=\"citation\">B. Mets. 86ᵇ</span> (fusion of Hebr. a. Chald.) <span dir=\"rtl\">מביאין תור ממַרְעִיתוֹ וכ׳</span> (v. Rabb. D. S. a. l. note 60) they bring from his pasture an ox that has not been forced (used for labor) &amp;c.; <span class=\"citation\">Yalk. Kings 176</span> (not <span dir=\"rtl\">ממרעיתן</span>); a. e.—Trnsf. <i>feeding one’s eye, satisfaction</i>. <span class=\"citation\">Cant. R. to IV, 5</span> (ref. to <a href=\"#\" data-headword=\"רָעַם\">הרעים</a>, ib.) <span dir=\"rtl\">והיכן היתה מַרְעִיתָן וכ׳</span> where did the Israelites have their satisfaction on Egypt?</div>","alt":[]},"16715":{"h":"מַרְעִית II","r":"M02739","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"מַרְעוּ\">מַרְעוּתָא</a>, <i>evil</i> &amp;c. <span class=\"citation\">Targ. Ps. CXXIV, 4</span> (h. text <a href=\"#\" data-headword=\"נַחֲלָה\">נחלה</a>); a. e., v. <a href=\"#\" data-headword=\"מַרְעוּ\">מַרְעוּ</a>.</div>","alt":["מַרְעֵיתָא I"]},"16716":{"h":"מַרְעִיתָא II","r":"M02740","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"מִרְעֶה\">מִרְעֶה</a>. <span class=\"citation\">Targ. I Chr. IV, 39</span>, sq.</div>","alt":[]},"16717":{"h":"מְרָעִיתָא","r":"M02741","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרַע II\"><span dir=\"rtl\">מְרַע</span> II</a></div>","alt":[]},"16718":{"h":"מַרְעֵלָא","r":"M02742","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְעַל\">רְעֵל</a>) <i>long pouch thrown over an animal’s back, haversack</i>. <span class=\"citation\">Lev. R. s. 25</span>; <span class=\"citation\">Koh. R. to II, 20</span>.</div>","alt":["מַרְעֵי׳"]},"16719":{"h":"מַרְעֶשֶׁת","r":"M02743","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"מַרְחֶשֶׁת II\"><span dir=\"rtl\">מַרְחֶשֶׁת</span> II</a></div>","alt":["מַרְעַשְׁתָּא"]},"16720":{"h":"מַרְפֵּא","r":"M02744","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>healing, recovery</i>. <span class=\"citation\">Keth. 103ᵃ</span> <span dir=\"rtl\">לשון חכמים מ׳</span> (v. <span class=\"citation\">Prov. XII, 18</span>) the tongue of the wise teaches medicine (indirectly, ref. to <span class=\"citation\">Pes. II, 7</span>).—Esp. ‘<i>your health</i>’, a wish uttered to one sneezing. <span class=\"citation\">Tosef. Sabb. VII</span> (<span class=\"citation\">VIII), 5</span> <span dir=\"rtl\">האומר מ׳ הרי זה וכ׳</span> (not <span dir=\"rtl\">האמר</span>) to say <i>marpé</i> is a superstitious practice (v. <a href=\"#\" data-headword=\"אֱמוֹרִי\">אֱמוֹרִי</a>). Ib. <span dir=\"rtl\">לא אמר מ׳ מפני וכ׳</span> did not say <i>m</i>. (at college), because it is an interruption of study; <span class=\"citation\">Ber. 53ᵃ</span></div>","alt":[]},"16721":{"h":"מְרַפֵּא","r":"M02745","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מַרְפֵּא\">preced.</a>) <i>surgeon, operator</i>. Mekh. Mishp., N’zik., s. 4 <span dir=\"rtl\">מ׳ שהמית</span> a surgeon who caused the death of his patient (through negligence), v. <a href=\"#\" data-headword=\"עָרַם II\"><span dir=\"rtl\">עָרַם</span> II</a>.</div>","alt":[]},"16722":{"h":"מַרְפְּיָיתָה","r":"M02746","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> name of certain <i>fruits</i> (prob. so named from their loosening effect on the bowels, v. <a href=\"#\" data-headword=\"רָפָה\">רָפָה</a>), perh. a certain kind of <i>apples</i>. <span class=\"citation\">Y. Maasr. I, 48ᵈ</span> bot.</div>","alt":[]},"16723":{"h":"מרפיס","r":"M02747","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִנְפִּיס\">מִנְפִּיס</a></div>","alt":[]},"16724":{"h":"מַרְפֵּיק","r":"M02748","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"מַרְתֵּיקָא\">מַרְפֵּיקָא</a>, v. <a href=\"#\" data-headword=\"מַרְפֵּק\">מַרְפֵּק</a>, <a href=\"#\" data-headword=\"מַרְפְּקָא\"><a href=\"#\" data-headword=\"מַרְפְּקָא\">מַרְפֵּקָא</a>.</a></div>","alt":[]},"16725":{"h":"מִרְפָּס","r":"M02749","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>that which is trodden</i>. <span class=\"citation\">Pirké d’R. El. ch. XLVII</span> <span dir=\"rtl\">שלא ישתה … כי אם מִרְפַּס רגלם</span> that no Israelite shall drink the wine of idolaters, but only wine trodden with their own feet (allud. to <span class=\"citation\">Ez. XXXIV, 19</span>).</div>","alt":[]},"16726":{"h":"מַרְפֶּסֶת","r":"M02750","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִרְפָּס\">preced.</a>) <i>a gallery</i> or <i>balcony</i> to which doors of the upper compartments open, and from which steps lead down to the court. <span class=\"citation\">Erub. VIII, 3</span> <span dir=\"rtl\">אנשי מ׳</span> tenants that have a common gallery; <span class=\"citation\">ib. 83ᵇ</span>, sq. <span dir=\"rtl\">קס&quot;ד מאי מ׳ בני עלייה וכ׳</span> at first it was thought <i>marpeseth</i> (in Mishn. l. c.) meant the dwellers of the upper story, and they are so called, because they go up to their rooms by the way of the gallery; <span dir=\"rtl\">אותן הדרים במ׳</span> those who have rooms on the gallery itself. Tosef. ib. IX (VI); 19; a. fr.</div>","alt":[]},"16727":{"h":"מַרְפֵּק","r":"M02751","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָפַק\">רָפַק</a>; cmp. Arab. marfiḳ) <i>elbow</i>. <span class=\"citation\">Sabb. X, 3</span> (<span class=\"citation\">92ᵃ</span>). <span class=\"citation\">Arakh. V, 1</span> <span dir=\"rtl\">עד מַרְפֵּיקוֹ</span> up to his elbow (<span class=\"citation\">Tosef. ib. III, 2</span> <span dir=\"rtl\">האציל</span>). Ohol. I, 8 <span dir=\"rtl\">שנים במ׳</span> two joints are in the elbow. <span class=\"citation\">Gen. R. s. 44</span> <span dir=\"rtl\">אוחזין אותו במַרְפֵּקוֹ וכ׳</span> held him by his elbow that he might not fall; ib. s. 65; <span class=\"citation\">Yalk. Gen. 115</span>; <span class=\"citation\">Yalk. Is. 313</span>.</div>","alt":[]},"16728":{"h":"מַרְפְּקָא","r":"M02752","html":"<div class=\"sense\">; pl. constr. <span dir=\"rtl\">מַרְפְּקֵי</span> same. <span class=\"citation\">Targ. Ez. XIII, 18</span>; (Tosaf. to <span class=\"citation\">Men. 37ᵃ</span> quotes <a href=\"#\" data-headword=\"מַרְפֵּיק\">מַרְפֵּיקי</a>, R. S. to Ohol. I, 8 <span dir=\"rtl\">מרפקי</span>); v. <a href=\"#\" data-headword=\"מַדְבַּק\">מַדְבַּק</a>.</div>","alt":[]},"16729":{"h":"מָרַץ","r":"M02753","html":"<div class=\"sense\"><i>to quicken</i>.</div><div class=\"sense\"><b>Nif. נִמְרָץ</b> <div class=\"sense\"><i>to be made rapid, to flow rapidly</i> in a gutter. <span class=\"citation\">Tosef. Par. IX</span> (<span class=\"citation\">VIII), 8</span> <span dir=\"rtl\">המים הנמשכין והנִמְרָצִין</span> ed. Zuck. (Var. <span dir=\"rtl\">והנגררין</span>, v. <a href=\"#\" data-headword=\"נָגַר\">נָגַר</a>; R. S. to <span class=\"citation\">Par. IX, 5</span> <span dir=\"rtl\">והנזרקין</span>) water running slowly in a channel or rapidly in a gutter. <span class=\"citation\">Num. R. s. 9</span> (play on <span dir=\"rtl\">נ̇מ̇ר̇ץ̇</span>, <span class=\"citation\">Mic. II, 10</span>) <span dir=\"rtl\">נ̇ואף מ̇מזר וכ׳</span>; <span class=\"citation\">Sabb. 105ᵃ</span> (play on <span dir=\"rtl\">נ̇מ̇ר̇צ̇ת</span>, <span class=\"citation\">I Kings II, 8</span>), v. <a href=\"#\" data-headword=\"נוֹטָרִיקוֹן\">נוֹטָרִיקוֹן</a>.</div></div>","alt":[]},"16730":{"h":"מַרְצוּמִי","r":"M02754","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָצַם\">רצם</a>) <i>contusion</i>. <span class=\"citation\">Koh. R. to VI, 11</span> (a gloss to <a href=\"#\" data-headword=\"מַרְמוּצִי\">מרמוצי</a>) <span dir=\"rtl\">ויש אומרים מ׳</span> some read <i>martsumi</i></div>","alt":[]},"16731":{"h":"מַרְצוּף","r":"M02755","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, only in pl. <span dir=\"rtl\">מַרְצוּפִים</span>, (<a href=\"#\" data-headword=\"רָצַף\">רָצַף</a>) <span dir=\"rtl\">מַרְצוּפִין</span> <i>packing bags, leather bags</i>, esp. adapted for ship-loads. <span class=\"citation\">Kel. XX, 1</span> (ed. Dehr. <span dir=\"rtl\">מרצפין</span>). <span class=\"citation\">B. Bath. V, 1</span>. Y. Sabb. X, end, 12ᵈ, v. <a href=\"#\" data-headword=\"חָדַק\">חָדַק</a>; a. fr.—[Cmp. μάρσιπος, marsupium, prob. of Semitic origin.]</div>","alt":[]},"16732":{"h":"מַרְצַיָּיה","r":"M02756","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְצְעָא\">מַרְצְעָא</a></div>","alt":[]},"16733":{"h":"מַרְצֵעַ","r":"M02757","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>awl, borer</i>. <span class=\"citation\">Kidd. 21ᵇ</span> המ׳ להביא המ׳ הגדול ‘the awl’ (<span class=\"citation\">Deut. XV, 17</span>), this includes the largest awl (borer); <span class=\"citation\">Sifré Deut. 122</span>; a. fr.—Pl. <span dir=\"rtl\">מַרְצֵעִין</span>. Kidd. l. c.</div>","alt":[]},"16734":{"h":"מַרְצְעָא","r":"M02758","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מַרְצֵעַ\">same</a>. <span class=\"citation\">Targ. O. Ex. XXI, 6</span>; a. e.—<span class=\"citation\">Y. Maas. Sh. V, 56ᵇ</span> sq. <span dir=\"rtl\">מַרְצְעָה דעקיבא וכ׳</span> the awl (penetrating acumen) of Akiba … has been here.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"רְצוּעָה\">רְצוּעָה</a>) <i>strap</i>.—Pl. <a href=\"#\" data-headword=\"מַרְצַיָּיה\">מַרְצְעַיָּיה</a>, contr. <a href=\"#\" data-headword=\"מַרְצַיָּיה\">מַרְצַיָּיה</a>. Y. Sot. I, 16ᵈ bot. [read:] <span dir=\"rtl\">לא הוינן מייתין ספסלייה ומ׳ ומלקין ליה ומרציין וכ׳</span> should we not have brought in benches and straps and smitten him and reconciled him to his wife?</div>","alt":[]},"16735":{"h":"מַרְצֵף","r":"M02759","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְצוּף\">מַרְצוּף</a></div>","alt":[]},"16736":{"h":"מָרַק","r":"M02760","html":"<div class=\"sense\"> sec. r. of <span dir=\"rtl\">רק</span>; cmp. <a href=\"#\" data-headword=\"מֻצְהָב\">מצהב</a>, <span class=\"citation\">Targ. II Chr. IV, 16</span>) <i>to brighten, cleanse</i> (metal); <i>to scour, scald</i>. Sifra Tsav, Par. 3, ch. VI; <span class=\"citation\">Zeb. XI, 6</span> <span dir=\"rtl\">מוֹרְקוֹ ושוטפו וכ׳</span> he must scour and rinse it &amp;c.; <span class=\"citation\">Tosef. ib. X, 13</span> <span dir=\"rtl\">מוֹרְקָן</span> (not <span dir=\"rtl\">מוריקן</span>); a. fr.</div><div class=\"sense\"><b>Nif. נִמְרַק</b> <div class=\"sense\"><i>to be cleansed, purged</i>. <span class=\"citation\">Ab. d’R. N. ch. I</span>, beg. <span dir=\"rtl\">בשביל שיִמָּרֵק מכל וכ׳</span> that he might be cleansed of all the food and drink in his bowels.—[<span class=\"citation\">Tosef. B. Bath. XI, 9</span> <a href=\"#\" data-headword=\"מָרַק\">נמרק</a>, read: <a href=\"#\" data-headword=\"מחַק\">נִמְחַק</a>].</div></div><div class=\"sense\"><b>Pi. מֵירֵק</b> <div class=\"sense\"><b>1)</b> <i>to polish up</i>. Koh. R. beg. <span dir=\"rtl\">סיתתה ומֵירְקָהּ</span> he chiselled the stone and polished it, v. <a href=\"#\" data-headword=\"כִּרְכִּם\">כִּרְכֵּם</a>. <span class=\"citation\">Sabb. 33ᵃ</span> (ref. to <span dir=\"rtl\">תמרוק</span>, <span class=\"citation\">Prov. XX, 30</span>) <span dir=\"rtl\">המְמָרֵק עצמו וכ׳</span> he who polishes himself (makes toilet, prepares himself) for a sinful act; (Rashi: who makes himself free from all other thoughts, devoting himself entirely to sin, v. infra).</div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">מכה בפטיש</span>) <i>to finish</i>. <span class=\"citation\">Tosef. Ḥull. I, 2</span> <span dir=\"rtl\">ומ׳ הגוי וכ׳</span> and a gentile finished the slaughtering (by cutting farther than the ritual requires); (<span class=\"citation\">Ḥull. 121ᵇ</span> <span dir=\"rtl\">גמר</span>); <span class=\"citation\">Yoma III, 4</span> <span dir=\"rtl\">ומֵרַ׳</span>; <span class=\"citation\">Ḥull. 29ᵃ</span> <span dir=\"rtl\">ומֵי׳</span>. <span class=\"citation\">Tam. IV, 2</span> <span dir=\"rtl\">מ׳ את ההפשט</span> he finishes the flaying. <span class=\"citation\">Mikv. X, 1</span> <span dir=\"rtl\">הכניסן … ולא מֵרְקָן</span> he inserted the handles properly but did not finish them off (by fastening &amp;c.). Ohol. XIII, 3 <span dir=\"rtl\">הגיפה ולא מֵירְקָהּ</span> he fitted the door in, but did not finish it off (so that it fitted accurately). Y. R. Hash. I, end, 57ᶜ, a. e. <span dir=\"rtl\">מכיון שהתחיל … מָרֵק</span> inasmuch as he commenced the act, we say to him, finish it; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to cleanse</i> from sin by suffering, <i>to remove sin, effect forgiveness</i>. <span class=\"citation\">Ber. 5ᵃ</span> <span dir=\"rtl\">יסורין שמְמָרְקִין כל וכ׳</span> sufferings which cleanse the entire body of man; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ממרקין כל עונותיו וכ׳</span> wash away all sins of man; <span class=\"citation\">Yalk. Ex. 339</span>; <span class=\"citation\">Yalk. Deut. 850</span>. <span class=\"citation\">Yoma 86ᵃ</span> <span dir=\"rtl\">מיתה מְמָרֶקֶת</span> death finishes the atonement (v. supra); Y. Snh. X, 27ᶜ bot. <span dir=\"rtl\">מיתה ממרקת שליש</span> death removes the last third of sins; a. fr.—Y. Keth. VI, beg. 30ᶜ (in mixed dict.) <span dir=\"rtl\">ולא מְמָרֵק לה פורנה</span> and does not pay off the entire dowry.—<span class=\"citation\">Sabb. 33ᵃ</span>, v. supra.</div></div><div class=\"sense\"><b>Hof. הוּמְרַק</b> <div class=\"sense\"><i>to be washed off, cleansed</i>. <span class=\"citation\">Snh. 92ᵃ</span> וה׳ סידו Ar. s. v. <span dir=\"rtl\">סר</span> 3, ed. Koh., v. <a href=\"#\" data-headword=\"מָקַק\">מָקַק</a> <i>Hof</i></div></div>","alt":[]},"16737":{"h":"מְרַק","r":"M02761","html":"<div class=\"sense\"><a href=\"#\" data-headword=\"מָרַק\">same</a>, <i>to polish; to cleanse</i>. <span class=\"citation\">Targ. Is. XXI, 5</span> (ed. Wil. <a href=\"#\" data-headword=\"מָרִי\">מָרִי׳</a> <i>Pa</i>.). <span class=\"citation\">Targ. Y. II, Lev. XXVI, 43</span>.—[Y. Bets. I, 60ᵈ <span dir=\"rtl\">שחק הוא מרק קונדיטון</span>, read: <span dir=\"rtl\">שחיק מר קונ׳</span>, v. R. N. to Alf. <span class=\"citation\">Bets. I, 7</span>; v. <a href=\"#\" data-headword=\"קוֹנְדִּיטוֹן\">קוֹנְדִּיטוֹן</a>.]</div><div class=\"sense\"><b>Pa. מָרֵיק</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מָרַק\">same</a>, <i>to cleanse, clear, finish</i>. <span class=\"citation\">B. Mets. 15ᵃ</span> (in a deed of sale) <span dir=\"rtl\">ואשפי ואדכי וַאֲמָרֵיק וכ׳</span> (v. Rabb. D. S. a. l. note 6) and I will satisfy (all claimants) and clear and clean the property &amp;c. <span class=\"citation\">Yalk. Is. 352</span> <span dir=\"rtl\">מְמָרְקָא לה</span> to pay it, v. <a href=\"#\" data-headword=\"שְׁבַק\">שְׁבַק</a>.—Y. Keth. VI, beg. 30ᶜ, v. preced.—[<span class=\"citation\">Targ. Prov. III, 11</span> <span dir=\"rtl\">תמריק</span>, read: <span dir=\"rtl\">תְמַיֵּיק</span>; <span class=\"citation\">ib. XIX, 28</span> ממריק Ms., read: <span dir=\"rtl\">מְמַיֵּיק</span>; v. <a href=\"#\" data-headword=\"מוּק\">מוּק</a>.]</div></div><div class=\"sense\"><b>Ithpa. אִתְמָרֵיק</b> </div><div class=\"sense\"><b>Ithpe. אִתְמְרֵיק</b> <div class=\"sense\"><b>1)</b> <i>to be scoured</i>. <span class=\"citation\">Targ. O. Lev. VI, 21</span>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <span dir=\"rtl\">תמרוק</span>) <i>to be used for toilet</i>; (of persons) <i>to be perfumed</i>. <span class=\"citation\">Targ. Y. Ex. XXX, 32</span>.—[<span dir=\"rtl\">אתמורק</span>, <span class=\"citation\">Targ. II Kings IV, 35</span>, v. <a href=\"#\" data-headword=\"מְקַק\">מְקַק</a>.]</div></div>","alt":["מְרֵיק"]},"16738":{"h":"מָרְקָא","r":"M02762","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרַק\">preced.</a>; cmp. <a href=\"#\" data-headword=\"מָרוֹקָא I\">מָרוֹקָא</a>) <i>yellowish, pale</i>. <span class=\"citation\">Yeb. 80ᵃ</span> <span dir=\"rtl\">שיכרא מ׳</span> pale (diluted) beer; (Rashi, another opin.: <i>strong</i> beer).—חמרא מ׳ <i>diluted wine</i>. <span class=\"citation\">Gitt. 69ᵇ</span>, opp. <span dir=\"rtl\">חייא</span>. <span class=\"citation\">Erub. 29ᵇ</span>.—[<span class=\"citation\">B. Mets. 47ᵇ</span> Ar., v. <a href=\"#\" data-headword=\"מָרוֹקָא I\"><span dir=\"rtl\">מָרוֹקָא</span> I</a>.]</div>","alt":[]},"16739":{"h":"מָרֵקָה","r":"M02763","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָרְקָא\">preced.</a> wds.) <i>a sort of earth used for polishing</i> (cmp. <a href=\"#\" data-headword=\"גַּרְגִּשְׁתָּא\">גַּרְגִּשְׁתָּא</a> in <span class=\"citation\">Targ. Y. Lev. VI, 21</span>). <span class=\"citation\">Mikv. IX, 2</span> (Barten. <a href=\"#\" data-headword=\"מָרֵיקָא\">מָרֵיקָא</a>); <span class=\"citation\">Tosef. ib. VI</span> (<span class=\"citation\">VII), 13</span> <span dir=\"rtl\">של מָרֵיקָה</span> water mixed with <i>mareḳah</i>.—[Y. Bets. I, 60ᵈ top <span dir=\"rtl\">משום מרקה</span>, read: <a href=\"#\" data-headword=\"מֶרְקָח\">מְרַקֵּחַ</a>, v. <a href=\"#\" data-headword=\"רָקַח\">רָקַח</a>.]</div>","alt":[]},"16740":{"h":"מֶרְקוּלִיס","r":"M02764","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Mercurius</i>, name of the Roman divinity, identified with the Grecian <i>Hermes</i>; esp. <i>a statue</i> or <i>way-mark dedicated to Hermes</i> (v. Lübker Reallex. s. vv. Hermes and Hermae). <span class=\"citation\">Snh. VII, 6</span> <span dir=\"rtl\">הזורק אבן למ׳ זו היא עבודתו</span> casting a stone on a <i>merculis</i> (<i>hermaeon</i>), that is the way of worshipping it. <span class=\"citation\">Ib. 64ᵃ</span> <span dir=\"rtl\">א&quot;ל מ׳ היא</span> they said to him, it was a <i>merculis</i> (at which you cast a stone). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הזורק אבן במ׳ תנן</span> the Mishnah reads, he who casts a stone <i>on</i> a <i>m</i>. <span class=\"citation\">Ab. Zar. IV, 1</span> <span dir=\"rtl\">שלש אבנים … בצד מ׳ וכ׳</span> if three stones near one another are found by the side of a <i>m.</i>, they are forbidden for use. <span class=\"citation\">Ib. 50ᵃ</span> <span dir=\"rtl\">אבנים שנשרו מן המ׳</span> stones which have fallen off a <i>m</i>.—<span class=\"citation\">Tosef. ib. VI</span> (<span class=\"citation\">VII), 13</span> <span dir=\"rtl\">מ׳ וכל מה שעליו אסור</span> a <i>m</i>. with all that is on it is forbidden. <span class=\"citation\">Ib. 15</span>, sq. (also <a href=\"#\" data-headword=\"מֶרְקוּלִיס\">מֶרְקוּלִס</a>). Ab. Zar. l. c. <span dir=\"rtl\">עיקר מ׳</span> the original statue of, or heap of stones for, Mercurius, opp. to <span dir=\"rtl\">מ׳ קטין</span> a heap of three stones by its side; a. fr.—Abbr. <a href=\"#\" data-headword=\"קוּלִיס\">קוּלִיס</a>.—בית ק׳ <i>a way-mark dedicated to M</i>. (consisting of two stones with a third across the top). Ib.; <span class=\"citation\">B. Mets. 25ᵇ</span> (Ms. H. <a href=\"#\" data-headword=\"מֶרְקוּלִיס\">מרקוליס</a>).</div>","alt":[]},"16741":{"h":"מַרְקוֹעַ I","r":"M02765","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">מַרְקוֹעָן</span> (<a href=\"#\" data-headword=\"רְקַע\">רְקַע</a>; cmp. <a href=\"#\" data-headword=\"רָקִיק\">רָקִיק</a>) <i>thin cakes, wafers</i>. <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> [read:] <span dir=\"rtl\">טור שמעון הוה מפיק … גריבין דמ׳ ללקיטייא כל וכ׳</span> the town of Tur Simon used to distribute three hundred <i>griva</i> (of flour in) wafers among the poor on every Sabbath eve (v. <a href=\"#\" data-headword=\"*לָקִיט I\"><span dir=\"rtl\">לָקִיט</span> I</a>); <span class=\"citation\">Lam. R. to II, 2</span> גרבי דמ׳ בכל ערובה לאילין קיטיא … Ar. Compl. ed. Koh. (defective in eds.).</div>","alt":[]},"16742":{"h":"מַרְקוֹעַ II","r":"M02766","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"מַרְקַע\">מַרְקַע</a> c. (רְקַע <i>Pa</i>.) <i>piece of cloth, patch</i>. <span class=\"citation\">Y. Snh. IV, 22ᵇ</span> top <span dir=\"rtl\">איתקלף מַרְקוֹעָךְ</span> thy patch is peeling off, i.e. thy ignorance is laid bare. <span class=\"citation\">B. Bath. 20ᵃ</span> חזי למ׳ דלבושא Ms. H. a. Ar. (ed. <span dir=\"rtl\">לקריעה</span>) can be used for a patch on a garment.—Pl. <span dir=\"rtl\">מַרְקוֹעִין</span>, <span dir=\"rtl\">מַרְקְעִין</span>, <span dir=\"rtl\">מַרְקְעָן</span>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד כות׳<sup>1</sup>) <span dir=\"rtl\">עשרים וארבע מרקועין</span> (some ed. <span dir=\"rtl\">מרקע׳</span>), v. <a href=\"#\" data-headword=\"מַרְדְּעָא\">מַרְדְּעָא</a>; <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> bot. <span dir=\"rtl\">מרקען</span> ed. Amst. (ed. Krot. <a href=\"#\" data-headword=\"מַקְרְעָן\">מַקְרְעָן</a>), v. <a href=\"#\" data-headword=\"אִיסְטְוָוא II\"><span dir=\"rtl\">אִיסְטְוָוא</span> II</a>.</div>","alt":[]},"16743":{"h":"מרקוש","r":"M02767","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Sabb. XIV</span> (<span class=\"citation\">XV), 2</span>, v. <a href=\"#\" data-headword=\"טַרְכֵּשׁ\">טַרְכֵּשׁ</a></div>","alt":[]},"16744":{"h":"מֶרְקָח","r":"M02768","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>aromatic herb</i>.—Pl. <span dir=\"rtl\">מֶרְקָחִים</span>. <span class=\"citation\">Pirké d’R. El. ch. XXV</span>; <span class=\"citation\">Yalk. Gen. 84</span> <span dir=\"rtl\">בית המ׳</span> drug-store.</div>","alt":[]},"16745":{"h":"מִרְקַחַת","r":"M02769","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"מֶרְקָח\">preced.</a>) <i>druggist’s preparation, drug; poison</i>. <span class=\"citation\">Gen. R. s. 10</span> (‘Rashi’: <span dir=\"rtl\">מֶרְקְחוֹתָיו</span>, pl. of <a href=\"#\" data-headword=\"מֶלְקָחָה\">מֶרְקָחָה</a>), v. <a href=\"#\" data-headword=\"סַם\">סַם</a>.</div>","alt":[]},"16746":{"h":"מֶרְקַחְתָּא","r":"M02770","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מִרְקַחַת\">preced.</a>) <i>a spiced dish</i>. Lam. R. introd. (R. Abbahu 2) (ref. to <span class=\"citation\">Ez. XXIV, 10</span>) <span dir=\"rtl\">היה גופן תוסס כהדא מ׳</span> their bodies were bubbling (hot with grief) like a spiced broth; <span class=\"citation\">Yalk. Ez. 363</span>.</div>","alt":[]},"16747":{"h":"מרקיה","r":"M02771","html":"<div class=\"sense\">, <span class=\"citation\">Y. Bets. I, 60ᵈ</span> top, read: <a href=\"#\" data-headword=\"מֶרְקָח\">מְרַקֵּחַ</a>, v. <a href=\"#\" data-headword=\"רָקַח\">רָקַח</a></div>","alt":[]},"16748":{"h":"מַרְקַע","r":"M02772","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְקוֹעַ II\"><span dir=\"rtl\">מַרְקוֹעַ</span> II</a></div>","alt":[]},"16749":{"h":"מָרַר","r":"M02773","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to drip;</i></div><div class=\"sense\"><b>2)</b>  (cmp. <a href=\"#\" data-headword=\"אֶרֶס\">אֶרֶס</a>) <i>to be bitter</i>.—V. <a href=\"#\" data-headword=\"מוֹר\">מוֹר</a>, <a href=\"#\" data-headword=\"מַר IV\">מַר</a>, <a href=\"#\" data-headword=\"מָרוֹר\">מָרוֹר</a></div><div class=\"sense\"><b>Pi. מֵרֵר</b> <div class=\"sense\"><i>to make bitter</i>; <i>to afflict</i>. <span class=\"citation\">Pes. X, 5</span> <span dir=\"rtl\">מרור על שום שמֵרְרוּ המצרים וכ׳</span> we eat bitter herbs in memory of the Egyptians embittering the lives of our fathers in Egypt. <span class=\"citation\">Cant. R. to I, 13</span> (play on <a href=\"#\" data-headword=\"מֹר\">מֹר</a>, ib.) <span dir=\"rtl\">אברהם מְמָרֵר עצמו וכ׳</span> Abraham afflicted himself and plagued himself with sufferings; <span class=\"citation\">ib. to III, 6</span>; a. e.</div></div><div class=\"sense\"><b>Hif. הֵמַר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"מַרְקַע\">same</a>. <span class=\"citation\">Gen. R. s. 98</span> (play on <span dir=\"rtl\">וימררהו</span>, <span class=\"citation\">Gen. XLIX, 23</span>) <span dir=\"rtl\">שה׳ לאחיו</span> who made his brothers suffer; <span dir=\"rtl\">שהֵמֵירוּ לו אחיו</span> whom his brothers made suffer; <span dir=\"rtl\">שה׳ לאדונתו</span> who made his mistress suffer; <span dir=\"rtl\">שהֵמֵירָה לו אדונתו</span> (v. Matt. K.) whom his mistress made suffer. <span class=\"citation\">Sabb. 88ᵇ</span> (play on <span dir=\"rtl\">צ̇ר̇ר המ̇ר̇</span>, <span class=\"citation\">Cant. I, 13</span>) <span dir=\"rtl\">אע&quot;פ שמיצ̇ר̇ ומֵימַ֗ר̇ לי וכ׳</span> although my Beloved decrees anguish and suffering for me; a. e.</div></div><div class=\"sense\"><b>Hithpa. הִתְמָרֵר</b> </div><div class=\"sense\"><b>Nithpa. נִתְמָרֵר</b> <div class=\"sense\"><i>to become sticky and bitter</i> from handling myrrh. <span class=\"citation\">Cant. R. to I, 13</span> <span dir=\"rtl\">כל … ידיו מִתְמָרְרוֹת</span> (Matt. K. <span dir=\"rtl\">מִתְמוֹרְר׳</span>, <i>Hithpol</i>.) whoever plucks it (myrrh), gets his hands sticky (and bitter). <span class=\"citation\">Num. R. s. 13</span> (play on <a href=\"#\" data-headword=\"מורי\">מוֹרִי</a>, <span class=\"citation\">Cant. V, 1</span>) <span dir=\"rtl\">נִתְמָרְרוּ בגלות וכ׳</span> they became bitter (affected with sin) in captivity, and were sweetened (atoned for their sins) by martyrdom.</div></div><div class=\"sense\"><b>Hithpalp. הִתְמַרְמֵר</b> <div class=\"sense\">, <i>Nithpalp</i>. <a href=\"#\" data-headword=\"מָרַר\">נִתְמַרְמֵר</a> <i>to get excited</i> (in battle); <i>to be enraged</i>. <span class=\"citation\">Pesik. R. s. 29-30</span>-30 (ed. Fr., p. 140ᵃ) <span dir=\"rtl\">מיד היה מִתְמַרְמֵר וכ׳</span> at once he became enraged and kicked it (the missile) &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נתמ׳ לצאת</span> he was excited in rushing out.</div></div>","alt":[]},"16750":{"h":"מְרַר","r":"M02774","html":"<div class=\"sense\"><a href=\"#\" data-headword=\"מָרַר\">same</a>, <i>to be bitter; to grieve, mourn</i>. Perf. <a href=\"#\" data-headword=\"מַר IV\">מַר</a>, imperf. <a href=\"#\" data-headword=\"יֵימַר\">יֵימַר</a>, <a href=\"#\" data-headword=\"יָמַר\">יֵמַר</a>. <span class=\"citation\">Targ. Is. XXIV, 9</span>. <span class=\"citation\">Targ. I Sam. XXX, 6</span>; a. fr.—<span class=\"citation\">Targ. Zech. XII, 10</span> <span dir=\"rtl\">ויֵימְרוּן</span>, v. infra.</div><div class=\"sense\"><b>Pa. מָרַר</b> <div class=\"sense\"><i>to embitter, aggrieve</i>. <span class=\"citation\">Targ. Ruth I, 13</span> <span dir=\"rtl\">תְמָרְרוּן</span> (ed. Amst. <span dir=\"rtl\">תִמְרְ׳</span>). <span class=\"citation\">Targ. Y. I Deut. XXXII, 32</span> <span dir=\"rtl\">מְמַרְרִין</span> (some ed. <span dir=\"rtl\">מְמַרְרַן</span>; Y. II <span dir=\"rtl\">מַרְרַן</span>).</div></div><div class=\"sense\"><b>Af. אַמְרֵיר  אַמַּר</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"מָרַר\">same</a>. <span class=\"citation\">Targ. Ruth I, 20</span> (not <a href=\"#\" data-headword=\"מָרַר\">same</a>. <span class=\"citation\">Targ. Ruth I, 20</span> (not <span dir=\"rtl\">אֲמַרִ׳</span>). <span class=\"citation\">Targ. Ex. I, 14</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to arrange mourning</i>. <span class=\"citation\">Targ. Zech. XII, 10</span> <span dir=\"rtl\">ויימרון … כמא דמַמְרִין וכ׳</span> they shall arrange mourning for him, as is arranged for &amp;c. (v. infra).—[<span dir=\"rtl\">אָמְרָרוּ</span>, v. <i>Ithpa.</i>]</div></div><div class=\"sense\"><b>Palp. מַרְמֵר  מַרְמֵיר</b> <div class=\"sense\"><i>to aggrieve</i>. <span class=\"citation\">Targ. Prov. XVII, 25</span>. <span class=\"citation\">Targ. Y. I Gen. XLIX, 23</span> <span dir=\"rtl\">ממרירו</span>, read: <span dir=\"rtl\">מַרְמִירוּ</span>; (Y. II <span dir=\"rtl\">אֲמָרוּ</span>, read: <a href=\"#\" data-headword=\"*אֲמַרְכֹּול\">אַמָּ׳</a> <i>Af</i>.).</div></div><div class=\"sense\"><b>Ithpa. אִתְמָרֵר</b> <div class=\"sense\"><b>1)</b> <i>to be enraged, fight</i>. Targ. O. Gen. l. c. (Var. <span dir=\"rtl\">אָמְרָרוּ</span>, v. Berl. Targ. O. II, p. 18; oth. ed. <span dir=\"rtl\">אַמְרָרוּ</span> <i>Af</i>.).</div><div class=\"sense\"><b>—2)</b> <i>to mourn</i>. Targ. Zech. l. c. Var. (v. Lag. Proph. I, p. XLII).</div></div>","alt":["מְרִיר"]},"16751":{"h":"מֶרֶר","r":"M02775","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְרַר\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>bitterness; trouble;</i> במ׳ <i>bitterly</i>. <span class=\"citation\">Esth. R. to III, 9</span> (ref. to <span class=\"citation\">Is. XXXIII, 7</span>) <span dir=\"rtl\">וכל צבא … בוכים במ׳</span> all the hosts on high weep bitterly.</div><div class=\"sense\"><b>—2)</b> <i>sin</i>. <span class=\"citation\">Cant. R. to V, 5</span> (play on <span dir=\"rtl\">מור עבר</span>, ib.) <span dir=\"rtl\">עבר על מְרָרִי</span> he passed over (pardoned) my sin.—Pl. <span dir=\"rtl\">מְרָרִים</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מ׳ דגזר כורש וכ׳</span> troubles,—when Cyrus decreed and said &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מ׳ שאמרתי לעגל וכ׳</span></div>","alt":[]},"16752":{"h":"מְרָר","r":"M02776","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"מֶרֶר\">מֶרֶר</a>, <a href=\"#\" data-headword=\"מְרָמָא\">מְרָרָא</a> ch. same, </div><div class=\"sense\"><b>1)</b> <i>trouble</i>. <span class=\"citation\">Snh. 19ᵃ</span> <span dir=\"rtl\">אגב מְרָרֵיה</span> in his trouble (excitement of mourning).—במ׳ <i>bitterly</i>. <span class=\"citation\">Targ. Esth. VI, 1</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>curse</i>. <span class=\"citation\">Targ. O. Num. V, 24</span>; <span class=\"citation\">27</span>, v. <a href=\"#\" data-headword=\"מְרִירוּ\">מְרִירוּ</a>.</div><div class=\"sense\"><b>—3)</b> <i>bitter herb</i>.—Pl. <span dir=\"rtl\">מְרָרִין</span>. <span class=\"citation\">Targ. O. Ex. XII, 8</span>; a. e.; v. <a href=\"#\" data-headword=\"מְרוֹרָא\">מְרוֹרָא</a>.</div>","alt":[]},"16753":{"h":"מְרָרִיתָא","r":"M02777","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"מָרוֹר\">מָרוֹר</a>, <i>a bitter herb</i>, prob. <i>succory</i>. <span class=\"citation\">Succ. 13ᵃ</span> <span dir=\"rtl\">הני מ׳ דאגמא וכ׳</span> that succory of the marsh. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הני מ׳ סתמא שמייהו וכ׳</span> the name of that plant is plain <i>m’raritha</i>, and the reason why they name it ‘<i>m</i>. of the marsh’ is, because it is frequent in marshes. <span class=\"citation\">Pes. 39ᵃ</span> (expl. <a href=\"#\" data-headword=\"מָרוֹר\">מרור</a>) <span dir=\"rtl\">מ׳ דאגמא</span> Ms. M. (ed. only <span dir=\"rtl\">מרירתא</span>, read <span dir=\"rtl\">מררי׳</span>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הוה מהדר אמררתא</span> ed. (corr. acc., as in Tosaf. to Succ. l. c.; Ms. M. 2 <span dir=\"rtl\">אמְרַרְיָיתָא דדברא</span>) took pains to get <i>m’raritha</i> (of the field). <span class=\"citation\">Ḥull. 59ᵃ</span> top <span dir=\"rtl\">עיקרא דמרידתא</span> ed. (read as Tosaf. to Succ. l. c. <span dir=\"rtl\">דמרריתא</span>; Ar. <span dir=\"rtl\">דנוריתא</span></div>","alt":[]},"16754":{"h":"מְרֹרָה","r":"M02778","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרוֹרָה\">מְרוֹרָה</a></div>","alt":[]},"16755":{"h":"מְרַרְתָּא","r":"M02779","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְרָרִיתָא\">מְרָרִיתָא</a></div>","alt":[]},"16756":{"h":"מָרֵשׁ","r":"M02780","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"מָרֵישָׁא\">מָרֵשָׁא</a>, v. <a href=\"#\" data-headword=\"מָרֵישׁ\">מָרֵישׁ</a>, <a href=\"#\" data-headword=\"מָרֵישָׁא\"><a href=\"#\" data-headword=\"מָרֵישָׁא\">מָרֵישָׁא</a>.</a></div>","alt":[]},"16757":{"h":"מְרַשְׁוָתָא","r":"M02781","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (Syr. <a href=\"#\" data-headword=\"מְרַשְׁוָתָא\">מרשותא</a>, <span dir=\"rtl\">מרשתא</span>, P. Sm. 401; <a href=\"#\" data-headword=\"רָשַׁשׁ\">רשש</a>) <i>mortars</i>. <span class=\"citation\">Y. B. Bath. II, 13ᵇ</span> bot. [read:] <span dir=\"rtl\">מרחקא אילין מ׳ מכותליה וכ׳</span> (v. Mus. in Ar. s. v.; ed. <span dir=\"rtl\">מרשותיה</span>, read: … <span dir=\"rtl\">וָתָה</span>) to remove those mortars from the walls &amp;c. [Comment. <i>saw-mill</i> (v. <a href=\"#\" data-headword=\"מָרֵישָׁא\">מָרֵישָׁא</a>)—which corresponds neither to form nor to context.]</div>","alt":[]},"16758":{"h":"מרשיא","r":"M02782","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"מורשיא\">מורשיא</a>, v. <a href=\"#\" data-headword=\"כרפוונה\">כרפוונה</a></div>","alt":[]},"16759":{"h":"מֵרַת","r":"M02783","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵירַת\">מֵירַת</a></div>","alt":[]},"16760":{"h":"מָרַת","r":"M02784","html":"<div class=\"sense\">, <span dir=\"rtl\">מָרְתָא</span>, <span dir=\"rtl\">מָרְתָה</span>, v. <a href=\"#\" data-headword=\"מַר IV\"><span dir=\"rtl\">מַר</span> IV</a></div>","alt":[]},"16761":{"h":"מרתהן","r":"M02785","html":"<div class=\"sense\">, <span class=\"citation\">Ex. R. s. 51</span> <span dir=\"rtl\">שמואל בר מ׳</span>, read: <span dir=\"rtl\">מָרְתָה</span> or <span dir=\"rtl\">מָרְתָא</span>.</div>","alt":[]},"16762":{"h":"מַרְתּוֹקָא","r":"M02786","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָתַק\">רתק</a>) </div><div class=\"sense\"><b>1)</b>  [<i>knuckles</i>,] <i>fist</i>. <span class=\"citation\">Targ. Y. Ex. XXI, 18</span>.</div><div class=\"sense\"><b>—2)</b> <i>a blow with the fist</i>. <span class=\"citation\">Y. M. Kat. III, 83ᵇ</span> (ed. Krot. <a href=\"#\" data-headword=\"מַרְתֵּיקָא\">מַרְתֵּיקָא</a>); <span class=\"citation\">Y. Snh. VII, 25ᵇ</span> top.</div><div class=\"sense\"><b>—3)</b> <i>knocker</i> at the door. Ib.ᵈ top [read:] <span dir=\"rtl\">מאן דעליל יהיב ליה חד במרתוקה</span> whoever entered (the bath-house) struck him with the knocker, v. <a href=\"#\" data-headword=\"נְתִיקָה\">נְתִיקָה</a> ch.—V. <a href=\"#\" data-headword=\"מַרְתֵּק\">מַרְתֵּק</a>.</div>","alt":[]},"16763":{"h":"מַרְתְּחָא","r":"M02787","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְתַח\">רְתַח</a>) <i>frying pan</i>. <span class=\"citation\">Targ. Y. Lev. II, 7</span>; <span class=\"citation\">VII, 9</span> (h. text <a href=\"#\" data-headword=\"מַרְחֶשֶׁת I\">מרחשת</a>).</div>","alt":[]},"16764":{"h":"מַרְתֵּיפָא","r":"M02788","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְתֵּפָא\">מַרְתֵּפָא</a></div>","alt":[]},"16765":{"h":"מַרְתֵּיקָא","r":"M02789","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַרְתּוֹקָא\">מַרְתּוֹקָא</a></div>","alt":[]},"16766":{"h":"מָרְתְּכָא","r":"M02790","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. <i>murtakh</i>, older form of <i>murdah</i>, v. <a href=\"#\" data-headword=\"מוּרְדְּקָא\">מוּרְדְּקָא</a>) <i>litharge</i>, dross formed during the purification of silver from the lead with which it is combined. <span class=\"citation\">Gitt. 69ᵇ</span>. <span class=\"citation\">Ib. 86ᵃ</span></div>","alt":[]},"16767":{"h":"מַרְתֵּף","r":"M02791","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָתַף\">רָתַף</a>) <i>store-room, cellar</i> where vessels are stored in rows and layers. <span class=\"citation\">Pes. I, 1</span> <span dir=\"rtl\">שתי שורות על פני כל המ׳</span> the two rows of piled vessels in front of the cellar. <span class=\"citation\">Snh. 108ᵃ</span> <span dir=\"rtl\">מ׳ של חומץ</span> a store-room for vinegar. <span class=\"citation\">Lev. R. s. 24</span>, end; a. fr.</div>","alt":[]},"16768":{"h":"מַרְתֵּפָא","r":"M02792","html":"<div class=\"sense\"><a href=\"#\" data-headword=\"מַרְתֵּף\">same</a>.—Pl. <span dir=\"rtl\">מַרְתֵּפַיָּיא</span>, <span dir=\"rtl\">מַרְתֵּפַיָּיה</span>, <a href=\"#\" data-headword=\"מַרְתֵּפָא\">מַרְתֵּי׳</a>. <span class=\"citation\">Targ. I Chr. XXVII, 27</span> (h. text <a href=\"#\" data-headword=\"אֹצְרוֹת\">אֹצְרוֹת</a>).</div>","alt":["מַרְתֵּי׳"]},"16769":{"h":"מַרְתֵּק","r":"M02793","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"מַרְתּוֹקָא\">מַרְתּוֹקָא</a>, <i>blow</i>. <span class=\"citation\">Gen. R. s. 51</span> (expl. ‘from the Lord,’ <span class=\"citation\">Gen. XIX, 24</span>) <span dir=\"rtl\">כמ׳ מן גבר</span> as (we say), ‘a blow from a strong man’; Yalk. ib. 85.</div>","alt":[]},"16770":{"h":"מִשֶּׁ־","r":"M02794","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִ־\">מִ־</a></div>","alt":[]},"16771":{"h":"מְשָׁא","r":"M02795","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מְשֵׁי\">מְשֵׁי</a></div>","alt":[]},"16772":{"h":"מַשָּׂא","r":"M02796","html":"<div class=\"sense\"> m (b. h.; </div><div class=\"sense\"><b>1)</b> <i>carrying.</i> <span class=\"citation\">Kel. I, 1</span> <span dir=\"rtl\">מטמאין במ׳</span> make the carrier unclean. <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">ששוה מַגָּעוֹ למַשָּׂאוֹ</span> the touch of which has the same effect as the carrying of it; a. fr.</div><div class=\"sense\"><b>—2)</b>  מ׳ ומַתָּן <i>carrying and giving, business, dealings; worldly affairs</i>; <i>intercourse</i>. <span class=\"citation\">Sabb. 120ᵃ</span> <span dir=\"rtl\">במ׳ ומ׳</span> in worldly affairs, opp. <span dir=\"rtl\">בדברי תורה</span>. <span class=\"citation\">Kidd. 35ᵃ</span> <span dir=\"rtl\">איש דבר מ׳ ומ׳</span> a man (has the protection of the law) because he is engaged in business. <span class=\"citation\">Yoma 86ᵃ</span> <span dir=\"rtl\">מַשָּׂאוֹ ומַתָּנוֹ וכ׳</span> his dealings with men; a. fr.—<span class=\"citation\">Kidd. 30ᵇ</span> <span dir=\"rtl\">כל משאו ומתנו בך</span> he (the tempter) will always be busy with thee.</div><div class=\"sense\"><b>—3)</b> <i>burden</i>. Tanḥ. B’midb. 2, v. <a href=\"#\" data-headword=\"מַשּׂוֹא\">מַשּׂוֹא</a>.—Trnsf. <i>burden of prophecy</i>. <span class=\"citation\">Gen. R. s. 44</span> <span dir=\"rtl\">עשרה לשונות נקראת נבואה … מ׳ וכ׳</span> prophecy goes by ten names: ‘vision’ … ‘burden’ &amp;c.; <span class=\"citation\">ib.</span> <span dir=\"rtl\">רבנן אמרי מ׳ כמשמעו וכ׳</span> the Rabbis say, the severest of all is <i>massa</i>, as its name indicates (burden) &amp;c.; <span class=\"citation\">Cant. R. to III, 4</span>; a. e.—Pl. <span dir=\"rtl\">מַשָּׂאוֹת</span>. <span class=\"citation\">Gitt. 71ᵃ</span> <span dir=\"rtl\">מ׳ ומתנות</span> business transactions.</div>","alt":[]},"16773":{"h":"מֵשָׁא","r":"M02797","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵישָׁא I\">מֵישָׁא</a></div>","alt":[]},"16774":{"h":"משא","r":"M02798","html":"<div class=\"sense\">, <span class=\"citation\">Pes. 111ᵇ</span> <span dir=\"rtl\">כרו מ׳</span>, v. <a href=\"#\" data-headword=\"כְּרוּמְשָׁא\">כְּרוּמְשָׁא</a></div>","alt":[]},"16775":{"h":"מַשְּׂאוֹי","r":"M02799","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מַשּׂוֹא\">מַשּׂוֹא</a></div>","alt":[]},"16776":{"h":"מְשָׁאכָה","r":"M02800","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מְשַׁךְ I\">מְשַׁךְ</a>) <i>stretching</i>. <span class=\"citation\">B. Bath. 73ᵇ</span> <span dir=\"rtl\">מ׳ דצואריה וכ׳</span> (Ms. M. <span dir=\"rtl\">בֵּי מְשָׁכָא</span></div>","alt":[]},"16777":{"h":"מִשְׁאָלָה","r":"M02801","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>request, prayer</i>.—Pl. <span dir=\"rtl\">מִשְׁאָלוֹת</span>. <span class=\"citation\">Num. R. s. 11</span> יחנך במִשְׁאֲלוֹתֶיךָ ‘be gracious unto thee’ (<span class=\"citation\">Num. VI, 25</span>) by granting thy prayers (beyond deserts); <span class=\"citation\">Sifré Num. 41</span>; <span class=\"citation\">Yalk. ibid. 710</span>.</div>","alt":[]},"16778":{"h":"מִשְׁאַר","r":"M02802","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> constr. (<a href=\"#\" data-headword=\"שְׁאַר I\">שְׁאַר</a>) <i>the rest of, others</i>. <span class=\"citation\">Targ. Y. II, Ex. XXXV, 34</span> <span dir=\"rtl\">מ׳ אומניא</span> the other mechanics. <span class=\"citation\">Targ. Y. Num. XIX, 3</span> <span dir=\"rtl\">מ׳ בעירן</span> other (not dedicated) animals.</div>","alt":[]},"16779":{"h":"מֵשָׁארָא","r":"M02803","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מֵישְׁרָא II\"><span dir=\"rtl\">מֵישְׁרָא</span> I</a></div>","alt":[]},"16780":{"h":"מִשְׁאֶרֶת","r":"M02804","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> (b. h.; <a href=\"#\" data-headword=\"שָׁאַר\">שָׁאַר</a> <i>to swell, rise</i>; cmp. <a href=\"#\" data-headword=\"שְׂאוֹר\">שְׂאוֹר</a>) <i>baking trough</i> or <i>dish</i>. Tanḥ. Vaëra 14 (ref. to <span class=\"citation\">Ex. VII, 28</span>) <span dir=\"rtl\">אימתי מ׳ מצויה וכ׳</span> when is the trough near the oven?</div><div class=\"sense\"><b>—2)</b>  (שָׁאַר <i>to remain</i>) <i>remainder</i>.—Pl. <span dir=\"rtl\">מִשְׁאָרוֹת</span>. Mekh. Bo s. 13 (ref. to <span dir=\"rtl\">משארתם</span>, <span class=\"citation\">Ex. XII, 34</span>; v. Targ.) <span dir=\"rtl\">אלו שיורי מצה ומרור</span> that means the remnants of the unleavened bread and the bitter herbs (of the Passover meal); Tanḥ. Bo 8.</div>","alt":[]},"16781":{"h":"מִשְּׁבָא","r":"M02805","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְשַׁב\">נְשַׁב</a>) <i>bellows</i>. <span class=\"citation\">Targ. Jer. VI, 29</span> <span dir=\"rtl\">מִשַּׁב</span> constr.</div>","alt":[]},"16782":{"h":"משבזג","r":"M02806","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מוֹשָׁב\">מוֹשָׁב</a></div>","alt":[]},"16783":{"h":"מְשַׁבְּחָא","r":"M02807","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁבַח\">שְׁבַח</a>) <i>singer</i>.—Pl. <span dir=\"rtl\">מְשַׁבְּחַיָּא</span>, <span dir=\"rtl\">מְשַׁבְּחִין</span>. <span class=\"citation\">Targ. I Chr. IX, 33</span>. <span class=\"citation\">Targ. Jer. XV, 17</span> (h. text <span dir=\"rtl\">משחקים</span>).</div>","alt":[]},"16784":{"h":"מְשַׁבְּקָא I","r":"M02808","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁבַק\">שְׁבַק</a>) <i>divorcer, former husband</i>. <span class=\"citation\">Y. Keth. XI, 34ᵇ</span> bot. <span dir=\"rtl\">שכונה דמְשַׁבְּקִי</span> the neighborhood of my first husband.</div>","alt":[]},"16785":{"h":"מְשַׁבְּקָא II","r":"M02809","html":"<div class=\"sense\"> <span dir=\"rtl\">מַשְׁבַּקְתָּא</span> f. (<a href=\"#\" data-headword=\"מְשַׁבְּקָא I\">preced.</a>) <i>divorced wife</i>. <span class=\"citation\">Targ. Y. Lev. XXI, 7</span> Ar. (ed. <span dir=\"rtl\">מפטרא</span>). <span class=\"citation\">Targ. Y. Num. XXX, 10</span> Ar. (ed. <a href=\"#\" data-headword=\"מְתַרְכָא\">מתרכא</a>).—<span class=\"citation\">Gen. R. s. 17</span> מַשְׁבַּקְתֵּיה אנא I am his divorced wife; <span class=\"citation\">Lev. R. s. 34</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עם מַשְׁבַּקְתָּךְ</span> with the woman thou hast divorced; <span class=\"citation\">Yalk. Lev. 665</span> <span dir=\"rtl\">למִישַּׁבַּקְתָּךְ</span>; a. e.</div>","alt":[]},"16786":{"h":"מַשְׁבֵּר","r":"M02810","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>orifice of the matrix</i>,] (in Talm.) <i>travailing chair.</i> <span class=\"citation\">Kel. XXIII, 4</span>. <span class=\"citation\">Gen. R. s. 72</span>; <span class=\"citation\">Y. Ber. IX, 14ᵃ</span> bot. <span dir=\"rtl\">ביושבת על המ׳</span> when she is seated on the travailing chair; a. e.</div>","alt":[]},"16787":{"h":"מְשַׁבֶּשְׁתָּא","r":"M02811","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁבַשׁ\">שְׁבַשׁ</a>) <i>a faulty version, a rejected Boraitha</i>, opp. <a href=\"#\" data-headword=\"מְתָרַצְתָּא\">מְתָרַצְתָּא</a>. <span class=\"citation\">Gitt. 73ᵃ</span> (ref. to <span class=\"citation\">Tosef. ib. VII</span> (<span class=\"citation\">V), 2</span>) <span dir=\"rtl\">כיון דקשיא … ומ׳ היא</span> since there is a contradiction between the first and the second clause, it could not have been discussed at college (or an attempt to harmonize would have been recorded), and (therefore) it is to be rejected. <span class=\"citation\">Sabb. 121ᵇ</span>; a. fr.</div>","alt":[]},"16788":{"h":"מְשַׁדַּרְתָּא","r":"M02812","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁדַר I\">שְׁדַר</a>) <i>sending</i>. <span class=\"citation\">Targ. Esth. IX, 22</span> <span dir=\"rtl\">מְשַׁדְּרַת</span> quot. in Levy Targ. Dict. (ed. <span dir=\"rtl\">לשדרא</span>).</div>","alt":[]},"16789":{"h":"משֶׁה","r":"M02813","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Moses</i>, </div><div class=\"sense\"><b>1)</b>  the law-giver, often <span dir=\"rtl\">מ׳ רַבֵּינוּ</span> M. our teacher. <span class=\"citation\">Ber. 3ᵇ</span>. <span class=\"citation\">Sot. 12ᵃ</span>; a. v. fr.—<span class=\"citation\">Y. Taan. IV, beg. 67ᵇ</span>, a. e. <span dir=\"rtl\">מ׳ דאנא וכ׳</span> by Moses, I will look (at the priests) and not be diverted. <span class=\"citation\">Y. Dem. IV, 24ᵃ</span> top <span dir=\"rtl\">בדֵין הוא מימר מ׳ דאנא וכ׳</span> will he (R. Ḥaggai) in this case, too, say, by Moses, I know the reason? Said he, by M. &amp;c.; a. fr.—<span class=\"citation\">Bets. 38ᵇ</span> <span dir=\"rtl\">מ׳ שפיר קאמרית</span> by Moses, art thou right? (Rashi).—Trnsf. <i>great scholar</i> (<i>that thou art</i>)!, (mostly ironically). <span class=\"citation\">Ḥull. 93ᵃ</span>. <span class=\"citation\">Sabb. 101ᵇ</span> <span dir=\"rtl\">מ׳ שפיר קאמרת</span> great scholar, art thou really right?; Bets. l. c. (v. supra); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>M.</i> <i> Bar ‘Atsri</i>, father of R. Huna. <span class=\"citation\">B. Bath. 174ᵇ</span> <span dir=\"rtl\">מ׳ בר עצרי</span> (Ms. M. <a href=\"#\" data-headword=\"עֲצוּרִי\">עצורי</a>); <span class=\"citation\">Arakh. 23ᵃ</span></div>","alt":[]},"16790":{"h":"מַשֶּׁהוּ","r":"M02814","html":"<div class=\"sense\"> (tradit. pronunc. <a href=\"#\" data-headword=\"מַשֶּׁהוּ\">מַשְׁהוּ</a>) m. (= <span dir=\"rtl\">מַה שֶׁהוּ</span>, v. <a href=\"#\" data-headword=\"הוּא\">הוּא</a>) <i>anything, the least portion, minimum</i>. <span class=\"citation\">Targ. Y. Num. XXXV, 16</span>.—<span class=\"citation\">Sifré Num. 160</span> <span dir=\"rtl\">הברזל ממית במשהוא</span> an iron weapon may wound fatally, be it ever so small of size. <span class=\"citation\">Pes. 11ᵇ</span> <span dir=\"rtl\">שעה ומ׳</span> an hour and a fraction of an hour. <span class=\"citation\">Ḥull. 102ᵇ</span> <span dir=\"rtl\">במ׳</span> when one eats ever so little of it, opp. <span dir=\"rtl\">בכזית</span>; (ib. top <span dir=\"rtl\">בכל שהוא</span>). Ib. <span dir=\"rtl\">במ׳ בשר וכ׳</span> when one eats a little of each, flesh, sinews and bones (so as to make up the size of an olive when combined); a. v. fr.—Pl. <span dir=\"rtl\">מַשְּׁהוּיִין</span>. <span class=\"citation\">Erub. 87ᵃ</span> <span dir=\"rtl\">ושני מ׳</span> and two fractions, i.e. ten and a fraction high, and two and a fraction wide.</div>","alt":[]},"16791":{"h":"משהיג","r":"M02815","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָשְׁמָהִיג\">מָשְׁמָהִיג</a></div>","alt":[]},"16792":{"h":"מַשּׂוֹא","r":"M02816","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"מַשֹּׂוי\">מַשּׂוֹי</a>, <span dir=\"rtl\">(<a href=\"#\" data-headword=\"מַסּוֹי\">מַסּוֹי</a>) <a href=\"#\" data-headword=\"מַשְּׂאוֹי\">מַשְּׁאוֹי</a></span> m.(b. h. <i>burden, load</i>. <span class=\"citation\">Y. Dem. II, 22ᵈ</span> top <span dir=\"rtl\">אין כל א&quot;י עושה מ׳ וכ׳</span> (not <a href=\"#\" data-headword=\"עִשּׂוּי\">עשוי</a>) the whole of Palestine does not produce one load of raisins. Ib. [read:] <span dir=\"rtl\">ואין כל א&quot;י עושה מ׳ אחד של צימוקין אלא כן אמר לן אין מקום בא&quot;י עושה מסוי וכ׳</span> does the whole of Palestine not produce &amp;c.? But thus he said to us, no single place in Palestine produces &amp;c. <span class=\"citation\">Sabb. 92ᵃ</span> <span dir=\"rtl\">המוציא מ׳ למעלה וכ׳</span> he who transfers a load from one territory to another at a height from the ground of more than ten handbreadths. <span class=\"citation\">Erub. 22ᵃ</span> (ref. to <span dir=\"rtl\">אל פניו</span>, <span class=\"citation\">Deut. VII, 10</span>) <span dir=\"rtl\">כאדם שנושא מ׳ על פניו וכ׳</span> like a man who carries a burden (hanging down) over his face, and is anxious to throw it off; <span class=\"citation\">Yalk. Deut. 846</span> <span dir=\"rtl\">כאדם שיש לו מ׳</span> (add: <span dir=\"rtl\">על פניו</span>; Ms. O. Erub. l. c. <a href=\"#\" data-headword=\"מַסְוֶה\">מַסְוֶה</a>). <span class=\"citation\">Midr. Till. to Ps. XXXVIII</span> (ref. to <span class=\"citation\">Ezra IX, 6</span>) <span dir=\"rtl\">לאדם שהיה … והמ׳ עליו</span> like a man wading through a river, his feet sinking into the ground and a load on his head &amp;c.; a. fr.—Pl. <span dir=\"rtl\">מַשּׂוֹאִין</span>. Y. Dem. II, 22ᶜ <span dir=\"rtl\">הביא שלשה מ׳ וכ׳</span> if one brings three loads of provisions at a time, he is not yet considered a huckster <a href=\"#\" data-headword=\"תגר\">(תגר</a>).—Trnsf. <i>care, interest</i>. <span class=\"citation\">Y. Ber. III, beg. 5ᵈ</span> <span dir=\"rtl\">אין לו מי שישא מַשּׂוֹאוֹ</span> he has none to take from him his duty (of burying a dead relative).—Pl. as ab. <span class=\"citation\">Num. R. s. 1</span>, beg. <span dir=\"rtl\">משלח … שיהיו נושאים מַשׂוֹאֵיהֶם</span> he sends important men … to attend to their (political) affairs; (Tanḥ. B’midb. 1 <span dir=\"rtl\">מַשָּׂאָם</span>; ed. Bub. <span dir=\"rtl\">מַשּׂוֹאָן</span>).—<span dir=\"rtl\">מ׳ פנים</span> (v. <a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>) <i>respect of person, partiality.</i> <span class=\"citation\">Ab. IV, 22</span>; <span class=\"citation\">Y. Snh. VI, end, 23ᵈ</span>, sq. <span dir=\"rtl\">מ׳ פ׳ ומקח וכ׳</span> partiality and bribe-taking. <span class=\"citation\">Yeb. 79ᵃ</span> <span dir=\"rtl\">וכי מ׳ פ׳ יש בדבר</span> was there partiality shown in that case?; <span class=\"citation\">Snh. 104ᵇ</span>; a. fr.</div>","alt":[]},"16793":{"h":"מַשּׂוּאָה","r":"M02817","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>signal</i>, esp. <i>fire signal</i> announcing the New-Moon.—Pl. <span dir=\"rtl\">מַשּׂוּאוֹת</span>. <span class=\"citation\">R. Hash. II, 2</span>, sq. <span dir=\"rtl\">היו משיאין מ׳</span> they raised signals (at the stations); Tosef. ib. II (I), 2 <span dir=\"rtl\">משיאין משו׳</span> ed. (ed. Zuck. <span dir=\"rtl\">מסיעין מסעיות</span>, <span dir=\"rtl\">מסעות</span>; Var. <span dir=\"rtl\">מסיאין מסואות</span>); a. e.</div>","alt":[]},"16794":{"h":"מַשּׁוּאָה","r":"M02818","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>desolation</i>.—Pl. <span dir=\"rtl\">מַשּׁוּאוֹת</span>. <span class=\"citation\">Midr. Till. to Ps. LXXIV, 3</span> <span dir=\"rtl\">הפעמים שאמרת לנו … הרי הם עשויות מ׳</span> the steps (pilgrim’s roads) of which thou hast said to us (<span class=\"citation\">Deut. XVI, 16</span>) …, behold they have become desolations; Yalk. ib. 809.</div>","alt":[]},"16795":{"h":"משובן","r":"M02819","html":"<div class=\"sense\">, <span class=\"citation\">Bekh. 44ᵇ</span>, v. <a href=\"#\" data-headword=\"אֶשֶׁךְ\">אֶשֶׁךְ</a> a. <a href=\"#\" data-headword=\"שִׁעְבֵּז\"><a href=\"#\" data-headword=\"שִׁעְבֵּז\">שַׁעְבֵּז</a>.</a></div>","alt":[]},"16796":{"h":"*מְשַׁוְּורָא","r":"M02820","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁוַור\">שְׁוַור</a>; v. <a href=\"#\" data-headword=\"שַׁוָּור\">שַׁוָּור</a>) [<i>jumper</i>,] <i>rover, freebooter</i>.—Pl. <a href=\"#\" data-headword=\"*מְשַׁוְּורָא\">מְשַׁוְּורֵי</a>. <span class=\"citation\">Ab. Zar. 70ᵃ</span> bot. <span dir=\"rtl\">רוב מ׳ ישראל</span> Ar. (Ms. M. <a href=\"#\" data-headword=\"שיירי\">שיירי</a>, read <span dir=\"rtl\">שוורי</span>; ed. <span dir=\"rtl\">גנבי</span>) the majority of rovers (around Pumbeditha) are Jews.</div>","alt":[]},"16797":{"h":"*מַשְׁוַורְתָּא","r":"M02821","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שְׁוַור\">שְׁוַור</a>) <i>stirrup</i> (for jumping on an animal’s back). <span class=\"citation\">Snh. 64ᵇ</span> <span dir=\"rtl\">כמ׳ דפורייא</span> like the stirrup (a ring suspended from a frame) thrust over a bonfire on Purim, Ar. (Rashi: ‘like the children’s <i>leaping</i> over a bonfire’).</div>","alt":[]},"16798":{"h":"מָשׁוּחַ","r":"M02822","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָשַׁח I\"><span dir=\"rtl\">מָשַׁח</span> I</a></div>","alt":[]},"16799":{"h":"מָשׁוֹחַ","r":"M02823","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (מָשַׁח II) <i>surveyor</i>.—Pl. <span dir=\"rtl\">מָשׁוֹחוֹת</span>. <span class=\"citation\">Erub. IV, 11</span>, v. <a href=\"#\" data-headword=\"מָצָה\">מָצָה</a>. <span class=\"citation\">Kel. XIV, 3</span> <span dir=\"rtl\">יתדות המ׳</span> the surveyors’ marking pins; <span dir=\"rtl\">שלשלת של מ׳</span> their measuring chains; <span class=\"citation\">Tosef. Kel. B. Mets. II, 3</span> <a href=\"#\" data-headword=\"מוֹשִׁיחוֹת\">מושיחות</a>.</div>","alt":[]}};
